AUTH = {"Authorization": "Bearer " + TOKEN}


def check(cond, msg):
    if not cond:
        failures.append(f"{current_test}: {msg}")
        print(f"    FAIL {msg}")


def api(op, **params):
    body = json.dumps({"op": op, **params}).encode()
    req = urllib.request.Request(BASE + "/command", data=body,
                                 headers={"Content-Type": "application/json", **AUTH},
                                 method="POST")
    with urllib.request.urlopen(req, timeout=120) as r:
        return json.load(r)


def http_get(path, timeout=10):
    try:
        with urllib.request.urlopen(BASE + path, timeout=timeout) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()
    except urllib.error.URLError as e:
        return 0, {}, str(e).encode()


def wav_peak(path, start, end):
    """Hoechster |Pegel| einer gerenderten Datei im Zeitfenster [start, end) s."""
    with wave.open(path) as f:
        rate, ch, sw, n = f.getframerate(), f.getnchannels(), f.getsampwidth(), f.getnframes()
        f.setpos(min(n, int(start * rate)))
        data = f.readframes(max(0, min(n, int(end * rate)) - int(start * rate)))
    full = float(2 ** (8 * sw - 1))
    peak = 0.0
    for i in range(0, len(data) - sw + 1, sw * ch * 5):
        peak = max(peak, abs(int.from_bytes(data[i:i + sw], "little", signed=True)) / full)
    return peak


def make_wav(path, seconds=1.0, rate=44100):
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        frames = bytearray()
        for i in range(int(seconds * rate)):
            sample = int(12000 * (i % 100 < 50))  # eckiger Ton, kein Stille-Trim
            frames += struct.pack("<h", sample)
        w.writeframes(bytes(frames))


def test(name):
    def deco(fn):
        global current_test
        current_test = name
        print(f"[ {name} ]")
        fn()
        global_check()
        return fn
    return deco


def global_check():
    pass


