def run():
    # UNIDAW_TESTS=a,b: nur diese Tests (beim Entwickeln; vor dem Commit alle)
    only = [n for n in os.environ.get("UNIDAW_TESTS", "").split(",") if n]
    if "ml" in only:   # UNIDAW_TESTS=...,ml: die ML-Trenn-Tests (pre-push-Hook)
        only += ML_TESTS
    skip_ml = os.environ.get("UNIDAW_SKIP_ML") == "1"
    # UNIDAW_GROUP=A|B: nur diese Gruppe (tests/run.sh, parallel); leer = alle
    group = os.environ.get("UNIDAW_GROUP", "")
    unknown = set(GROUP_B) - {n for n, _ in TESTS}
    if unknown:
        failures.append(f"GROUP_B: unbekannte Tests {sorted(unknown)}")
    results = []
    for name, fn in TESTS:
        if only and name not in only:
            continue
        if group and (name in GROUP_B) != (group == "B"):
            continue
        if skip_ml and name in ML_TESTS:
            print(f"[ {name} ]\n    skip (UNIDAW_SKIP_ML: no ML code in this commit, runs before push)", flush=True)
            continue
        global current_test
        current_test = name
        before = len(failures)
        start = time.monotonic()
        print(f"[ {name} ]", flush=True)
        try:
            fn()
        except Exception as e:
            import traceback
            where = [l.strip() for l in traceback.format_exc().splitlines() if l.strip().startswith('File "') and "run_tests.py" in l]
            failures.append(f"{name}: exception {e}")
            print(f"    FAIL exception {e} ({where[-1] if where else '?'})")
        ok = len(failures) == before
        results.append((name, ok))
        # Dauer je Test: Grundlage, um die Suite schneller zu machen
        print(f"    {'ok' if ok else 'FAILED'} ({time.monotonic() - start:.1f} s)", flush=True)
        # Instanz weg: abbrechen statt alle weiteren Tests in "Connection
        # refused" laufen zu lassen, mit dem Ende ihres stderr
        if INSTANCE_PROC is not None and INSTANCE_PROC.poll() is not None:
            failures.append(f"{name}: dawd test instance exited (code {INSTANCE_PROC.returncode}), remaining tests not run")
            print(f"    dawd test instance exited (code {INSTANCE_PROC.returncode}) — end of unidaw.err:")
            print_err_tail()
            break
    return results


def print_err_tail(lines=30):
    try:
        with open(INSTANCE_ERR, errors="replace") as f:
            for line in f.readlines()[-lines:]:
                print("      " + line.rstrip())
    except OSError:
        pass


TESTS = []


def t(name):
    def deco(fn):
        TESTS.append((name, fn))
        return fn
    return deco


