def make_mid(path):
    """Minimal-SMF mit 4 Noten (C4/E4/G4/C5, 120 bpm)."""
    def varlen(n):
        out = [n & 0x7f]
        n >>= 7
        while n:
            out.append((n & 0x7f) | 0x80)
            n >>= 7
        return bytes(reversed(out))

    events = []
    for pitch, start, dur in [(60, 0, 240), (64, 240, 240), (67, 480, 240), (72, 720, 480)]:
        events.append((start, bytes([0x90, pitch, 100])))
        events.append((start + dur, bytes([0x80, pitch, 0])))
    events.sort()
    data = b""
    last = 0
    for tick, msg in events:
        data += varlen(tick - last) + msg
        last = tick
    data += varlen(0) + b"\xff\x2f\x00"
    smf = (b"MThd" + struct.pack(">IHHH", 6, 0, 1, 480)
           + b"MTrk" + struct.pack(">I", len(data)) + data)
    with open(path, "wb") as f:
        f.write(smf)


def _raw(method, path, headers, body=b"", port=None):
    """Anfrage mit genau diesen Headern (auch ohne Host) -> (Status, JSON oder Text)."""
    import socket
    head = "".join(f"{k}: {v}\r\n" for k, v in headers.items())
    s = socket.create_connection(("127.0.0.1", port or PORT), timeout=30)
    s.sendall(f"{method} {path} HTTP/1.1\r\n{head}Content-Length: {len(body)}\r\n\r\n".encode() + body)
    data = b""
    while True:
        chunk = s.recv(65536)
        if not chunk:
            break
        data += chunk
    s.close()
    status = int(data.split(b" ", 2)[1]) if data.startswith(b"HTTP/") else 0
    text = data.split(b"\r\n\r\n", 1)[-1].decode(errors="replace")
    try:
        return status, json.loads(text)
    except ValueError:
        return status, text


@t("api_guard_flow")
def _():
    # localhost-API absichern (Todo 2026-11-18-localhost-api-absichern):
    # Host nur 127.0.0.1/localhost mit Port, Origin nur die eigene UI oder
    # keiner, jeder POST mit dem Token der Sitzung
    host = f"127.0.0.1:{PORT}"
    cmd = json.dumps({"op": "ping"}).encode()
    bearer = "Bearer " + TOKEN

    status, r = _raw("POST", "/command", {"Host": host, "Authorization": bearer}, cmd)
    check(status == 200 and r.get("ok") is True, f"mit Token: {status} {r}")
    status, r = _raw("POST", "/command", {"Host": f"localhost:{PORT}", "Authorization": bearer,
                                          "Origin": f"http://localhost:{PORT}"}, cmd)
    check(status == 200 and r.get("ok") is True, f"localhost mit eigener Origin: {status} {r}")
    status, r = _raw("POST", "/command", {"Host": host, "Authorization": bearer,
                                          "Origin": f"http://127.0.0.1:{PORT}"}, cmd)
    check(status == 200 and r.get("ok") is True, f"eigene UI als Origin: {status} {r}")

    # Ohne/mit falschem Token: 401, der Befehl laeuft nicht (quit beendete
    # sonst die Instanz)
    quit_ = json.dumps({"op": "quit"}).encode()
    for name, h in (("ohne Token", {"Host": host}),
                    ("falscher Token", {"Host": host, "Authorization": "Bearer " + "0" * len(TOKEN)}),
                    ("kuerzerer Token", {"Host": host, "Authorization": bearer[:-1]}),
                    ("ohne Bearer", {"Host": host, "Authorization": TOKEN})):
        status, r = _raw("POST", "/command", h, quit_)
        check(status == 401 and r.get("ok") is False and "token" in r.get("error", ""),
              f"{name}: 401 {status} {r}")
    check(api("ping").get("ok") is True, "quit ohne Token lief nicht")
    status, r = _raw("POST", "/upload?name=guard.wav", {"Host": host}, b"\x00\x01")
    check(status == 401 and r.get("ok") is False, f"Upload ohne Token: {status} {r}")
    check(not os.path.exists(os.path.join(os.path.dirname(INSTANCE_ERR), "config", "references", "guard.wav")),
          "Upload ohne Token schreibt keine Datei")

    # Fremde Website: einfacher POST mit ihrer Origin, auch mit Token
    status, r = _raw("POST", "/command", {"Host": host, "Origin": "http://evil.example",
                                          "Content-Type": "text/plain"}, quit_)
    check(status == 403 and "origin" in r.get("error", ""), f"fremde Origin ohne Token: {status} {r}")
    status, r = _raw("POST", "/command", {"Host": host, "Origin": "http://evil.example", "Authorization": bearer}, cmd)
    check(status == 403 and "origin" in r.get("error", ""), f"fremde Origin mit Token: {status} {r}")
    status, r = _raw("POST", "/command", {"Host": host, "Origin": "null", "Authorization": bearer}, cmd)
    check(status == 403, f"Origin null: {status} {r}")
    status, r = _raw("POST", "/command", {"Host": host, "Origin": f"http://127.0.0.1:{PORT + 5}",
                                          "Authorization": bearer}, cmd)
    check(status == 403, f"anderer Port als Origin: {status} {r}")

    # DNS-Rebinding: der Browser schickt den fremden Namen als Host — auch
    # die UI (sie traegt den Token) und /audio antworten nicht
    for path in ("/ui", "/", "/health", "/progress", "/audio?path=/etc/hostname"):
        status, r = _raw("GET", path, {"Host": f"evil.example:{PORT}"})
        check(status == 403 and "host" in str(r) and TOKEN not in str(r), f"fremder Host {path}: {status} {r}")
    for bad in (f"127.0.0.1:{PORT + 5}", "127.0.0.1", f"127.0.0.2:{PORT}"):
        status, r = _raw("POST", "/command", {"Host": bad, "Authorization": bearer}, cmd)
        check(status == 403, f"Host {bad}: {status} {r}")
    status, r = _raw("POST", "/command", {"Authorization": bearer}, cmd)
    check(status == 403 and "host" in r.get("error", ""), f"ohne Host: {status} {r}")
    status, r = _raw("GET", "/health", {"Host": f"LocalHost:{PORT}"})
    check(status == 200, f"localhost gross geschrieben: {status} {r}")

    # Die UI bekommt den Token als meta-Tag; GETs ohne Token gehen
    status, html = _raw("GET", "/ui", {"Host": host})
    check(status == 200 and f'<meta name="dawd-token" content="{TOKEN}">' in html, "UI traegt den Token")
    check(http_get("/health")[0] == 200 and http_get("/progress")[0] == 200, "GET ohne Token")

    # Token-Datei der Suite-Instanz: <config>/api-token-<port>, nur fuer den Nutzer
    tf = os.path.join(os.path.dirname(INSTANCE_ERR), "config", f"api-token-{PORT}")
    check(os.path.exists(tf) and oct(os.stat(tf).st_mode & 0o777) == "0o600", f"Token-Datei 0600: {tf}")
    check(os.path.exists(tf) and open(tf).read() == TOKEN, "Token-Datei = UNIDAW_TOKEN")

    # Ohne UNIDAW_TOKEN: Zufalls-Token je Start, Datei 0600; ein zweiter Start
    # auf dem belegten Port laesst sie stehen; nach quit ist sie weg
    port = PORT + 1
    run_dir = tempfile.mkdtemp(prefix="dawd-guard-run-")
    env = {k: v for k, v in os.environ.items() if k != "UNIDAW_TOKEN"}
    args = [os.path.abspath(UNIDAW_BIN), "--port", str(port), "--log", "events.jsonl", "--config", "config",
            "--interface-sim", "--no-audio"]
    proc = subprocess.Popen(args, cwd=run_dir, env=env, stdout=subprocess.DEVNULL,
                            stderr=open(os.path.join(run_dir, "unidaw.err"), "w"), start_new_session=True)
    tf = os.path.join(run_dir, "config", f"api-token-{port}")
    try:
        check(_wait_health(port), "Instanz startet")
        tok = open(tf).read() if os.path.exists(tf) else ""
        check(re.fullmatch(r"[0-9a-f]{64}", tok) is not None and tok != TOKEN, f"Zufalls-Token: {tok!r}")
        check(oct(os.stat(tf).st_mode & 0o777) == "0o600", "Datei 0600")
        status, r = _raw("POST", "/command", {"Host": f"127.0.0.1:{port}", "Authorization": "Bearer " + tok},
                         cmd, port=port)
        check(status == 200 and r.get("ok") is True, f"Befehl mit dem Token aus der Datei: {status} {r}")
        status, r = _raw("POST", "/command", {"Host": f"127.0.0.1:{port}", "Authorization": bearer}, cmd, port=port)
        check(status == 401, f"Token einer anderen Instanz: {status} {r}")
        second = subprocess.run(args, cwd=run_dir, env=dict(env, UNIDAW_TOKEN="x" * 64), stdout=subprocess.DEVNULL,
                                stderr=subprocess.DEVNULL, timeout=60)
        check(second.returncode != 0 and open(tf).read() == tok,
              f"zweiter Start auf belegtem Port aendert die Datei nicht: {second.returncode}")
        status, r = _raw("POST", "/command", {"Host": f"127.0.0.1:{port}", "Authorization": "Bearer " + tok},
                         quit_, port=port)
        proc.wait(timeout=30)
        check(not os.path.exists(tf), "Datei nach quit weg")
    finally:
        if proc.poll() is None:
            proc.kill()
            proc.wait()


