@t("upload_binary_and_collision")
def _():
    data = open(WAV, "rb").read()
    req = urllib.request.Request(BASE + "/upload?name=take.wav", data=data, headers=AUTH, method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        r1 = json.load(r)
    check(r1.get("ok") is True, f"upload ok: {r1}")
    f1 = r1.get("file", "")
