@t("insert_flow")
def _():
    # Section ist Pflicht: erst die Section (Node-Aktion), dann der Clip in sie.
    # Die Auto-Section des Seeds ("Section 1", 0-30) liegt schon da — die neue
    # startet hinten danach.
    sec = api("addSection", name="Seed", length=2.0)
    check(sec.get("ok") is True, f"addSection: {sec}")
    sec_start = sec.get("start")

    up = os.path.join(PROJECT, "media")
    media_file = os.path.join(up, "take.wav")
    r = api("addClip", track=0, file=media_file, section="Seed")
    check(r.get("ok") is True, f"addClip ok: {r}")
    check(r.get("length", 0) > 0.9, f"addClip length: {r.get('length')}")
    check(r.get("section") == "Seed" and abs(r.get("start", -1) - sec_start) < 0.01,
          f"clip starts at section start: {r}")
    # Der Insert wird eine Lane des Zieltracks (track = Lane, laneOf = Ziel)
    check(r.get("track") == 1 and r.get("laneOf") == 0, f"insert as lane: {r}")

    n = api("treeState")["nodes"][0]
    check(n["acted"] is True, "node acted after insert")
    # Erste Aktion war die Section (keine Audio-Datei) — actionFile bleibt leer
    check(n["actionFile"] == "", f"actionFile: {n['actionFile']}")
    # actedBy meldet, wodurch acted gesetzt wurde (die erste Aktion am Node)
    check(n["actedBy"] == "addSection", f"actedBy: {n['actedBy']}")
    # Take-Daten für den + Button: Typ, Section und Zieltrack des Inserts
    check(n["takeType"] == "audio", f"takeType: {n['takeType']}")
    check(n["takeSection"] == "Seed", f"takeSection: {n['takeSection']}")
    check(n["takeTrack"] == 0, f"takeTrack: {n['takeTrack']}")

    s = api("state")
    check(s["tracks"] == 2 and s["clips"] == 1 and s["length"] > 0.9,
          f"state after insert: {s}")

    # clipPeaks: Waveform des Inserts fuer die Clip-Anzeige (read-only)
    lane = next(t for t in s["trackList"] if t["dest"] == 0)
    v0 = s["version"]
    pk = api("clipPeaks", track=lane["index"], name=lane["clips"][0]["name"], buckets=50)
    check(pk.get("ok") is True and pk.get("type") == "audio" and len(pk.get("peaks", [])) == 50,
          f"clipPeaks audio: {pk}")
    check(max(pk.get("peaks", [0])) > 0.01, f"clipPeaks has signal: {pk.get('peaks')}")
    check(pk.get("version") == v0, "clipPeaks is read-only")
    r = api("clipPeaks", track=lane["index"], name="Nope")
    check(r.get("ok") is False and "no such clip" in r.get("error", ""), f"clipPeaks unknown clip: {r}")


@t("state_trackList")
def _():
    s = api("state")
    tl = s.get("trackList")
    check(isinstance(tl, list) and len(tl) == 2, f"trackList: {s}")

    tr = tl[0]
    check(tr.get("index") == 0, f"track index: {tr}")
    check(isinstance(tr.get("name"), str) and tr.get("name") != "", f"track name: {tr}")
    check(tr.get("type") == "audio", f"track type: {tr}")
    # Gruppenspur bleibt leerer Bus — der Clip lebt in der Lane
    check(len(tr.get("clips", [])) == 0, f"group track empty: {tr}")

    lane = tl[1]
    check(lane.get("dest") == 0, f"lane routes into track: {lane}")
    clips = lane.get("clips", [])
    check(len(clips) == 1, f"one clip: {lane}")
    c = clips[0]
    sec_start = next(x["start"] for x in s.get("sections", []) if x["name"] == "Seed")
    check(abs(c.get("start", -1) - sec_start) < 0.01, f"clip start: {c}")
    check(c.get("length", 0) > 0.9, f"clip length: {c}")
    check(c.get("type") == "audio", f"clip type: {c}")
    check(c.get("name") == "take", f"clip name: {c}")


