    # Node 2 ist current; Aktion an Node 2
    r = api("addClip", track=0, file=os.path.join(PROJECT, "media", "take.wav"), section="Seed", start=0, newLane=True)
    check(r.get("ok") is True, f"addClip at node 2: {r}")
