    # Reset der eigenen Node geht
    r = api("treeReset", node=2)
    check(r.get("ok") is True, f"reset own node: {r}")
    n2 = [x for x in api("treeState")["nodes"] if x["id"] == 2][0]
    check(n2["acted"] is False, "node 2 fresh again")


