@t("midi_record_flow")
def _():
    # MIDI-Aufnahme über den ALSA-Midi-Through-Loopback (Client 14:0) — läuft
    # headless. Ohne aplaymidi oder seq-Device elegant aussteigen.
    if shutil.which("aplaymidi") is None or not os.path.exists("/dev/snd/seq"):
        print("    skip (no aplaymidi or /dev/snd/seq)")
        return
    ports = subprocess.run(["aplaymidi", "-l"], capture_output=True, text=True,
                           timeout=10).stdout
    if "14:0" not in ports:
        print("    skip (no Midi Through port)")
        return

    mid = os.path.join(PROJECT, "notes.mid")
    make_mid(mid)

    # Section ist Pflicht: hinter die letzte Section ans Ende (Auto-Section
    # und die Seed-Section aus insert_flow liegen davor)
    prev_end = max((x["end"] for x in api("state").get("sections", [])), default=0.0)
    r = api("addSection", name="Midi", length=8.0, position="last")
    check(r.get("ok") is True, f"addSection: {r}")
    check(abs(r.get("start", -1) - prev_end) < 0.01 and abs(r.get("end", -1) - prev_end - 8.0) < 0.01,
          f"last section after the others: {r}")

    # MIDI-Spur vorab durch ein Instrument bis Main routen — ohne Routing
    # bleibt sie stumm (Routing-Matrix: kein Default-Instrument), und der
    # Take-Render fuer Listen-to-take braucht hoerbares Audio
    r = api("createTrack", type="midi")
    check(r.get("ok") is True, f"createTrack midi: {r}")
    mt = r["index"]
    r = api("addPlugin", name="4OSC", track=mt, at="end")
    check(r.get("ok") is True and r.get("class") == "instrument", f"4OSC ans Ende der MIDI-Spur: {r}")
    r = api("connect", **{"from": r["id"], "to": "main"})
    check(r.get("ok") is True, f"Instrument auf Main: {r}")

    r = api("record", on=True, type="midi", section="Midi", track=mt)
    check(r.get("ok") is True, f"record midi start: {r}")
    check(r.get("type") == "midi", f"record type: {r}")
    check(r.get("section") == "Midi", f"record section: {r}")

    # Section anlegen während der Aufnahme ist blockiert
    r = api("addSection", name="Nope", length=1.0)
    check(r.get("ok") is False and r.get("error") == "recording in progress",
          f"addSection while recording: {r}")

    # Erster Arm auf frischer Instanz: Rescan + ALSA-Verbindung brauchen ~1 s,
    # sonst fallen die ersten Noten vor der Verbindung.
    time.sleep(1)
    subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)
    time.sleep(1)

    r = api("record", on=False)
    check(r.get("ok") is True, f"record midi stop: {r}")
    check(r.get("notes", 0) >= 4, f"midi notes recorded: {r}")

    # MIDI-Take wird als WAV gerendert — Listen-to-take braucht eine Datei,
    # und sie liegt im Projektordner (wie Audio-Takes), nicht im CWD
    check(len(r.get("files", [])) > 0, f"midi take wav rendered: {r}")
    check(r.get("files") and os.path.dirname(r["files"][0]) == PROJECT,
          f"midi take in project dir: {r.get('files')}")

    # Take-Daten für den + Button — der Record-Stop setzt Typ, Section, Track
    n = [x for x in api("treeState")["nodes"] if x["id"] == api("treeState")["current"]][0]
    check(n["takeType"] == "midi", f"takeType after record: {n['takeType']}")
    check(n["takeSection"] == "Midi", f"takeSection after record: {n['takeSection']}")
    check(n["takeTrack"] >= 0, f"takeTrack after record: {n['takeTrack']}")

    # Die Take-Lane ist eine MIDI-Spur (erbt den Typ der Gruppe)
    s = api("state")
    check(s.get("trackTypes", [])[-1] == "midi", f"trackTypes: {s.get('trackTypes')}")

    # trackList meldet die MIDI-Spur mit ihrem Clip (lineare Ansicht)
    tl = s.get("trackList", [])
    check(tl and tl[-1].get("type") == "midi", f"trackList midi track: {tl}")
    mclips = tl[-1].get("clips", []) if tl else []
    check(len(mclips) == 1 and mclips[0].get("type") == "midi"
          and mclips[0].get("length", 0) > 0, f"trackList midi clip: {mclips}")

    # Take zurückgeben (lastTake meldet die Notenzahl)
    r = api("lastTake")
    check(r.get("ok") is True and r.get("notes", 0) >= 4, f"lastTake midi: {r}")

    r = api("render", file=os.path.join(PROJECT, "midi-render.wav"))
    check(r.get("ok") is True, f"render midi: {r}")

    # Löschen läuft nur über den node reset — der wirft die Artefakte der
    # Node (die Midi-Section und den Take) weg
    r = api("treeReset", node=api("treeState")["current"])
    check(r.get("ok") is True, f"treeReset midi take: {r}")
    s = api("state")
    check(s.get("clips") == 0, f"midi clip gone: {s}")


@t("monitor_flow")
def _():
    # Monitor armt den Input ohne Aufnahme — Hören vor dem Record. Läuft über
    # den gleichen Loopback-Weg wie midi_record_flow.
    if shutil.which("aplaymidi") is None or not os.path.exists("/dev/snd/seq"):
        print("    skip (no aplaymidi or /dev/snd/seq)")
        return
    ports = subprocess.run(["aplaymidi", "-l"], capture_output=True, text=True,
                           timeout=10).stdout
    if "14:0" not in ports:
        print("    skip (no Midi Through port)")
        return

    # Frische Edit ohne Ziel — der Monitor erzeugt die MIDI-Spur
    api("newEdit", path=os.path.join(PROJECT, "monitor-test.tracktionedit"))
    s = api("state")
    check(s.get("monitor") is False, f"monitor off initially: {s}")

    r = api("addSection", name="Take", length=6.0)
    check(r.get("ok") is True, f"addSection: {r}")

    r = api("monitor", on=True, type="midi")
    check(r.get("ok") is True, f"monitor on: {r}")
    check(r.get("monitor") is True, f"monitor flag: {r}")

    s = api("state")
    check(s.get("monitor") is True, f"state monitor: {s}")
    # Frische Edit hat keine Spur; der Monitor erzeugt die MIDI-Spur als erste
    check(s.get("tracks") == 1 and s.get("trackTypes", [])[-1] == "midi",
          f"monitor created midi track: {s}")

    mid = os.path.join(PROJECT, "notes.mid")
    make_mid(mid)
    subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)

    # Record ohne track-Param: Aufnahme in einer Lane der geärmten Spur
    r = api("record", on=True, type="midi", section="Take")
    check(r.get("ok") is True, f"record on monitored track: {r}")
    check(r.get("track") == 1, f"record in lane of monitored track: {r}")

    # Re-Arm der Lane braucht einen Moment — sonst fällt die erste Note vor
    # der Verbindung (wie beim ersten Arm in midi_record_flow)
    time.sleep(0.3)
    subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)
    time.sleep(0.5)
    r = api("record", on=False)
    check(r.get("ok") is True and r.get("notes", 0) >= 4, f"record on monitored: {r}")

    # Monitor aus: Ziel weg, nächste Aufnahme erzeugt wieder eine neue Spur
    r = api("monitor", on=False)
    check(r.get("ok") is True and r.get("monitor") is False, f"monitor off: {r}")
    s = api("state")
    check(s.get("monitor") is False, f"state monitor off: {s}")


@t("section_flow")
def _():
    # Frische Edit — die erste Section entfällt die Positionswahl: startet bei 0
    api("newEdit", path=os.path.join(PROJECT, "sections-test.tracktionedit"))

    r = api("addSection", name="Verse", length=3.0)
    check(r.get("ok") is True, f"addSection first: {r}")
    check(abs(r.get("start", -1)) < 0.01 and abs(r.get("end", -1) - 3.0) < 0.01,
          f"first section starts at 0: {r}")

    secs = api("state").get("sections", [])
    check(len(secs) == 1 and secs[0]["name"] == "Verse", f"sections: {secs}")

    # Weitere Section ans Ende: startet am Ende der letzten
    r = api("addSection", name="Chorus", length=2.0, position="last")
    check(r.get("ok") is True, f"addSection last: {r}")
    check(abs(r.get("start", -1) - 3.0) < 0.01 and abs(r.get("end", -1) - 5.0) < 0.01,
          f"last section range: {r}")

    # Clip in die Section — später prüfen, dass er mitrutscht
    r = api("addClip", track=0, file=WAV, section="Verse")
    check(r.get("ok") is True, f"addClip into section: {r}")
    check(abs(r.get("start", -1)) < 0.01, f"clip at section start: {r}")

    # Section an den Anfang: spätere Sections und Clips rücken nach rechts
    r = api("addSection", name="Intro", length=1.0, position="first")
    check(r.get("ok") is True, f"addSection first-pos: {r}")

    s = api("state")
    secs = s.get("sections", [])
    check([x["name"] for x in secs] == ["Intro", "Verse", "Chorus"], f"order: {secs}")
    check(abs(secs[0]["end"] - 1.0) < 0.01 and abs(secs[1]["start"] - 1.0) < 0.01
          and abs(secs[1]["end"] - 4.0) < 0.01 and abs(secs[2]["end"] - 6.0) < 0.01,
          f"shifted ranges: {secs}")
    tl = s.get("trackList", [])
    clips = [c for t in tl for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"] - 1.0) < 0.01,
          f"clip shifted with section: {clips}")

    # Section zwischen zwei: hinter Intro — Verse rückt weiter
    r = api("addSection", name="Break", length=1.0, position="after", after="Intro")
    check(r.get("ok") is True, f"addSection after: {r}")
    check(abs(r.get("start", -1) - 1.0) < 0.01 and abs(r.get("end", -1) - 2.0) < 0.01,
          f"between range: {r}")

    s = api("state")
    secs = s.get("sections", [])
    check([x["name"] for x in secs] == ["Intro", "Break", "Verse", "Chorus"],
          f"order after insert: {secs}")
    check(abs(secs[2]["start"] - 2.0) < 0.01 and abs(secs[2]["end"] - 5.0) < 0.01,
          f"Verse shifted further: {secs[2]}")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"] - 2.0) < 0.01,
          f"clip still in its section: {clips}")

    r = api("addSection", name="Verse", length=2.0)
    check(r.get("ok") is False and "exists" in r.get("error", ""), f"duplicate name: {r}")

    r = api("addSection", name="X", length=0.0)
    check(r.get("ok") is False, f"zero length: {r}")

    r = api("addSection", name="X", length=2.0, position="after", after="NichtDa")
    check(r.get("ok") is False and "no such section" in r.get("error", ""),
          f"unknown after: {r}")

    r = api("addSection", name="X", length=2.0, position="schwebend")
    check(r.get("ok") is False and "position" in r.get("error", ""), f"bad position: {r}")

    # Ohne Namen/Laenge/Farbe: Defaults — "Section N", 30 s, Palette-Farbe
    r = api("addSection")
    check(r.get("ok") is True and r.get("name") == "Section 1", f"default name: {r}")
    check(abs(r.get("length", -1) - 30.0) < 0.01, f"default length: {r}")
    check(r.get("color", "").startswith("#") and len(r.get("color", "")) == 7,
          f"default colour: {r}")

    r2 = api("addSection")
    check(r2.get("ok") is True and r2.get("name") == "Section 2", f"default name 2: {r2}")
    check(r2.get("color") != r.get("color"), f"distinct colours: {r.get('color')} / {r2.get('color')}")


@t("move_section_flow")
def _():
    # Verschieben: die Section wandert in die Reihenfolge — alle Sections
    # liegen danach lueckenlos ab 0, die Clips wandern mit ihren Sections mit
    api("newEdit", path=os.path.join(PROJECT, "move-test.tracktionedit"))
    api("addSection", name="A", length=3.0)
    api("addSection", name="B", length=3.0, position="last")
    api("addSection", name="C", length=3.0, position="last")

    r = api("addClip", track=0, file=WAV, section="A")
    check(r.get("ok") is True, f"clip in A: {r}")

    # C an den Anfang: A und B ruecken nach rechts, der Clip wandert mit A
    r = api("moveSection", name="C", position="first")
    check(r.get("ok") is True, f"moveSection first: {r}")
    s = api("state")
    secs = s.get("sections", [])
    check([x["name"] for x in secs] == ["C", "A", "B"], f"order: {secs}")
    check(abs(secs[0]["end"] - 3.0) < 0.01 and abs(secs[1]["start"] - 3.0) < 0.01
          and abs(secs[2]["end"] - 9.0) < 0.01, f"compact ranges: {secs}")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"] - 3.0) < 0.01,
          f"clip moved with its section: {clips}")

    # B zwischen C und A
    r = api("moveSection", name="B", position="after", after="C")
    check(r.get("ok") is True, f"moveSection after: {r}")
    s = api("state")
    secs = s.get("sections", [])
    check([x["name"] for x in secs] == ["C", "B", "A"], f"order after move: {secs}")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"] - 6.0) < 0.01,
          f"clip still with A: {clips}")

    r = api("moveSection", name="NichtDa", position="first")
    check(r.get("ok") is False and "no such section" in r.get("error", ""), f"unknown section: {r}")
    r = api("moveSection", name="A", position="schwebend")
    check(r.get("ok") is False and "position" in r.get("error", ""), f"bad position: {r}")
    r = api("moveSection", name="A", position="after", after="NichtDa")
    check(r.get("ok") is False and "no such section" in r.get("error", ""), f"unknown after: {r}")


@t("update_section_colour")
def _():
    # Farbe aendern: Hex am Op, im Edit und im state
    api("newEdit", path=os.path.join(PROJECT, "colour-test.tracktionedit"))
    r = api("addSection", name="S", length=2.0)
    check(r.get("ok") is True, f"section: {r}")

    r = api("updateSection", name="S", color="#ff5733")
    check(r.get("ok") is True and r.get("color") == "#FF5733", f"colour set: {r}")
    s = api("state")
    check(s.get("sections", [])[0].get("color") == "#FF5733", f"colour in state: {s}")

    r = api("updateSection", name="S", color="keinefarbe")
    check(r.get("ok") is False, f"invalid colour rejected: {r}")


@t("resize_section")
def _():
    # Kanten ziehen: am Ende wandern alle folgenden Sections und ihre Clips
    # mit (keine Luecken im Arrangement); am Anfang ist die Grenze zwischen
    # den Sections — die erste Section startet fix bei 0
    api("newEdit", path=os.path.join(PROJECT, "resize-test.tracktionedit"))
    api("addSection", name="A", length=3.0)
    api("addSection", name="B", length=3.0, position="last")

    r = api("addClip", track=0, file=WAV, section="B")
    check(r.get("ok") is True, f"clip in B: {r}")

    # Ende von A kuerzen: B und ihr Clip wandern mit
    r = api("updateSection", name="A", length=2.0)
    check(r.get("ok") is True and abs(r.get("end", -1) - 2.0) < 0.01, f"shorten A: {r}")
    s = api("state")
    secs = s.get("sections", [])
    check(abs(secs[1]["start"] - 2.0) < 0.01, f"B follows: {secs}")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"] - 2.0) < 0.01, f"clip follows B: {clips}")

    # Ende von A laenger: B wandert weiter
    r = api("updateSection", name="A", length=2.5)
    check(r.get("ok") is True, f"extend A: {r}")
    s = api("state")
    check(abs(s.get("sections", [])[1]["start"] - 2.5) < 0.01, f"B follows longer: {s}")

    # Start der ersten Section: fix bei 0
    r = api("updateSection", name="A", start=1.0)
    check(r.get("ok") is False and "first section" in r.get("error", ""),
          f"first section fixed: {r}")

    # Grenze zwischen A und B ziehen: A endet dort, B startet dort — das
    # Ende von B bleibt (Länge aendert sich), keine Luecke
    r = api("updateSection", name="B", start=2.0)
    check(r.get("ok") is True and abs(r.get("start", -1) - 2.0) < 0.01, f"boundary: {r}")
    s = api("state")
    secs = s.get("sections", [])
    check(abs(secs[0]["end"] - 2.0) < 0.01 and abs(secs[1]["start"] - 2.0) < 0.01
          and abs(secs[1]["end"] - 5.5) < 0.01, f"boundary applied: {secs}")


@t("section_record_flow")
def _():
    # Aufnahme in eine Section (seit 2026-10-24 nicht mehr punch-bounded):
    # sie beginnt am Section-Anfang und laeuft bis zum Stopp, auch ueber das
    # Section-Ende; reicht der Take hinter die letzte Section, entsteht beim
    # Stopp eine Auto-Section. MIDI über den Loopback (headless).
    if shutil.which("aplaymidi") is None or not os.path.exists("/dev/snd/seq"):
        print("    skip (no aplaymidi or /dev/snd/seq)")
        return
    ports = subprocess.run(["aplaymidi", "-l"], capture_output=True, text=True,
                           timeout=10).stdout
    if "14:0" not in ports:
        print("    skip (no Midi Through port)")
        return

    # Frische Edit — Playhead steht bei 0, die Section ebenfalls; 1 s lang,
    # die Noten (bis 1,25 s) reichen darueber hinaus
    api("newEdit", path=os.path.join(PROJECT, "section-test.tracktionedit"))
    r = api("addSection", name="Take", length=1.0)
    check(r.get("ok") is True, f"addSection: {r}")

    r = api("record", on=True, type="midi", section="Take")
    check(r.get("ok") is True, f"section record start: {r}")
    check(r.get("section") == "Take" and "sectionEnd" not in r, f"section fields: {r}")

    # Start am Section-Anfang — kurz warten, dann die Noten spielen
    time.sleep(0.3)
    mid = os.path.join(PROJECT, "notes.mid")
    make_mid(mid)
    subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)

    # Kein Auto-Stop am Section-Ende: nach ~2 s laeuft die Aufnahme noch
    time.sleep(0.6)
    s = api("state")
    check(s.get("recording") is True, f"still recording past the section end: {s.get('recording')}")

    r = api("record", on=False)
    check(r.get("ok") is True and r.get("notes", 0) >= 4, f"record stop, all notes: {r}")

    # Take ab dem Section-Anfang, laenger als die Section; Auto-Section
    # hinter "Take" bis zum Take-Ende (ganze Takte, 120 BPM: 2 s)
    s = api("state")
    tl = s.get("trackList", [])
    mclips = [c for t in tl for c in t.get("clips", []) if c.get("type") == "midi"]
    check(len(mclips) == 1, f"one midi clip: {tl}")
    c = mclips[-1] if mclips else {}
    check(abs(c.get("start", -1)) < 0.4 and c.get("length", 0) > 1.5, f"take runs past the section: {c}")
    asec = r.get("autoSection") or {}
    secs = [(x["name"], round(x["start"], 3), round(x["end"], 3)) for x in s.get("sections", [])]
    check(asec.get("name") == "Section 1" and abs(asec.get("start", 0) - 1.0) < 1e-6
          and asec.get("end", 0) >= c.get("start", 0) + c.get("length", 0) - 1e-6, f"autoSection at stop: {r}")
    check([x[0] for x in secs] == ["Take", "Section 1"], f"sections: {secs}")
    # Auto-Section als eigene Aktion hinter dem Take, Take-Daten bleiben
    ts = api("treeState")
    cur = next(n for n in ts["nodes"] if n["id"] == ts["current"])
    acts = [(a["kind"], a["op"], (a["params"] or {}).get("name"), (a["params"] or {}).get("auto")) for a in cur["actions"][-2:]]
    check(acts == [("collect", "record", None, None), ("collect", "addSection", "Section 1", True)]
          and cur["takeType"] == "midi" and cur["takeSection"] == "Take", f"Aktion beim Stopp: {acts} {cur['takeType']} {cur['takeSection']}")

    # Take und Sektion wieder aufraeumen — Löschen läuft nur über den node reset
    r = api("treeReset", node=api("treeState")["current"])
    check(r.get("ok") is True, f"treeReset: {r}")

    # Unbekannte Sektion wird vor dem Record-Start abgelehnt
    r = api("record", on=True, type="midi", section="Nope")
    check(r.get("ok") is False and "no such section" in r.get("error", ""),
          f"unknown section: {r}")


@t("lane_flow")
def _():
    # Jede Aufnahme ist eine eigene Lane: eigener Track, Output in den
    # Zieltrack — sie klingt durch dessen Processing. Die Track-Gruppenspur
    # bleibt leerer Bus, die Takes leben in den Lanes.
    if shutil.which("aplaymidi") is None or not os.path.exists("/dev/snd/seq"):
        print("    skip (no aplaymidi or /dev/snd/seq)")
        return
    ports = subprocess.run(["aplaymidi", "-l"], capture_output=True, text=True,
                           timeout=10).stdout
    if "14:0" not in ports:
        print("    skip (no Midi Through port)")
        return

    api("newEdit", path=os.path.join(PROJECT, "lane-test.tracktionedit"))
    r = api("addSection", name="Lane", length=4.0)
    check(r.get("ok") is True, f"addSection: {r}")

    def stop_take():
        # Kein Auto-Stop am Section-Ende (seit 2026-10-24) — selbst stoppen
        r = api("record", on=False)
        check(r.get("ok") is True, f"record stop: {r} {record_log() if not r.get('ok') else ''}")

    mid = os.path.join(PROJECT, "notes.mid")
    make_mid(mid)

    def take(**params):
        r = api("record", on=True, type="midi", section="Lane", **params)
        check(r.get("ok") is True, f"take start: {r}")
        time.sleep(0.3)
        subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)
        stop_take()
        return r

    # Take 1: Gruppenspur (Index 0) + Lane Track 1.1 (Index 1) — die Gruppenspur
    # bleibt leer
    r = take()
    check(r.get("track") == 1, f"take 1 in first lane: {r}")

    s = api("state")
    tl = s.get("trackList", [])
    check(len(tl) == 2, f"group track plus lane: {len(tl)}")
    check(len(tl[0].get("clips", [])) == 0, f"group track empty: {tl[0]}")
    check(tl[1].get("dest") == 0 and len(tl[1].get("clips", [])) == 1,
          f"take 1 on lane: {tl[1]}")
    check(tl[1].get("name") == tl[0].get("name") + ".1", f"lane named after track: {tl[1]}")
    check(tl[0].get("mute") is False and tl[1].get("mute") is False, f"take 1 active: {tl}")

    # Take 2 mit track=0 → zweite Lane (Index 2)
    r = take(track=0)
    check(r.get("track") == 2, f"take 2 in second lane: {r}")

    # Take 3 mit track=1 (eine Lane) → Umleitung in die Gruppe, dritte Lane (Index 3)
    r = take(track=1)
    check(r.get("track") == 3, f"take 3 redirected into group: {r}")

    s = api("state")
    tl = s.get("trackList", [])
    check(len(tl) == 4, f"group track plus three lanes: {len(tl)}")
    check(all(t.get("dest") == 0 for t in tl[1:]), f"lanes route into group track: {tl}")
    check(len(tl[0].get("clips", [])) == 0, f"group track still empty: {tl[0]}")
    check(tl[1].get("name") == tl[0].get("name") + ".1"
          and tl[2].get("name") == tl[0].get("name") + ".2"
          and tl[3].get("name") == tl[0].get("name") + ".3", f"lane names: {tl}")

    # Nur eine Lane spielt: die neueste aktiv, die älteren gemutet; die
    # Gruppenspur bleibt als Bus an (Track-Mute nie gesetzt — die Lanes
    # laufen durch sie)
    check(tl[0].get("mute") is False and tl[1].get("mute") is True
          and tl[2].get("mute") is True and tl[3].get("mute") is False,
          f"newest lane active: {tl}")

    # Aufraeumen: Löschen läuft nur über den node reset — der wirft die
    # Section und die Lanes der Node weg
    r = api("treeReset", node=api("treeState")["current"])
    check(r.get("ok") is True, f"treeReset lane: {r}")

    s = api("state")
    tl = s.get("trackList", [])
    check(len(tl) == 0, f"node reset cleared lanes: {len(tl)}")


@t("midi_insert_flow")
def _():
    # add midi: eine .mid-Datei landet als MidiClip in einer Lane des
    # Zieltracks — die Spur wird MIDI-Spur, die Lane erbt den Typ
    api("newEdit", path=os.path.join(PROJECT, "midi-insert-test.tracktionedit"))
    r = api("addSection", name="MidiIn", length=6.0)
    check(r.get("ok") is True, f"addSection: {r}")

    mid = os.path.join(PROJECT, "insert-notes.mid")
    make_mid(mid)
    r = api("addClip", track=0, file=mid, section="MidiIn", start=0)
    check(r.get("ok") is True, f"addClip midi: {r}")
    check(r.get("length", 0) > 0.9, f"midi clip length: {r.get('length')}")
    check(r.get("section") == "MidiIn", f"midi clip section: {r}")
    check(r.get("track") == 1 and r.get("laneOf") == 0, f"midi insert as lane: {r}")

    s = api("state")
    check(s.get("trackTypes", [])[-1] == "midi", f"midi lane: {s.get('trackTypes')}")
    tl = s.get("trackList", [])
    mclips = tl[-1].get("clips", []) if tl else []
    check(len(mclips) == 1 and mclips[0].get("type") == "midi", f"midi clip in list: {mclips}")

    # Eine Nicht-MIDI-Datei mit falscher Endung bleibt beim Audio-Weg
    r = api("addClip", track=0, file=os.path.join(PROJECT, "media", "take.wav"), section="MidiIn")
    check(r.get("ok") is True, f"audio insert still ok: {r}")

    # Zu langer Insert: der Clip bleibt ganz (Material darf ueber das
    # Section-Ende, 2026-10-24) — hinter der letzten Section entsteht eine
    # Auto-Section bis zum Clip-Ende (ganze Takte: 8 .. 10 s)
    r = api("addSection", name="Short", length=2.0, position="last")
    check(r.get("ok") is True, f"short section: {r}")
    long_wav = os.path.join(PROJECT, "long-src.wav")
    make_wav(long_wav, seconds=3.0)
    r = api("addClip", track=-1, file=long_wav, section="Short", start=0)
    check(r.get("ok") is True, f"too-long insert: {r}")
    check(abs(r.get("length", 99) - 3.0) < 0.01, f"not cut at the section end: {r}")
    asec = r.get("autoSection") or {}
    check(asec.get("name") == "Section 1" and abs(asec.get("start", 0) - 8.0) < 1e-6 and abs(asec.get("end", 0) - 10.0) < 1e-6,
          f"auto section: {r}")


@t("midi_add_notes_flow")
def _():
    # addMidiClip: Noten programmatisch — der Weg ohne Keyboard und ohne
    # Datei. Der Clip landet wie ein Insert in einer Lane des Zieltracks;
    # hoerbar wird er erst durch ein Instrument im Routing
    api("newEdit", path=os.path.join(PROJECT, "midi-notes-test.tracktionedit"))
    r = api("addSection", name="Notes", length=4.0)
    check(r.get("ok") is True, f"addSection: {r}")

    # Validation vor Seiteneffekten: Section, Noten, Notenwerte
    note = {"pitch": 60, "start": 0, "length": 0.5}
    r = api("addMidiClip", track=0, notes=[note])
    check(r.get("error") == "no section", f"section required: {r}")
    r = api("addMidiClip", section="Nope", track=0, notes=[note])
    check(r.get("error") == "no such section: Nope", f"section must exist: {r}")
    r = api("addMidiClip", section="Notes", track=0)
    check(r.get("error") == "no notes", f"notes required: {r}")
    r = api("addMidiClip", section="Notes", track=0, notes=[])
    check(r.get("error") == "no notes", f"empty notes: {r}")
    r = api("addMidiClip", section="Notes", track=0, notes=[dict(note, pitch=200)])
    check(str(r.get("error")).startswith("invalid note"), f"pitch range: {r}")
    r = api("addMidiClip", section="Notes", track=0, notes=[dict(note, length=0)])
    check(str(r.get("error")).startswith("invalid note"), f"note length: {r}")
    s = api("state")
    check(s.get("tracks") == 0, f"no track on validation error: {s.get('tracks')}")

    notes = [{"pitch": 60, "start": 0, "length": 0.5},
             {"pitch": 64, "start": 0.5, "length": 0.5, "velocity": 80},
             {"pitch": 67, "start": 1.0, "length": 1.0}]
    r = api("addMidiClip", track=0, section="Notes", notes=notes)
    check(r.get("ok") is True, f"addMidiClip: {r}")
    check(r.get("track") == 1 and r.get("laneOf") == 0, f"clip as lane: {r}")
    check(r.get("notes") == 3, f"note count: {r}")
    # clipPeaks liefert die Noten fuer die Noten-Vorschau im Clip
    cl = api("state")["trackList"][r["track"]]["clips"][0]
    pk = api("clipPeaks", track=r["track"], name=cl["name"])
    check(pk.get("ok") is True and pk.get("type") == "midi"
          and [n["pitch"] for n in pk.get("notes", [])] == [60, 64, 67], f"clipPeaks midi: {pk}")
    check(abs(pk["notes"][1]["start"] - 0.5) < 0.02 and pk["notes"][1]["velocity"] == 80,
          f"clipPeaks note timing: {pk['notes']}")
    check(abs(r.get("length", 0) - 2.0) < 0.01, f"length from notes: {r}")

    s = api("state")
    check(s.get("trackTypes", [])[-1] == "midi", f"lane is midi: {s.get('trackTypes')}")
    tl = s.get("trackList", [])
    clips = tl[-1].get("clips", []) if tl else []
    check(len(clips) == 1 and clips[0].get("type") == "midi", f"midi clip in lane: {clips}")

    # Ohne Instrument stumm (kein Default-Instrument), mit 4OSC -> Main
    # tragen die Noten den Render (Peak > 0)
    out = os.path.join(PROJECT, "midi-notes-render.wav")
    r = api("render", file=out)
    check(r.get("ok") is False and r.get("error") == "Didn't find any audio to render",
          f"ohne Instrument stumm: {r}")
    r = api("addPlugin", name="4OSC", track=0, at="end")
    check(r.get("ok") is True, f"4OSC: {r}")
    r = api("connect", **{"from": r["id"], "to": "main"})
    check(r.get("ok") is True, f"4OSC -> main: {r}")
    r = api("render", file=out)
    check(r.get("ok") is True, f"render: {r}")
    r = api("peak")
    check(r.get("ok") is True and r.get("peak", 0) > 0, f"notes audible: {r}")

    # Laengen-Override: der Clip bleibt 10 s (kein Kuerzen am Section-Ende),
    # die Auto-Section reicht in ganzen Takten bis hinter das Clip-Ende (4 .. 12 s)
    r = api("addMidiClip", track=0, section="Notes", start=0.5, length=10, newLane=True,   # zweite Lane (Take)
            notes=[{"pitch": 55, "start": 0, "length": 0.5}])
    check(r.get("ok") is True, f"length override: {r}")
    check(abs(r.get("length", 0) - 10.0) < 0.01 and abs((r.get("autoSection") or {}).get("end", 0) - 12.0) < 1e-6,
          f"not cut, auto section: {r}")

    # Zweite Lane auf demselben Track: die neue spielt, die alte ist gemutet,
    # die Gruppenspur bleibt als Bus an
    tl = api("state")["trackList"]
    check(tl[-1].get("mute") is False and tl[-2].get("mute") is True
          and tl[0].get("mute") is False,
          f"newest lane active: {[t.get('mute') for t in tl]}")


@t("clip_edit_flow")
def _():
    # Clip-Edit-Ops am aktuellen Knoten: trimmen, verschieben, löschen —
    # der Weg ohne treeReset (der wirft alle Aktionen am Node weg).
    # Adressierung: track + name aus state.trackList.
    api("newEdit", path=os.path.join(PROJECT, "clip-edit-test.tracktionedit"))
    r = api("addSection", name="Edit", length=6.0)
    check(r.get("ok") is True, f"addSection: {r}")

    src = os.path.join(PROJECT, "clip-edit-src.wav")
    make_wav(src, seconds=3.0)
    r = api("addClip", track=0, file=src, section="Edit")
    check(r.get("ok") is True and r.get("track") == 1, f"addClip: {r}")

    # Fehlerwege ohne Seiteneffekte
    tracks_before = api("state").get("tracks")
    r = api("deleteClip", track=99, name="clip-edit-src")
    check(r.get("ok") is False and r.get("error") == "no such track", f"bad track: {r}")
    r = api("deleteClip", track=1, name="nope")
    check(r.get("ok") is False and r.get("error") == "no such clip: nope", f"bad name: {r}")
    r = api("trimClip", track=1, name="clip-edit-src")
    check(r.get("ok") is False and r.get("error") == "no start or length", f"nothing to trim: {r}")
    r = api("trimClip", track=1, name="clip-edit-src", length=0.0)
    check(r.get("ok") is False and r.get("error") == "length must be > 0", f"zero length: {r}")
    r = api("trimClip", track=1, name="clip-edit-src", start=-1)
    check(r.get("ok") is False and r.get("error") == "start must be >= 0", f"negative start: {r}")
    r = api("moveClip", track=1, name="clip-edit-src", start=-1)
    check(r.get("ok") is False and r.get("error") == "start must be >= 0", f"negative move: {r}")
    check(api("state").get("tracks") == tracks_before, f"no side effects: {api('state').get('tracks')}")

    # Trimmen: Laenge (Endkante), dann Start (Startkante)
    r = api("trimClip", track=1, name="clip-edit-src", length=1.5)
    check(r.get("ok") is True and abs(r.get("start", -1)) < 0.01
          and abs(r.get("length", 0) - 1.5) < 0.01, f"trim length: {r}")

    r = api("trimClip", track=1, name="clip-edit-src", start=0.5)
    check(r.get("ok") is True and abs(r.get("start", 0) - 0.5) < 0.01
          and abs(r.get("length", 0) - 1.0) < 0.01, f"trim start: {r}")

    # Beide Kanten in einem Ruf
    r = api("trimClip", track=1, name="clip-edit-src", start=0.0, length=2.0)
    check(r.get("ok") is True and abs(r.get("start", -1)) < 0.01
          and abs(r.get("length", 0) - 2.0) < 0.01, f"trim both: {r}")

    s = api("state")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and abs(clips[0]["start"]) < 0.01
          and abs(clips[0]["length"] - 2.0) < 0.01, f"state after trim: {clips}")

    # Verschieben: Laenge und Inhalt bleiben
    r = api("moveClip", track=1, name="clip-edit-src", start=2.0)
    check(r.get("ok") is True and abs(r.get("start", 0) - 2.0) < 0.01
          and abs(r.get("length", 0) - 2.0) < 0.01, f"move: {r}")

    # Trim-Start am/hinter dem Clip-Ende wird abgelehnt
    r = api("trimClip", track=1, name="clip-edit-src", start=4.0)
    check(r.get("ok") is False and "before the clip end" in r.get("error", ""),
          f"trim past end: {r}")

    # Take-Daten am Node: die letzte Collect-Aktion liefert Section und
    # Track (Clip-Edit-Ops sind process und speisen die Take-Daten nicht)
    n = [x for x in api("treeState")["nodes"] if x["id"] == api("treeState")["current"]][0]
    check(n["acted"] is True, "node acted after edits")
    check(n["takeType"] == "audio", f"takeType: {n['takeType']}")
    check(n["takeSection"] == "Edit", f"takeSection: {n['takeSection']}")
    check(n["takeTrack"] == 0, f"takeTrack: {n['takeTrack']}")

    # MIDI-Clip dazu, dann beide loeschen
    mid = os.path.join(PROJECT, "edit-notes.mid")
    make_mid(mid)
    r = api("addClip", track=-1, file=mid, section="Edit", start=0)
    check(r.get("ok") is True, f"midi insert: {r}")
    midi_track = r.get("track")
    check(api("state").get("clips") == 2, f"two clips: {api('state').get('clips')}")

    r = api("deleteClip", track=1, name="clip-edit-src")
    check(r.get("ok") is True, f"deleteClip audio: {r}")
    clips = [c for t in api("state").get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and clips[0].get("type") == "midi", f"audio clip gone: {clips}")

    r = api("deleteClip", track=midi_track, name="edit-notes")
    check(r.get("ok") is True, f"deleteClip midi: {r}")
    check(api("state").get("clips") == 0, f"clips gone: {api('state').get('clips')}")

    # Take-Daten am Node: die letzte Collect-Aktion liefert Typ, Section und
    # Track
    n = [x for x in api("treeState")["nodes"] if x["id"] == api("treeState")["current"]][0]
    check(n["takeType"] == "midi", f"takeType after midi delete: {n['takeType']}")


