@t("play_position")
def _():
    # Play/Stop über die Befehls-API, position meldet Playhead + Flags
    # (leichtgewichtig — kein Log-Eintrag, kein cerr-Spam).
    # Clip rein, damit das Edit eine Länge hat — sonst stoppt der
    # Play-Stop-am-Ende sofort (leeres Edit ≈ 0 s).
    api("newEdit", path=os.path.join(PROJECT, "play-test.tracktionedit"))
    wav = os.path.join(PROJECT, "play-src.wav")
    make_wav(wav, seconds=3.0)
    api("addSection", name="P", length=4.0)
    api("addClip", file=wav, section="P")

    r = api("position")
    check(r.get("ok") is True, f"position ok: {r}")
    check(abs(r.get("position", -1)) < 0.01, f"position starts at 0: {r}")
    check(r.get("playing") is False, f"not playing: {r}")
    check(r.get("recording") is False, f"not recording: {r}")

    r = api("play", on=True)
    check(r.get("ok") is True and r.get("playing") is True, f"play start: {r}")

    time.sleep(0.8)
    r = api("position")
    check(r.get("playing") is True, f"still playing: {r}")
    check(r.get("position", 0) > 0.5, f"position advances: {r}")

    r = api("play", on=False)
    check(r.get("ok") is True and r.get("playing") is False, f"play stop: {r}")

    r = api("position")
    check(r.get("playing") is False, f"stopped: {r}")

    # Play "from": ab der geklickten Stelle im Lineal
    r = api("play", on=True, **{"from": 2.0})
    check(r.get("ok") is True and r.get("playing") is True, f"play from: {r}")
    r = api("position")
    check(r.get("position", 0) >= 1.95, f"play from starts at 2 s: {r}")
    api("play", on=False)

    # Zweites Play: Song startet wieder von vorne
    r = api("play", on=True)
    check(r.get("ok") is True and r.get("playing") is True, f"play again: {r}")

    r = api("position")
    check(r.get("position", 99) < 0.4, f"play starts from top: {r}")

    api("play", on=False)

    # Version in jeder Antwort: verändernde Ops zählen hoch, Lese-Ops nicht
    r = api("position")
    v1 = r.get("version")
    check(v1 is not None, f"position has version: {r}")

    r = api("state")
    check(r.get("version") == v1, f"read op keeps version: {r}")

    r = api("play", on=False)
    check(r.get("version", 0) > v1, f"mutating op bumps version: {r}")


@t("loop_play")
def _():
    # Loop-Marker per loop-Op (Sektion), Play stoppt am Loop-Ende (einmal
    # durchhören) bzw. loopt den Bereich (Loop-Modus an).
    api("newEdit", path=os.path.join(PROJECT, "loop-test.tracktionedit"))
    api("addSection", name="A", length=2.0)

    r = api("loop", section="A")
    check(r.get("ok") is True, f"loop set: {r}")
    loop = r.get("loop") or {}
    check(abs(loop.get("start", -1)) < 0.01 and abs(loop.get("end", -1) - 2.0) < 0.01,
          f"loop range from section: {r}")
    check(loop.get("looping") is False, f"not looping after range set: {r}")

    r = api("state")
    check((r.get("loop") or {}).get("start") is not None, f"state carries loop: {r}")

    # Play ohne Loop-Modus: stoppt am Loop-Ende
    r = api("play", on=True)
    check(r.get("ok") is True and r.get("playing") is True, f"play start: {r}")

    time.sleep(2.6)
    r = api("position")
    check(r.get("playing") is False, f"play stopped at loop end: {r}")
    check(r.get("position", 0) < 3.5, f"stopped near loop end, not runaway: {r}")

    # Loop-Modus: loopt den Bereich endlos
    r = api("loop", on=True)
    check((r.get("loop") or {}).get("looping") is True, f"looping on: {r}")

    r = api("play", on=True)
    check(r.get("ok") is True and r.get("playing") is True, f"loop play: {r}")

    time.sleep(2.8)
    r = api("position")
    check(r.get("playing") is True, f"still looping: {r}")
    check(r.get("position", 99) < 2.5, f"wrapped inside loop range: {r}")

    api("play", on=False)

    # Loop-Marker löschen (loop ohne section und ohne on)
    r = api("loop")
    check(r.get("ok") is True, f"loop clear: {r}")
    check((r.get("loop") or {}).get("looping") is False, f"looping off after clear: {r}")

    r = api("loop", section="NichtDa")
    check(r.get("ok") is False, f"unknown section rejected: {r}")

    api("play", on=False)


