@t("render_and_peak")
def _():
    # Clip wieder rein (Reset hat geleert), dann Render + Peak
    r = api("addClip", track=0, file=os.path.join(PROJECT, "media", "take.wav"), section="Branch", newLane=True)
    check(r.get("ok") is True, f"addClip before render: {r}")

    out = os.path.join(PROJECT, "render-test.wav")
