@t("treeDelete")
def _():
    # Seed (root) ist geschützt
    r = api("treeDelete", node=1)
    check(r.get("ok") is False and "seed" in r.get("error", ""), f"delete seed: {r}")

    # Aktuelle frische Node im Teilbaum löschen → current wandert zum Parent
    r = api("treeCheckout", node=3)
    check(r.get("ok") is True, f"checkout node 3: {r}")
    r = api("treeReset", node=3)  # render_and_peak hat an node 3 geactet
    check(r.get("ok") is True, f"reset node 3: {r}")
    r = api("treeDelete", node=3)
    check(r.get("ok") is True, f"delete fresh subtree: {r}")
    check(api("treeState")["current"] == 1, "current moved to parent")
    check(not os.path.exists(os.path.join(PROJECT, "node-3.tracktionedit")), "edit file gone")
    check(not os.path.exists(os.path.join(PROJECT, "node-3.base.tracktionedit")), "base file gone")

    # acted Node ist geschützt — eine Aktion am Node schützt vor treeDelete
    r = api("treeBranch", label="acted-branch")
    check(r.get("ok") is True, f"branch for acted test: {r}")
    nid = r["node"]
    r = api("addSection", name="Branch-A", length=2.0)
    check(r.get("ok") is True, f"addSection at branch: {r}")
    n = [x for x in api("treeState")["nodes"] if x["id"] == nid][0]
    check(n["acted"] is True, "node acted after addSection")
    check(n["actedBy"] == "addSection", f"actedBy: {n['actedBy']}")
    r = api("treeDelete", node=nid)
    check(r.get("ok") is False and "actions" in r.get("error", ""), f"delete acted: {r}")
    check(any(n["id"] == nid for n in api("treeState")["nodes"]), "acted node still there")


@t("treeBranch_from_other_node")
def _():
    # current ist die acted-Branch; fork von node 1 (acted, nicht current)
    r = api("treeBranch", node=1, label="from-one")
    check(r.get("ok") is True and r.get("parent") == 1, f"branch from node 1: {r}")
    nid = r["node"]
    st = api("treeState")
    check(st["current"] == nid, "new branch is current")
    n = next(x for x in st["nodes"] if x["id"] == nid)
    check(n["parent"] == 1 and n["label"] == "from-one" and not n["acted"], "branch fields")

    # fresh node kann nicht geforkt werden
    r = api("treeBranch", node=nid)
    check(r.get("ok") is False and "action" in r.get("error", ""), f"branch fresh: {r}")


