@t("node_actions")
def _():
    # Frischer Song: Aktionen liegen als Datensaetze am Node (kind, op, params)
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-actions-")
    w = os.path.join(d, "tone.wav")
    make_wav(w)
    r = api("treeSeed", dir=d, label="actions")
    api("treeSettings", autoBranch=False)   # Spuren/Sections bewusst in einem Node (Fokus-Regel aus)
    check(r.get("ok") is True, f"seed: {r}")

    r = api("addSection", name="A", length=1.0)
    check(r.get("ok") is True, f"addSection: {r}")
    n = api("treeState")["nodes"][0]
    acts = n.get("actions", [])
    check(len(acts) == 1, f"one action: {acts}")
    check(acts[0]["kind"] == "collect" and acts[0]["op"] == "addSection",
          f"section action: {acts[0]}")
    check(n["actedBy"] == "addSection", "derived actedBy")

    r = api("addClip", track=0, file=w, section="A")
    check(r.get("ok") is True, f"addClip: {r}")
    n = api("treeState")["nodes"][0]
    acts = n.get("actions", [])
    check(len(acts) == 2, f"two actions: {acts}")
    check(acts[1]["kind"] == "collect" and acts[1]["op"] == "addClip", f"clip action: {acts[1]}")
    check(acts[1]["params"]["section"] == "A", f"action section: {acts[1]}")
    check(acts[1]["params"]["track"] == 0, f"action track: {acts[1]}")
    check(acts[1]["params"]["type"] == "audio", f"action type: {acts[1]}")
    check(acts[1]["file"] == w, f"action file: {acts[1]}")
    check(n["takeType"] == "audio" and n["takeSection"] == "A" and n["takeTrack"] == 0,
          f"derived take data: {n}")
    # Erste Aktion bleibt die Herkunft, die Take-Daten kommen aus der letzten
    check(n["actedBy"] == "addSection", "first action stays actedBy")

    # Branch erbt nichts: frische Node ohne Aktionen
    r = api("treeBranch")
    check(r.get("ok") is True, f"branch: {r}")
    n2 = [x for x in api("treeState")["nodes"] if x["id"] == r["node"]][0]
    check(n2["actions"] == [] and n2["acted"] is False, f"fresh branch actions: {n2}")


