@t("tree_v1_migration")
def _():
    # v1-tree.json (ohne actions) wird beim Laden migriert: die Altfelder
    # werden zu einer Aktion, acted/actedBy/Take-Daten bleiben abgeleitet
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-v1-")
    r = api("treeSeed", dir=d, label="legacy")
    check(r.get("ok") is True, f"seed: {r}")
    api("treeClose")

    # tree.json auf v1 zurueckschreiben: Altfelder statt actions
    tf = os.path.join(d, "tree.json")
    with open(tf) as f:
        js = json.load(f)
    js["version"] = 1
    js.pop("nextActionId", None)
    for n in js["nodes"]:
        n.pop("actions", None)
        n["acted"] = True
        n["actedBy"] = "record"
        n["actionFile"] = ""
        n["takeType"] = "midi"
        n["takeSection"] = "Seed"
        n["takeTrack"] = 0
    with open(tf, "w") as f:
        json.dump(js, f)

    r = api("treeOpen", dir=d)
    check(r.get("ok") is True, f"open v1: {r}")
    n = api("treeState")["nodes"][0]
    check(n["acted"] is True and n["actedBy"] == "record", f"migrated acted: {n}")
    check(n["takeType"] == "midi" and n["takeSection"] == "Seed" and n["takeTrack"] == 0,
          f"migrated take data: {n}")
    acts = n.get("actions", [])
    check(len(acts) == 1, f"migrated action: {acts}")
    check(acts[0]["kind"] == "collect" and acts[0]["op"] == "record", f"migrated kind/op: {acts[0]}")
    check(acts[0]["params"]["section"] == "Seed" and acts[0]["params"]["track"] == 0,
          f"migrated params: {acts[0]}")
    check(acts[0]["params"]["type"] == "midi", f"migrated take type: {acts[0]}")

    # Die naechste Mutation speichert v3 (actions stehen dann auf der Platte)
    r = api("treeLabel", node=1, label="legacy")
    check(r.get("ok") is True, f"label: {r}")
    api("treeClose")
    with open(tf) as f:
        js2 = json.load(f)
    check(js2.get("version") == 3, f"v3 written: {js2.get('version')}")
    check("actions" in js2["nodes"][0], "actions persisted")


@t("updateSection_flow")
def _():
    # Bestehende Section anpassen: umbenennen + Laenge aendern (Node-Aktion) —
    # die Auto-Section des Seeds liegt da und wird angepasst
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-updsec-")
    r = api("treeSeed", dir=d, label="upd")
    check(r.get("ok") is True, f"seed: {r}")

    r = api("updateSection", name="Section 1", label="B", length=2.0)
    check(r.get("ok") is True, f"updateSection: {r}")
    check(r.get("name") == "B" and abs(r.get("end", -1) - 2.0) < 0.01, f"updated range: {r}")

    secs = {x["name"]: x for x in api("state")["sections"]}
    check("Section 1" not in secs and "B" in secs, f"renamed: {list(secs)}")
    check(abs(secs["B"]["end"] - 2.0) < 0.01, f"new length: {secs['B']}")

    n = api("treeState")["nodes"][0]
    last = n["actions"][-1]
    check(last["kind"] == "collect" and last["op"] == "updateSection", f"action: {last}")
    check(last["params"]["name"] == "Section 1" and last["params"]["label"] == "B"
          and abs(last["params"]["length"] - 2.0) < 0.01, f"action params: {last}")

    r = api("updateSection", name="Nope", length=1.0)
    check(r.get("ok") is False and "no such section" in r.get("error", ""), f"unknown: {r}")
    r = api("updateSection", name="B")
    check(r.get("ok") is False and "nothing to update" in r.get("error", ""), f"no-op: {r}")
    r = api("updateSection", name="B", length=-1.0)
    check(r.get("ok") is False, f"bad length: {r}")


