@t("plugin_action")
def _():
    # Processing als Node-Aktion: addPlugin markiert den Node acted,
    # die Aktion steht als kind "processing" am Node
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-plugin-")
    r = api("treeSeed", dir=d, label="plug")
    check(r.get("ok") is True, f"seed: {r}")
    r = api("createTrack")
    check(r.get("ok") is True, f"createTrack: {r}")

    plugs = api("listPlugins").get("plugins", [])
    keys = [(p["format"], p["name"], p["uid"]) for p in plugs]
    check(len(keys) == len(set(keys)), f"listPlugins without duplicates: {len(keys)} vs {len(set(keys))}")
    tg = next((p for p in plugs if p["name"].lower() == "testgain"), None)
    check(tg is not None, f"testgain plugin found: {[p['name'] for p in plugs][:10]}")

    if tg is None:
        return

    # addPlugin legt nur ein Modul im Projekt an — unverdrahtet, die Spur
    # bleibt unberuehrt an Main
    r = api("addPlugin", name=tg["name"])
    check(r.get("ok") is True and r.get("id") == "p1" and r.get("class") == "audioFx",
          f"addPlugin: {r}")

    # state/routing listen das Modul; die Id adressiert die Parameter
    rt = api("state")["routing"]
    pl = rt.get("plugins", [])
    check(len(pl) == 1 and pl[0]["name"].lower() == "testgain" and pl[0]["id"] == "p1",
          f"routing plugins: {pl}")
    check(rt.get("edges") == [{"ok": True, "from": "t0", "to": "main", "level": 1.0, "send": False}], f"unverdrahtet: {rt.get('edges')}")
    lp = api("listParameters", plugin="p1")
    check(lp.get("ok") is True and lp.get("pluginName", "").lower() == "testgain",
          f"plugin id addresses listParameters: {lp}")
    r = api("listParameters", plugin="p9")
    check(r.get("error") == "no such plugin: p9", f"unknown plugin id: {r}")

    n = api("treeState")["nodes"][0]
    check(n["acted"] is True, "plugin acts the node")
    last = n["actions"][-1]
    check(last["kind"] == "process" and last["op"] == "addPlugin", f"action: {last}")
    check(last["params"]["plugin"] == tg["name"] and last["params"]["id"] == "p1"
          and "track" not in last["params"], f"action params: {last}")

    # Unbekanntes Plugin: Fehler, keine Aktion, Node bleibt wie er war
    r = api("addPlugin", name="GibtEsNicht")
    check(r.get("ok") is False and "unknown plugin" in r.get("error", ""), f"unknown plugin: {r}")
    check(len(api("treeState")["nodes"][0]["actions"]) == 1, "no action for failed plugin")

    # Der Processing-Node kann branchen (acted durch Processing)
    r = api("treeBranch", label="plug-branch")
    check(r.get("ok") is True, f"branch after plugin: {r}")


@t("plugin_select_format_uid")
def _():
    # Namensgleiche Plugins je Format/uid waehlen: testgain existiert als
    # VST3 und LV2 — format/uid aus listPlugins entscheiden, nicht der
    # erste Treffer.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-plugsel-")
    r = api("treeSeed", dir=d, label="sel")
    check(r.get("ok") is True, f"seed: {r}")
    r = api("createTrack")
    check(r.get("ok") is True, f"createTrack: {r}")

    plugs = [p for p in api("listPlugins").get("plugins", [])
             if p["name"].lower() == "testgain"]
    vst3 = next((p for p in plugs if p["format"] == "VST3"), None)
    lv2 = next((p for p in plugs if p["format"] == "LV2"), None)
    check(vst3 is not None and lv2 is not None,
          f"testgain in beiden Formaten: {[(p['format'], p['uid']) for p in plugs]}")

    if vst3 is None or lv2 is None:
        return

    check(vst3["uid"] != lv2["uid"], f"uid trennt die Formate: {vst3} {lv2}")

    # Je Format gezielt laden: die Antwort meldet die geladene Aufloesung,
    # der Edit-Dump die tatsaechlich geladene uid. Reihenfolge absichtlich
    # gegen den ersten Name-Treffer (hier VST3): ab Schritt 1 darf kein
    # VST3 im Edit stehen — jedes Ignorieren eines Filters faellt so auf.
    r = api("addPlugin", name=lv2["name"], format="LV2")
    check(r.get("ok") is True and r.get("format") == "LV2" and r.get("uid") == lv2["uid"],
          f"addPlugin per format: {r}")
    xml = api("dump")["xml"]
    check(f'uniqueId="{lv2["uid"]}"' in xml and f'uniqueId="{vst3["uid"]}"' not in xml,
          "nur LV2 geladen, kein VST3")

    # uid identifiziert allein; format ist dann nicht noetig
    r = api("addPlugin", name=lv2["name"], uid=lv2["uid"])
    check(r.get("ok") is True and r.get("format") == "LV2" and r.get("uid") == lv2["uid"],
          f"addPlugin per uid: {r}")
    xml = api("dump")["xml"]
    check(f'uniqueId="{vst3["uid"]}"' not in xml, "uid-Filter laedt kein VST3")

    # Gegenrichtung: dieselbe uid-Auswahl findet das VST3
    r = api("addPlugin", name=vst3["name"], uid=vst3["uid"])
    check(r.get("ok") is True and r.get("format") == "VST3" and r.get("uid") == vst3["uid"],
          f"addPlugin per VST3-uid: {r}")
    xml = api("dump")["xml"]
    check(f'uniqueId="{vst3["uid"]}"' in xml, "VST3 geladen")

    # Filter ohne Treffer: Fehler statt Zufallstreffer
    r = api("addPlugin", name=vst3["name"], format="AU")
    check(r.get("ok") is False and "unknown plugin" in r.get("error", ""),
          f"format ohne Treffer: {r}")

    # Die Node-Aktionen tragen die geladene Aufloesung
    n = api("treeState")["nodes"][0]
    acts = [a for a in n["actions"] if a["op"] == "addPlugin"]
    check(len(acts) == 3, f"drei addPlugin-Aktionen: {acts}")
    if len(acts) == 3:
        check(acts[0]["params"]["format"] == "LV2" and acts[0]["params"]["uid"] == lv2["uid"],
              f"Action LV2 per format: {acts[0]}")
        check(acts[1]["params"]["uid"] == lv2["uid"], f"Action LV2 per uid: {acts[1]}")
        check(acts[2]["params"]["format"] == "VST3" and acts[2]["params"]["uid"] == vst3["uid"],
              f"Action VST3 per uid: {acts[2]}")


@t("undo_delete_flow")
def _():
    # deleteClip gibt ein undo-Token (Aktions-Id); undoDelete holt den Clip
    # unveraendert zurueck und nimmt die deleteClip-Aktion vom Node
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-undo-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="undo").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    r = api("addClip", track=-1, file=w, section="Section 1", start=1.0)
    check(r.get("ok") is True, f"addClip: {r}")
    lane = r["track"]
    clip = api("state")["trackList"][lane]["clips"][0]
    n_actions = len(api("treeState")["nodes"][0]["actions"])

    r = api("deleteClip", track=lane, name=clip["name"])
    check(r.get("ok") is True and isinstance(r.get("undo"), int) and r["undo"] > 0, f"delete with token: {r}")
    token = r["undo"]
    check(api("state")["trackList"][lane]["clips"] == [], "clip gone")
    check(len(api("treeState")["nodes"][0]["actions"]) == n_actions + 1, "deleteClip recorded")

    r = api("undoDelete", undo=token)
    check(r.get("ok") is True and r.get("track") == lane and r.get("name") == clip["name"], f"undoDelete: {r}")
    back = api("state")["trackList"][lane]["clips"]
    check(len(back) == 1 and abs(back[0]["start"] - clip["start"]) < 0.01
          and abs(back[0]["length"] - clip["length"]) < 0.01, f"clip restored in place: {back}")
    acts = api("treeState")["nodes"][0]["actions"]
    check(len(acts) == n_actions and all(a["op"] != "deleteClip" for a in acts), f"action removed: {acts}")

    # Zweimal geht nicht, falsches Token auch nicht
    r = api("undoDelete", undo=token)
    check(r.get("ok") is False and r.get("error") == "nothing to undo", f"no double undo: {r}")
    check(api("undoDelete", undo=9999).get("error") == "nothing to undo", "unknown token")

    # Der Clip ueberlebt das Speichern: Checkout-Roundtrip laedt ihn wieder
    r = api("deleteClip", track=lane, name=clip["name"])
    token = r["undo"]
    check(api("undoDelete", undo=token).get("ok") is True, "undo again")
    check(api("treeCheckout", node=1).get("ok") is True, "reload node")
    check(len(api("state")["trackList"][lane]["clips"]) == 1, "restored clip saved")

    # Ein Node-Wechsel (Edit neu geladen) verwirft die Undo-Liste
    r = api("deleteClip", track=lane, name=clip["name"])
    api("treeCheckout", node=1)
    r = api("undoDelete", undo=r["undo"])
    check(r.get("ok") is False and r.get("error") == "nothing to undo", f"undo gone after reload: {r}")


@t("set_midi_notes_flow")
def _():
    # setMidiNotes ersetzt die Noten eines MIDI-Clips (Piano-Roll); der Clip
    # waechst mit (auch ueber Section-Grenzen), Folgeaufrufe sind eine Aktion
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-notes-")
    check(api("treeSeed", dir=d, label="notes").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    r = api("addSection", position="first", length=4.0)
    sec = r.get("name")
    r = api("addMidiClip", track=-1, section=sec, notes=[{"pitch": 60, "start": 0, "length": 1}])
    check(r.get("ok") is True, f"addMidiClip: {r}")
    lane = r["track"]
    name = api("state")["trackList"][lane]["clips"][0]["name"]
    n_actions = len(api("treeState")["nodes"][0]["actions"])

    # Fehlerwege ohne Seiteneffekte
    check(api("setMidiNotes", track=lane, name="nope", notes=[]).get("error") == "no such MIDI clip: nope", "bad clip")
    check(api("setMidiNotes", track=lane, name=name).get("error") == "no notes", "notes required")
    r = api("setMidiNotes", track=lane, name=name, notes=[{"pitch": 300, "start": 0, "length": 1}])
    check(str(r.get("error")).startswith("invalid note"), f"invalid note: {r}")
    check(len(api("treeState")["nodes"][0]["actions"]) == n_actions, "no action on error")

    notes = [{"pitch": 62, "start": 0, "length": 0.5}, {"pitch": 65, "start": 0.5, "length": 0.5, "velocity": 70}]
    r = api("setMidiNotes", track=lane, name=name, notes=notes)
    check(r.get("ok") is True and r.get("notes") == 2, f"setMidiNotes: {r}")
    pk = api("clipPeaks", track=lane, name=name)
    check([(n["pitch"], n["velocity"]) for n in pk["notes"]] == [(62, 100), (65, 70)], f"notes replaced: {pk['notes']}")

    # Noch einmal: dieselbe Aktion wird ersetzt, nicht angehaengt
    r = api("setMidiNotes", track=lane, name=name, notes=notes + [{"pitch": 67, "start": 1.0, "length": 0.5}])
    acts = api("treeState")["nodes"][0]["actions"]
    check(len(acts) == n_actions + 1 and acts[-1]["op"] == "setMidiNotes"
          and acts[-1]["kind"] == "process" and acts[-1]["params"]["notes"] == 3, f"coalesced: {acts[-1:]}")

    # Noten ueber das Clip-Ende: Clip waechst, auch ueber das Section-Ende
    # (4 s) in die naechste Section (2026-10-24)
    r = api("setMidiNotes", track=lane, name=name, notes=[{"pitch": 60, "start": 2.5, "length": 3.0}])
    check(r.get("ok") is True and abs(r.get("length", 0) - 5.5) < 0.02 and "warning" not in r, f"grows past the section end: {r}")

    # Leere Noten sind erlaubt (Clip bleibt, ohne Noten)
    r = api("setMidiNotes", track=lane, name=name, notes=[])
    check(r.get("ok") is True and r.get("notes") == 0, f"cleared: {r}")


@t("favorites_flow")
def _():
    # Select: favoriteClip/favoriteSection als select-Aktionen am Node —
    # state leitet die Favoriten-Flags ab, treeState hasFavorites, die
    # letzte select-Aktion je Ziel entscheidet.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-fav-")
    w = os.path.join(d, "tone.wav")
    make_wav(w)
    r = api("treeSeed", dir=d, label="fav")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    check(r.get("ok") is True, f"seed: {r}")
    r = api("addSection", name="A", length=2.0)
    check(r.get("ok") is True, f"addSection: {r}")
    r = api("addClip", track=0, file=w, section="A")
    check(r.get("ok") is True, f"addClip: {r}")

    # Section und Clip favorisieren — der Clip lebt auf seiner Lane, die
    # Adressierung (track + name) kommt aus state.trackList
    r = api("favoriteSection", name="A")
    check(r.get("ok") is True and r.get("favorite") is True, f"favoriteSection: {r}")

    s = api("state")
    clip_loc = [(t["index"], c["name"]) for t in s.get("trackList", [])
                for c in t.get("clips", []) if c["name"] == "tone"]
    check(len(clip_loc) == 1, f"clip located: {clip_loc}")
    ctr, cname = clip_loc[0]

    r = api("favoriteClip", track=ctr, name=cname)
    check(r.get("ok") is True and r.get("favorite") is True, f"favoriteClip: {r}")

    # state leitet die Flags ab (lineare Ansicht zeigt die Sterne)
    s = api("state")
    secs = {x["name"]: x for x in s.get("sections", [])}
    check(secs["A"].get("favorite") is True, f"section favorite: {secs['A']}")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(len(clips) == 1 and clips[0].get("favorite") is True, f"clip favorite: {clips}")

    # treeState: hasFavorites am Node, select-Aktionen als Datensaetze
    n = api("treeState")["nodes"][0]
    check(n.get("hasFavorites") is True, f"hasFavorites: {n.get('hasFavorites')}")
    sel = [a for a in n.get("actions", []) if a["kind"] == "select"]
    check(len(sel) == 2, f"select actions: {sel}")

    if len(sel) == 2:
        check(sel[0]["op"] == "favoriteSection" and sel[1]["op"] == "favoriteClip",
              f"select ops: {sel}")
        check(sel[0]["params"]["on"] is True and sel[1]["params"]["on"] is True,
              f"select params: {sel}")

    # Unfavorite: die letzte select-Aktion je Ziel entscheidet
    r = api("favoriteClip", track=ctr, name=cname)
    check(r.get("ok") is True and r.get("favorite") is False, f"unfavoriteClip: {r}")
    s = api("state")
    clips = [c for t in s.get("trackList", []) for c in t.get("clips", [])]
    check(clips[0].get("favorite") is False, f"clip favorite off: {clips}")
    n = api("treeState")["nodes"][0]
    check(n.get("hasFavorites") is True, "section favorite keeps hasFavorites")

    r = api("favoriteSection", name="A")
    check(r.get("ok") is True and r.get("favorite") is False, f"unfavoriteSection: {r}")
    n = api("treeState")["nodes"][0]
    check(n.get("hasFavorites") is False, f"hasFavorites cleared: {n.get('hasFavorites')}")

    # Guards: unbekannter Clip/Section
    r = api("favoriteClip", track=ctr, name="Nope")
    check(r.get("ok") is False and "no such clip" in r.get("error", ""), f"unknown clip: {r}")
    r = api("favoriteSection", name="Nope")
    check(r.get("ok") is False and "no such section" in r.get("error", ""), f"unknown section: {r}")


@t("compact_flow")
def _():
    # Projekt komprimieren: Trockenlauf (treeCompactPreview) liefert Plan +
    # Token, treeCompact laeuft nur mit dem Token. Node-Favoriten schuetzen
    # den Pfad komplett, Nodes ohne Favoriten fliegen, in Nodes mit
    # Material-Favoriten fliegt das nicht favorisierte Material.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-compact-")
    w = os.path.join(d, "tone.wav")
    make_wav(w)
    check(api("treeSeed", dir=d, label="compact").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)   # Spuren/Sections bewusst in einem Node (Fokus-Regel aus)

    # Ohne Favoriten gibt es nichts zu schuetzen — kein Plan
    r = api("treeCompactPreview")
    check(r.get("ok") is False and r.get("error") == "no favorites \u2014 nothing to keep", f"no favorites (UTF-8 intact): {r}")

    # Seed: Section 1 (Default), A, B — je ein Clip in A und B
    api("addSection", name="A", length=2.0)
    api("addSection", name="B", length=2.0)
    check(api("addClip", track=0, file=w, section="A").get("ok") is True, "addClip A")
    check(api("addClip", track=0, file=w, section="B", newLane=True).get("ok") is True, "addClip B")   # eigene Lane wie frueher

    # Node 2: Clip in B favorisiert (Material-Favorit) -> wird gestutzt
    check(api("treeBranch", label="pruned").get("node") == 2, "branch 2")
    s = api("state")
    sec_b = next(x for x in s["sections"] if x["name"] == "B")
    loc = [(t["index"], c["name"]) for t in s["trackList"] for c in t.get("clips", [])
           if abs(c["start"] - sec_b["start"]) < 0.01]
    check(len(loc) == 1, f"clip in B: {loc}")
    btr, bname = loc[0]
    check(api("favoriteClip", track=btr, name=bname).get("favorite") is True, "favoriteClip B")

    # Node 3: ohne Favoriten -> fliegt; Node 4: Node-Favorit (Pfad 1-4)
    api("treeCheckout", node=1)
    check(api("treeBranch", label="drop").get("node") == 3, "branch 3")
    api("addSection", name="C", length=1.0)
    api("treeCheckout", node=1)
    check(api("treeBranch", label="fav").get("node") == 4, "branch 4")
    api("addSection", name="D", length=1.0)
    check(api("treeFavorite", node=4).get("ok") is True, "treeFavorite 4")
    api("treeCheckout", node=3)

    # Trockenlauf: read-only (Version bleibt), nichts faellt
    v0 = api("treeState")["version"]
    r = api("treeCompactPreview")
    check(r.get("ok") is True and r.get("plan"), f"preview: {r}")
    check(r.get("version") == v0, f"preview counts no version: {r.get('version')} vs {v0}")
    check([n["node"] for n in r.get("removeNodes", [])] == [3], f"removeNodes: {r.get('removeNodes')}")
    pr = r.get("pruneNodes", [])
    check([p["node"] for p in pr] == [2], f"pruneNodes: {pr}")
    if pr:
        check(sorted(pr[0]["sections"]) == ["A", "Section 1"], f"pruned sections: {pr[0]['sections']}")
        check(len(pr[0]["clips"]) == 1 and pr[0]["clips"][0]["track"] != btr,
              f"pruned clips: {pr[0]['clips']}")
        check(len(pr[0]["tracks"]) == 1, f"pruned tracks: {pr[0]['tracks']}")
    check(os.path.exists(os.path.join(d, "node-3.tracktionedit")), "preview deletes nothing")
    plan = r.get("plan")

    # Guards: ohne Token, mit falschem Token
    r = api("treeCompact")
    check(r.get("ok") is False and "no plan" in r.get("error", ""), f"no plan: {r}")
    r = api("treeCompact", plan="deadbeef")
    check(r.get("ok") is False and "plan changed" in r.get("error", ""), f"wrong plan: {r}")

    # Echter Lauf
    r = api("treeCompact", plan=plan)
    check(r.get("ok") is True, f"compact: {r}")
    ts = api("treeState")
    check(sorted(n["id"] for n in ts["nodes"]) == [1, 2, 4], f"nodes after: {[n['id'] for n in ts['nodes']]}")
    check(ts["current"] == 1, f"current falls back to kept ancestor: {ts['current']}")
    check(not os.path.exists(os.path.join(d, "node-3.tracktionedit")), "node-3 edit deleted")
    check(not os.path.exists(os.path.join(d, "node-3.base.tracktionedit")), "node-3 base deleted")

    # Node 1 (Pfad-Favorit) unberuehrt
    s = api("state")
    check(sorted(x["name"] for x in s["sections"]) == ["A", "B", "Section 1"],
          f"node 1 sections kept: {s['sections']}")

    # Node 2: nur B bleibt (rueckt auf 0), der favorisierte Clip mit, die
    # leere Lane faellt, die select-Aktion zeigt auf den neuen Index
    api("treeCheckout", node=2)
    s = api("state")
    check([(x["name"], round(x["start"], 2)) for x in s["sections"]] == [("B", 0.0)],
          f"node 2 sections: {s['sections']}")
    clips = [(t["index"], c) for t in s["trackList"] for c in t.get("clips", [])]
    check(len(clips) == 1 and clips[0][1].get("favorite") is True
          and abs(clips[0][1]["start"]) < 0.01, f"node 2 clips: {clips}")
    n2 = next(n for n in api("treeState")["nodes"] if n["id"] == 2)
    sel = [a for a in n2["actions"] if a["kind"] == "select"]
    check(len(clips) == 1 and sel and sel[-1]["params"]["track"] == clips[0][0],
          f"select remapped: {sel} vs {clips}")
    check(len(s["trackList"]) == 2, f"node 2 tracks: {[t['name'] for t in s['trackList']]}")

    # Zweiter Trockenlauf: nichts mehr zu tun
    r = api("treeCompactPreview")
    check(r.get("ok") is True and not r.get("removeNodes") and not r.get("pruneNodes"),
          f"second preview empty: {r}")


@t("inputs_flow")
def _():
    # Collect: listInputs meldet wave + midi Geraete, assignInput legt die
    # Spur auf ein Geraet, record aerm alle Spuren mit Zuweisung
    # (Multi-Track-Record — hier MIDI ueber den Loopback auf zwei Spuren).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-inputs-")
    r = api("treeSeed", dir=d, label="inputs")
    check(r.get("ok") is True, f"seed: {r}")

    # listInputs: das wave input ist da
    r = api("listInputs")
    check(r.get("ok") is True, f"listInputs: {r}")
    inputs = r.get("inputs", [])
    check(len(inputs) >= 1, f"inputs: {inputs}")
    check(any(i["type"] == "audio" for i in inputs), f"wave input: {inputs}")

    # state meldet die Eingaenge (die UI liest sie fuer das Spur-Dropdown)
    s = api("state")
    check(len(s.get("inputs", [])) == len(inputs), f"state inputs: {len(s.get('inputs', []))}")

    midi_ok = shutil.which("aplaymidi") is not None and os.path.exists("/dev/snd/seq")
    if midi_ok:
        ports = subprocess.run(["aplaymidi", "-l"], capture_output=True, text=True,
                               timeout=10).stdout
        midi_ok = "14:0" in ports

    if not midi_ok:
        print("    skip multi-record (no aplaymidi or Midi Through)")
        return

    mid = os.path.join(d, "notes.mid")
    make_mid(mid)

    # Zwei MIDI-Spuren, beide auf das Loopback-Geraet
    r1 = api("createTrack", type="midi")
    r2 = api("createTrack", type="midi")
    check(r1.get("ok") is True and r2.get("ok") is True, f"two midi tracks: {r1} {r2}")

    # Guards
    r = api("assignInput", track=9, input="Nope")
    check(r.get("ok") is False, f"assign unknown track: {r}")
    r = api("assignInput", track=0, input="Nope")
    check(r.get("ok") is False and "no such input" in r.get("error", ""),
          f"assign unknown input: {r}")

    r = api("addSection", name="Multi", length=8.0)
    check(r.get("ok") is True, f"addSection: {r}")

    midi_name = next(i["name"] for i in api("listInputs")["inputs"] if i["type"] == "midi")
    r = api("assignInput", track=0, input=midi_name)
    check(r.get("ok") is True, f"assign track 0: {r}")
    r = api("assignInput", track=1, input=midi_name)
    check(r.get("ok") is True, f"assign track 1: {r}")

    # listInputs meldet die Zuweisungen, state die Spur-Felder
    ins = api("listInputs")["inputs"]
    midi_in = next(i for i in ins if i["type"] == "midi")
    check(0 in midi_in.get("tracks", []) and 1 in midi_in.get("tracks", []),
          f"assignments: {midi_in}")

    # Record aerm beide Spuren — takes meldet zwei Lanes
    r = api("record", on=True, section="Multi")
    check(r.get("ok") is True, f"multi record start: {r}")
    takes = r.get("takes", [])
    check(len(takes) == 2, f"two armed lanes: {takes}")

    time.sleep(1)
    subprocess.run(["aplaymidi", "-p", "14:0", mid], timeout=10, check=True)
    time.sleep(1)

    r = api("record", on=False)
    check(r.get("ok") is True, f"multi record stop: {r}")
    takes = r.get("takes", [])
    check(len(takes) == 2, f"two takes collected: {takes}")
    check(all(t.get("notes", 0) >= 4 for t in takes), f"notes on both lanes: {takes}")

    # Eine record-Aktion je Lane am Node, beide kind collect
    n = [x for x in api("treeState")["nodes"] if x["id"] == api("treeState")["current"]][0]
    recs = [a for a in n.get("actions", []) if a["op"] == "record"]
    check(len(recs) == 2 and all(a["kind"] == "collect" for a in recs),
          f"one action per lane: {recs}")

    # clearInput hebt die Zuweisung auf
    r = api("clearInput", track=0)
    check(r.get("ok") is True, f"clearInput: {r}")
    ins = api("listInputs")["inputs"]
    midi_in = next(i for i in ins if i["type"] == "midi")
    check(0 not in midi_in.get("tracks", []) and 1 in midi_in.get("tracks", []),
          f"cleared: {midi_in}")

    # Aufraeumen
    r = api("treeReset", node=api("treeState")["current"])
    check(r.get("ok") is True, f"treeReset: {r}")


@t("arm_track_flow")
def _():
    # Arm-Schalter je Spur: armTrack legt das Default-Geraet des Spurtyps
    # auf die Spur (state armed), record nimmt alle geaermten Spuren
    # parallel auf — Audio und MIDI gleichzeitig
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-arm-")
    check(api("treeSeed", dir=d, label="arm").get("ok") is True, "seed")
    ra = api("createTrack")
    rm = api("createTrack", type="midi")
    a, m = ra["index"], rm["index"]

    check(api("armTrack", track=99).get("error") == "no such track", "bad track")

    r = api("armTrack", track=m)
    check(r.get("ok") is True and r.get("armed") is True and r.get("type") == "midi", f"arm midi: {r}")
    midi_dev = r.get("input")
    tl = api("state")["trackList"]
    check(tl[m]["armed"] is True and tl[a]["armed"] is False, f"armed flags: {[(t['name'], t['armed']) for t in tl]}")

    # Nochmal armen ohne Geraet laesst die Zuweisung stehen
    check(api("armTrack", track=m).get("input") == midi_dev, "re-arm keeps device")

    # Anderes Geraet ersetzt das bisherige (eine Zuweisung je Spur)
    other = next((i["name"] for i in api("listInputs")["inputs"]
                  if i["type"] == "midi" and i["name"] != midi_dev), None)
    if other:
        r = api("armTrack", track=m, input=other)
        check(r.get("input") == other and api("state")["trackList"][m]["inputs"] == [other],
              f"device replaced: {api('state')['trackList'][m]['inputs']}")
        api("armTrack", track=m, input=midi_dev)
    check(api("armTrack", track=m, input="Nope").get("error") == "no such input: Nope", "unknown input")

    # Monitor ueber die geaermten Spuren
    r = api("monitor", on=True, armed=True)
    check(r.get("ok") is True and midi_dev in r.get("inputs", []), f"monitor armed: {r}")
    check(api("state").get("monitor") is True, "monitor flag")
    check(api("monitor", on=False).get("ok") is True, "monitor off")

    # Audio-Spur armen — ohne Audio-Eingang (headless) nur der Fehlerweg
    r = api("armTrack", track=a)
    audio_ok = r.get("ok") is True
    if audio_ok:
        check(r.get("type") == "audio", f"arm audio: {r}")
        s = api("record", on=True, section="Section 1")
        if s.get("ok"):
            types = sorted(t["type"] for t in s.get("takes", []))
            check(types == ["audio", "midi"], f"audio + midi in parallel: {s.get('takes')}")
            tl = api("state")["trackList"]
            check(tl[a]["armed"] and tl[m]["armed"], "groups stay armed while recording")
            time.sleep(0.5)
            r = api("record", on=False)
            check(r.get("ok") is True and len(r.get("takes", [])) == 2, f"two takes: {r.get('takes')}")
            # Ohne Monitor-Schalter ist das Monitoring nach dem Take wieder aus
            check(api("state").get("monitor") is False, "monitor flag off after record")
            # Zuweisungen bleiben auf den Spuren — beide weiter geaermt
            tl = api("state")["trackList"]
            check(tl[a]["armed"] and tl[m]["armed"], "still armed after record")
            # Eine Lane armt ihre Gruppe
            lane = next(t["index"] for t in tl if t["dest"] == m)
            r = api("armTrack", track=lane)
            check(r.get("track") == m, f"lane arms its group: {r}")
        else:
            print(f"    skip parallel record ({s.get('error')})")
    else:
        print(f"    skip audio arm ({r.get('error')})")

    # Disarm hebt die Zuweisung auf; ohne geaermte Spur kein Monitor
    for t in (a, m):
        check(api("armTrack", track=t, on=False).get("armed") is False, "disarm")
    check(not any(t["armed"] for t in api("state")["trackList"]), "nothing armed")
    check(api("monitor", on=True, armed=True).get("error") == "no armed track", "monitor needs arm")

    # Armen ist keine Node-Aktion
    n = api("treeState")["nodes"][0]
    check(all(x["op"] != "armTrack" for x in n["actions"]), f"no arm action: {n['actions']}")
    api("treeReset", node=1)


@t("routing_rules_flow")
def _():
    # Routing-Matrix: Spuren laufen frei durch Plugin-Module bis Main. MIDI
    # geht nur in MIDI-Effekte und Instrumente, Audio nur in Audio-Effekte
    # und Main; ein Instrument macht aus MIDI Audio. Die Fehlertexte sind
    # API-Vertrag (UI-Tooltip in der Matrix).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-routing-")
    check(api("treeSeed", dir=d, label="routing").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)   # Spuren/Sections bewusst in einem Node (Fokus-Regel aus)
    check(api("createTrack", type="midi").get("index") == 0, "t0 midi")
    check(api("createTrack").get("index") == 1, "t1 audio")

    rt = api("routing")
    check(rt.get("ok") is True and [(x["id"], x["signal"]) for x in rt["sources"]]
          == [("t0", "midi"), ("t1", "audio")], f"sources: {rt.get('sources')}")
    check(rt["edges"] == [{"ok": True, "from": "t1", "to": "main", "level": 1.0, "send": False}], f"nur Audio an Main: {rt['edges']}")

    ids = {}
    for name, cls in (("4OSC", "instrument"), ("MIDI Modifier", "midiFx"), ("Reverb", "audioFx")):
        r = api("addPlugin", name=name)
        check(r.get("ok") is True and r.get("class") == cls and r.get("format") == "builtin",
              f"addPlugin {name}: {r}")
        ids[name] = r.get("id")
    osc, mod, rev = ids["4OSC"], ids["MIDI Modifier"], ids["Reverb"]
    check([osc, mod, rev] == ["p1", "p2", "p3"], f"Ids: {ids}")
    pl = {x["id"]: (x["in"], x["out"]) for x in api("routing")["plugins"]}
    check(pl == {"p1": ("midi", "audio"), "p2": ("midi", "midi"), "p3": ("audio", "audio")},
          f"Ein-/Ausgangstypen: {pl}")
    check(api("addPlugin", name="Reverb", **{"class": "synth"}).get("error")
          == "class must be midiFx, instrument or audioFx", "class validiert")

    def conn(a, b):
        return api("connect", **{"from": a, "to": b})

    # Typ-Regeln und Graph-Regeln
    for a, b, err in (("t0", "main", "midi cannot reach main"),
                      ("t0", rev, "midi needs an instrument or midi fx"),
                      (mod, rev, "midi needs an instrument or midi fx"),
                      ("t1", osc, "audio cannot enter a midi plugin"),
                      ("t1", mod, "audio cannot enter a midi plugin"),
                      (osc, "t0", "tracks have no input"),
                      ("main", rev, "main has no output"),
                      (rev, rev, "would create a loop"),
                      ("foo", rev, "no such node: foo"),
                      ("t9", rev, "no such node: t9")):
        r = conn(a, b)
        check(r.get("ok") is False and r.get("error") == err, f"{a} -> {b}: {r}")

    # Kette MIDI -> MIDI-Effekt -> Instrument -> Hall -> Main, Fan-in (t1 in
    # den Hall), Fan-out (t0 zusaetzlich direkt ins Instrument)
    for a, b in (("t0", mod), (mod, osc), (osc, rev), (rev, "main"), ("t1", rev), ("t0", osc)):
        r = conn(a, b)
        check(r.get("ok") is True, f"connect {a} -> {b}: {r}")
    check(conn("t0", osc).get("error") == "already connected", "doppelt")

    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check(edges == {("t0", mod), ("t0", osc), (mod, osc), (osc, rev), (rev, "main"),
                    ("t1", rev), ("t1", "main")}, f"edges: {edges}")

    # Schleife ueber mehrere Knoten
    dly = api("addPlugin", name="Delay")["id"]
    check(conn(rev, dly).get("ok") is True, "rev -> delay")
    check(conn(dly, rev).get("error") == "would create a loop", "Schleife erkannt")
    check(conn(dly, osc).get("error") == "audio cannot enter a midi plugin", "Delay -> 4OSC")
    check(api("disconnect", **{"from": dly, "to": rev}).get("error") == "not connected", "not connected")
    check(api("disconnect", **{"from": rev, "to": dly}).get("ok") is True, "disconnect")

    # Matrix: je Ausgang alle Eingaenge mit connected und Grund
    m = {row["from"]: {c["to"]: c for c in row["cells"]} for row in api("routing")["matrix"]}
    check(set(m) == {"t0", "t1", osc, mod, rev, dly}, f"Matrix-Zeilen: {list(m)}")
    check(m["t0"]["main"]["reason"] == "midi cannot reach main" and not m["t0"]["main"]["connected"],
          f"Zelle t0/main: {m['t0']['main']}")
    check(m["t1"][rev]["connected"] is True and m["t1"][rev]["reason"] == "", f"Zelle t1/rev: {m['t1'][rev]}")
    check(m[dly][rev]["reason"] == "would create a loop" or m[dly][rev]["reason"] == "",
          f"Zelle delay/rev: {m[dly][rev]}")
    check(m[rev][rev]["reason"] == "would create a loop", f"Zelle rev/rev: {m[rev][rev]}")

    # Track-Header: Ziele der Spur
    tl = api("state")["trackList"]
    check([x["name"] for x in tl[0]["routes"]] == ["4OSC", "MIDI Modifier"], f"routes t0: {tl[0]['routes']}")

    # removePlugin raeumt die Kanten; t1 bleibt an Main
    r = api("removePlugin", plugin=rev)
    check(r.get("ok") is True and r.get("name") == "Reverb", f"removePlugin: {r}")
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    # die Luecke schliesst sich: was in den Hall ging, geht jetzt nach Main
    check(edges == {("t0", mod), ("t0", osc), (mod, osc), ("t1", "main"), (osc, "main")} and f"{osc} → main" in r.get("reconnected", []),
          f"edges nach remove: {edges} {r.get('reconnected')}")
    check(api("removePlugin", plugin=rev).get("error") == f"no such plugin: {rev}", "zweimal entfernen")
    # Ids werden nicht wiederverwendet
    check(api("addPlugin", name="Chorus").get("id") == "p5", "neue Id nach remove")

    # Eine Lane ist kein Knoten — ihre Gruppe wird geroutet
    r = api("addMidiClip", track=0, section="Section 1", notes=[{"pitch": 60, "start": 0, "length": 1}])
    lane = r.get("track")
    r = conn(f"t{lane}", osc)
    check(r.get("error") == f"t{lane} is a lane — route its track t0", f"Lane: {r}")
    check([x["id"] for x in api("routing")["sources"]] == ["t0", "t1"], "Lanes nicht in der Matrix")

    # Die Aktionen am Node: Module und Kanten sind process-Aktionen
    ops = [a["op"] for a in api("treeState")["nodes"][0]["actions"] if a["kind"] == "process"]
    check(ops.count("addPlugin") == 5 and ops.count("connect") == 7 and ops.count("disconnect") == 1
          and ops.count("removePlugin") == 1, f"process-Aktionen: {ops}")


@t("routing_audio_flow")
def _():
    # Hoerbar: das Signal kommt nur ueber das Routing an Main — getrennt ist
    # es still, ein Modul ohne Weg nach Main auch. addPlugin track+at fuegt
    # das Modul an den Anfang/ans Ende der Kette der Spur ein (Typ-Pruefung
    # vorab, Fehler ohne Aenderung).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-routaudio-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="routaudio").get("ok") is True, "seed")
    check(api("addClip", track=0, file=w, section="Section 1").get("ok") is True, "addClip")
    out = os.path.join(d, "out.wav")

    def peak():
        api("render", file=out)
        return api("peak").get("peak", 0)

    check(peak() > 0.1, "Audio-Spur an Main hoerbar")
    check(api("disconnect", **{"from": "t0", "to": "main"}).get("ok") is True, "t0 von Main trennen")
    check(peak() < 0.001, "getrennt still")

    # Ende der Kette ohne Weg nach Main: das Modul haengt hinter der Spur
    r = api("addPlugin", name="Compressor", track=0, at="end")
    check(r.get("ok") is True, f"Compressor ans Ende: {r}")
    comp = r["id"]
    edges = [(e["from"], e["to"]) for e in api("routing")["edges"]]
    check(edges == [("t0", comp)], f"hinter der Spur: {edges}")
    check(peak() < 0.001, "Modul ohne Main still")
    check(api("connect", **{"from": comp, "to": "main"}).get("ok") is True, "comp -> main")
    check(peak() > 0.1, "ueber das Modul hoerbar")

    # Ende der Kette mit Weg nach Main: vor Main eingefuegt
    r = api("addPlugin", name="Low Pass", track=0, at="end")
    lp = r["id"]
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check(edges == {("t0", comp), (comp, lp), (lp, "main")}, f"vor Main: {edges}")

    # Anfang der Kette: direkt hinter die Spur
    r = api("addPlugin", name="Phaser", track=0, at="start")
    ph = r["id"]
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check(edges == {("t0", ph), (ph, comp), (comp, lp), (lp, "main")}, f"hinter der Spur: {edges}")
    check(peak() > 0.05, "Kette hoerbar")

    # Passt nicht: Fehler, kein Modul, keine Aktion
    n_plugins = len(api("routing")["plugins"])
    n_actions = len(api("treeState")["nodes"][0]["actions"])
    for at in ("start", "end"):
        r = api("addPlugin", name="4OSC", track=0, at=at)
        check(r.get("ok") is False and r.get("error") == "audio cannot enter a midi plugin", f"4OSC {at}: {r}")
    r = api("addPlugin", name="Reverb", track=0, at="middle")
    check(r.get("error") == "at must be start, end or master", f"at: {r}")
    r = api("addPlugin", name="Reverb", track=7, at="end")
    check(r.get("error") == "no such track", f"track: {r}")
    check(len(api("routing")["plugins"]) == n_plugins, "kein Modul bei Fehler")
    check(len(api("treeState")["nodes"][0]["actions"]) == n_actions, "keine Aktion bei Fehler")

    # Ein Lane-Index meint die Gruppe
    lane = api("state")["trackList"][1]
    check(lane["dest"] == 0, f"Lane: {lane}")
    r = api("addPlugin", name="Chorus", track=1, at="end")
    check(r.get("ok") is True and r.get("id") in
          {e["from"] for e in api("routing")["edges"] if e["to"] == "main"}, f"Lane meint Gruppe: {r}")

    # Mute ist Abhoer-Hilfe (Decision 2026-10-20): Messung und Render
    # ignorieren sie; Solo laesst die Module an
    api("trackMix", track=0, mute=True)
    check(peak() > 0.05, "Mute gilt nicht in der Messung")
    api("trackMix", track=0, mute=False)
    api("createTrack")
    api("trackMix", track=0, solo=True)
    check(peak() > 0.05, "Solo der Spur: Module bleiben hoerbar")
    api("trackMix", track=0, solo=False)

    # MIDI-Spur bis Main: MIDI-Effekt -> Instrument -> Main
    r = api("addMidiClip", track=-1, section="Section 1",
            notes=[{"pitch": 60, "start": 0, "length": 1}])
    mt = r["laneOf"]
    api("trackMix", track=0, volumeDb=-100.0)   # Audio-Spur aus der Messung (Mute gilt dort nicht)
    check(peak() < 0.001, "MIDI ohne Instrument still")
    r = api("addPlugin", name="4OSC", track=mt, at="end")
    check(r.get("ok") is True, f"4OSC ans Ende der MIDI-Spur: {r}")
    osc = r["id"]
    check(api("connect", **{"from": osc, "to": "main"}).get("ok") is True, "4OSC -> main")
    r = api("addPlugin", name="MIDI Modifier", track=mt, at="start")
    check(r.get("ok") is True, f"MIDI-Effekt an den Anfang: {r}")
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check({(f"t{mt}", r["id"]), (r["id"], osc), (osc, "main")} <= edges, f"MIDI-Kette: {edges}")
    check(peak() > 0.05, "MIDI -> MIDI-Effekt -> Instrument -> Main hoerbar")


@t("routing_tree_flow")
def _():
    # Das Routing liegt im Edit: jeder Node hat sein eigenes, ein Branch
    # erbt es, Aenderungen im Branch lassen den Vorgaenger unberuehrt.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-routtree-")
    check(api("treeSeed", dir=d, label="routtree").get("ok") is True, "seed")
    api("createTrack")
    rev = api("addPlugin", name="Reverb", track=0, at="end").get("id")
    check(rev == "p1", f"Reverb: {rev}")
    acts = api("treeState")["nodes"][0]["actions"]
    check(acts[-1]["op"] == "addPlugin" and acts[-1]["params"]["track"] == 0
          and acts[-1]["params"]["at"] == "end" and acts[-1]["params"]["id"] == rev,
          f"Aktion mit Splice: {acts[-1]}")
    parent_edges = api("routing")["edges"]

    check(api("treeBranch", label="b").get("node") == 2, "branch")
    check(api("routing")["edges"] == parent_edges, "Branch erbt das Routing")
    check(api("removePlugin", plugin=rev).get("ok") is True, "removePlugin im Branch")
    check(api("routing")["plugins"] == [], "Branch ohne Modul")

    check(api("treeCheckout", node=1).get("ok") is True, "checkout 1")
    rt = api("routing")
    check([p["id"] for p in rt["plugins"]] == [rev] and rt["edges"] == parent_edges,
          f"Vorgaenger unberuehrt: {rt}")

    # Reset wirft das Routing des Nodes mit seinen Aktionen weg
    check(api("treeCheckout", node=2).get("ok") is True, "checkout 2")
    check(api("treeReset", node=2).get("ok") is True, "reset 2")
    check([p["id"] for p in api("routing")["plugins"]] == [rev], "Reset holt den Base-Stand")


@t("routing_migration")
def _():
    # Alte Edits (Plugins auf der Spur, 4OSC auf MIDI-Spur und Lanes) werden
    # beim Laden zur Modulkette: Spur -> 4OSC -> Reverb -> Main, Lane-Synths
    # raus, Audio-Spur bleibt an Main. Der Klang bleibt erhalten.
    import xml.etree.ElementTree as ET
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-routmig-")
    check(api("treeSeed", dir=d, label="legacy").get("ok") is True, "seed")
    r = api("addMidiClip", track=-1, section="Section 1",
            notes=[{"pitch": 60, "start": 0, "length": 1}])
    check(r.get("track") == 1 and r.get("laneOf") == 0, f"MIDI-Spur + Lane: {r}")
    api("createTrack")
    api("treeClose")

    # Zurueck ins alte Format: keine dawd-Felder, keine Void-Spur, Synths
    # und Effekte auf den Spuren
    f = os.path.join(d, "node-1.tracktionedit")
    tree = ET.parse(f)
    root = tree.getroot()
    for k in ("dawdRouting", "dawdNextModule"):
        root.attrib.pop(k, None)
    tracks = root.findall("TRACK")
    for tr in tracks:
        if tr.get("dawdRole"):
            root.remove(tr)
            continue
        tr.attrib.pop("dawdType", None)
    group, lane, audio = [tr for tr in root.findall("TRACK")]
    group.find("OUTPUTDEVICES/DEVICE").set("name", "(default audio output)")

    def plugin(tr, typ, pid, first):
        el = ET.Element("PLUGIN", {"type": typ, "id": pid, "enabled": "1"})
        idx = list(tr).index(tr.find("PLUGIN")) if first else len(list(tr))
        tr.insert(idx, el)

    plugin(group, "4osc", "9001", True)
    plugin(group, "reverb", "9002", False)
    plugin(lane, "4osc", "9003", True)
    tree.write(f, encoding="UTF-8", xml_declaration=True)

    check(api("treeOpen", dir=d).get("ok") is True, "open legacy")
    s = api("state")
    check(s["trackTypes"] == ["midi", "midi", "audio"], f"Typen aus dem alten Synth: {s['trackTypes']}")
    rt = s["routing"]
    pl = [(p["id"], p["name"], p["class"]) for p in rt["plugins"]]
    check(pl == [("p1", "4OSC", "instrument"), ("p2", "Reverb", "audioFx")], f"Module: {pl}")
    edges = {(e["from"], e["to"]) for e in rt["edges"]}
    check(edges == {("t0", "p1"), ("p1", "p2"), ("p2", "main"), ("t2", "main")}, f"Kette: {edges}")
    xml = api("dump")["xml"]
    check(xml.count('type="4osc"') == 1, "Lane-Synth entfernt, ein 4OSC im Modul")
    out = os.path.join(d, "mig.wav")
    api("render", file=out)
    check(api("peak").get("peak", 0) > 0.05, "migrierter Song klingt")

    # Idempotent: erneutes Laden migriert nicht doppelt
    api("treeClose")
    check(api("treeOpen", dir=d).get("ok") is True, "reopen")
    check(len(api("routing")["plugins"]) == 2, "keine doppelte Migration")


@t("routing_wet_level_flow")
def _():
    # Pegel je Kante (setEdge, linear 0..1 am AuxSend) und Dry/Wet je Modul
    # (setWet, Rack-Wrap — ein Knopf wie beim Synth: wet = Anteil durchs
    # Plugin, der Rest geht trocken weiter). Beides Verfeinerung: geloggt,
    # keine Node-Aktion.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-wetlevel-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="wetlevel").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    check(api("addClip", track=0, file=w, section="Section 1").get("ok") is True, "addClip")
    out = os.path.join(d, "out.wav")

    def peak():
        api("render", file=out)
        return api("peak").get("peak", 0)

    full = peak()
    check(full > 0.1, f"Audio an Main: {full}")
    n_actions = len(api("treeState")["nodes"][0]["actions"])

    r = api("setEdge", **{"from": "t0", "to": "main", "level": 0.5})
    check(r.get("ok") is True and abs(r.get("level", 0) - 0.5) < 0.001, f"setEdge: {r}")
    check(abs(peak() - full / 2) < 0.01, "halber Pegel halbiert den Peak")
    check(api("routing")["edges"][0]["level"] == 0.5, "routing meldet den Pegel")
    for args, err in (({"from": "t0", "to": "main", "level": 1.5}, "level must be 0..1"),
                      ({"from": "t0", "to": "p9", "level": 0.5}, "no such node: p9"),
                      ({"from": "main", "to": "t0", "level": 0.5}, "not connected")):
        r = api("setEdge", **args)
        check(r.get("ok") is False and r.get("error") == err, f"setEdge {args}: {r}")
    api("setEdge", **{"from": "t0", "to": "main", "level": 1.0})

    # connect mit Pegel
    lp = api("addPlugin", name="Low Pass")["id"]
    check(api("connect", **{"from": "t0", "to": lp, "level": 0.25}).get("level") == 0.25, "connect level")
    m = {r["from"]: {c["to"]: c for c in r["cells"]} for r in api("routing")["matrix"]}
    check(m["t0"][lp]["connected"] and m["t0"][lp]["level"] == 0.25, f"Zelle mit Pegel: {m['t0'][lp]}")
    check(api("connect", **{"from": lp, "to": "main", "level": 2}).get("error") == "level must be 0..1",
          "connect level validiert")
    api("disconnect", **{"from": "t0", "to": lp})

    # Wet: 0 = nur trocken (wie ohne Plugin), 1 = nur durchs Plugin
    api("disconnect", **{"from": "t0", "to": "main"})
    api("connect", **{"from": "t0", "to": lp})
    api("connect", **{"from": lp, "to": "main"})
    check([p["wet"] for p in api("routing")["plugins"]] == [1.0], "Default wet 1")
    r = api("setWet", plugin=lp, wet=0.0)
    check(r.get("ok") is True and r.get("wet") == 0.0, f"setWet: {r}")
    check(abs(peak() - full) < 0.001, "wet 0 = trockenes Signal")

    # Instrument: wet wirkt als Pegel (trocken ist dort nur MIDI)
    api("trackMix", track=0, volumeDb=-100.0)   # Audio-Spur aus der Messung (Mute gilt dort nicht)
    r = api("addMidiClip", track=-1, section="Section 1", notes=[{"pitch": 60, "start": 0, "length": 1}])
    osc = api("addPlugin", name="4OSC", track=r["laneOf"], at="end")["id"]
    api("connect", **{"from": osc, "to": "main"})
    loud = peak()
    api("setWet", plugin=osc, wet=0.5)
    check(abs(peak() - loud / 2) < 0.01, "Instrument wet 0.5 halbiert")

    mod = api("addPlugin", name="MIDI Modifier")["id"]
    for args, err in (({"plugin": mod, "wet": 0.5}, "midi plugins have no wet/dry"),
                      ({"plugin": lp, "wet": 2}, "wet must be 0..1"),
                      ({"plugin": "p99", "wet": 0.5}, "no such plugin: p99")):
        r = api("setWet", **args)
        check(r.get("ok") is False and r.get("error") == err, f"setWet {args}: {r}")
    check(next(p for p in api("routing")["plugins"] if p["id"] == mod)["wet"] is None, "MIDI-FX ohne wet")

    acts = api("treeState")["nodes"][0]["actions"]
    fine = [(a["op"], (a.get("params") or {}).get("plugin"), (a.get("params") or {}).get("from")) for a in acts if a["op"] in ("setEdge", "setWet")]
    check(len(fine) == len(set(fine)), f"Feinschliff je Modul zusammengefasst: {fine}")
    check(len(acts) > n_actions, "connect/addPlugin bleiben Aktionen")


@t("routing_v1_upgrade")
def _():
    # Edits aus der ersten Routing-Version (v1: Kante nach Main = Track-
    # Output auf Master, Modul-Plugin ohne Rack) werden beim Laden v2:
    # Main-Bus-Send mit Pegel 1, Plugin im Rack (Dry/Wet), Klang bleibt.
    import xml.etree.ElementTree as ET
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-routv1-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="v1").get("ok") is True, "seed")
    api("addClip", track=0, file=w, section="Section 1")
    api("addPlugin", name="Reverb", track=0, at="end")
    api("treeClose")

    f = os.path.join(d, "node-1.tracktionedit")
    tree = ET.parse(f)
    root = tree.getroot()
    root.set("dawdRouting", "1")
    racks = root.find("RACKS")
    for tr in root.findall("TRACK"):
        if tr.get("dawdRole") == "main":
            root.remove(tr)
            continue
        for pl in list(tr.findall("PLUGIN")):
            if pl.get("type") == "auxsend" and pl.get("busNum") == "0":
                tr.remove(pl)
                tr.find("OUTPUTDEVICES/DEVICE").set("name", "(default audio output)")
            elif pl.get("type") == "rack":
                rack = next(r for r in racks.findall("RACK") if r.get("id") == pl.get("rackType"))
                inner = rack.find("PLUGININSTANCE/PLUGIN")
                idx = list(tr).index(pl)
                tr.remove(pl)
                tr.insert(idx, inner)
                racks.remove(rack)
    tree.write(f, encoding="UTF-8", xml_declaration=True)
    xml_v1 = open(f).read()
    check('type="rack"' not in xml_v1 and 'dawdRole="main"' not in xml_v1, "v1-Datei gebaut")

    check(api("treeOpen", dir=d).get("ok") is True, "open v1")
    rt = api("routing")
    edges = {(e["from"], e["to"], e["level"]) for e in rt["edges"]}
    check(edges == {("t0", "p1", 1.0), ("p1", "main", 1.0)}, f"Kanten nach Upgrade: {edges}")
    check(rt["plugins"][0]["name"] == "Reverb" and rt["plugins"][0]["wet"] == 1.0, f"Rack-Wrap: {rt['plugins']}")
    xml = api("dump")["xml"]
    check(xml.count('type="rack"') == 1 and 'dawdRouting="2"' in xml, "Rack + Version 2")
    api("render", file=os.path.join(d, "v1.wav"))
    check(api("peak").get("peak", 0) > 0.1, "klingt nach dem Upgrade")


def _envelope(path, win=0.1, seconds=2.0):
    """Max |Pegel| je Fenster (Sekunden) einer gerenderten WAV."""
    with wave.open(path) as f:
        n, ch, sw, sr = f.getnframes(), f.getnchannels(), f.getsampwidth(), f.getframerate()
        raw = f.readframes(n)
    vals = [abs(int.from_bytes(raw[i:i + sw], "little", signed=True)) / (2 ** (8 * sw - 1))
            for i in range(0, n * ch * sw, ch * sw)]
    w = int(sr * win)
    return [max(vals[k:k + w]) for k in range(0, min(len(vals), int(sr * seconds)), w)]


@t("routing_feedback_flow")
def _():
    # Feedback-Kanten (Complex-Mode): das Signal geht verzoegert (>= ein
    # Audio-Block) zurueck in ein Modul — auch in sich selbst. Mit Pegel <
    # 100 % klingt die Schleife aus (Echos), Soft-Clip haelt 100 % begrenzt.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-feedback-")
    burst = os.path.join(d, "burst.wav")
    with wave.open(burst, "w") as f:
        f.setnchannels(1); f.setsampwidth(2); f.setframerate(44100)
        f.writeframes(b"".join(struct.pack("<h", int(12000 * (i % 100 < 50)) if i < 4410 else 0)
                               for i in range(44100 * 3)))
    check(api("treeSeed", dir=d, label="fb").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    check(api("addClip", track=0, file=burst, section="Section 1").get("ok") is True, "addClip")
    eq = api("addPlugin", name="Equaliser", track=0, at="end")["id"]
    out = os.path.join(d, "out.wav")

    api("render", file=out)
    dry = _envelope(out)
    check(dry[0] > 0.1 and max(dry[1:]) < 0.001, f"ohne Feedback nur der Ton: {dry[:6]}")

    # Normale Kante in sich selbst bleibt verboten — als Feedback geht sie
    check(api("connect", **{"from": eq, "to": eq}).get("error") == "would create a loop", "Schleife normal verboten")
    r = api("connect", **{"from": eq, "to": eq, "feedback": True, "level": 0.7, "delayMs": 300})
    check(r.get("ok") is True and r.get("feedback") is True, f"Feedback-Kante: {r}")
    fb = api("routing")["feedback"]
    check(len(fb) == 1 and fb[0]["from"] == eq and fb[0]["to"] == eq and fb[0]["level"] == 0.7
          and fb[0]["delayMs"] == 300 and fb[0]["minDelayMs"] >= 0, f"routing.feedback: {fb}")
    api("render", file=out)
    env = _envelope(out)
    # Echos alle 300 ms, jeweils um 0.7 leiser
    check(env[3] > 0.1 and abs(env[3] / env[0] - 0.7) < 0.08 and abs(env[6] / env[3] - 0.7) < 0.08,
          f"Echos 300 ms / 70 %: {[round(x, 3) for x in env[:10]]}")
    check(max(env[1:3]) < 0.001, "zwischen den Echos still")

    # 100 % mit kleinster Verzoegerung: begrenzt, explodiert nicht
    r = api("setEdge", **{"from": eq, "to": eq, "feedback": True, "level": 1.0, "delayMs": 0})
    check(r.get("ok") is True, f"setEdge feedback: {r}")
    api("render", file=out)
    check(api("peak").get("peak", 99) < 4.0, "Soft-Clip begrenzt die Schleife")

    # Regeln
    osc = api("addPlugin", name="4OSC")["id"]
    for args, err in (({"from": "t0", "to": "main"}, "feedback goes into a plugin"),
                      ({"from": eq, "to": osc}, "feedback is audio only"),
                      ({"from": eq, "to": eq}, "already connected"),
                      ({"from": "main", "to": eq}, "main has no output")):
        r = api("connect", feedback=True, **args)
        check(r.get("ok") is False and r.get("error") == err, f"feedback {args}: {r}")
    check(api("setEdge", **{"from": eq, "to": eq, "feedback": True, "level": 2}).get("error")
          == "level must be 0..1", "level validiert")
    check(api("setEdge", **{"from": eq, "to": eq, "feedback": True, "delayMs": 5000}).get("error")
          == "delayMs must be 0..2000", "delay validiert")

    # Kreis ueber zwei Module: eq -> rev normal, rev -> eq als Feedback
    rev = api("addPlugin", name="Reverb")["id"]
    check(api("connect", **{"from": eq, "to": rev}).get("ok") is True, "eq -> rev")
    m = {r["from"]: {c["to"]: c for c in r["cells"]} for r in api("routing")["matrix"]}
    check(m[rev][eq]["reason"] == "would create a loop" and m[rev][eq]["feedbackReason"] == "",
          f"Zelle rev/eq: Feedback moeglich: {m[rev][eq]}")
    check(api("connect", **{"from": rev, "to": eq, "feedback": True}).get("ok") is True, "rev ~> eq")
    check(m[eq][eq]["feedback"] is not None, "Zelle eq/eq traegt die Feedback-Kante")

    # disconnect und removePlugin raeumen die Feedback-Kanten
    check(api("disconnect", **{"from": eq, "to": eq, "feedback": True}).get("ok") is True, "disconnect feedback")
    check(api("disconnect", **{"from": eq, "to": eq, "feedback": True}).get("error") == "not connected", "zweimal")
    check(api("removePlugin", plugin=rev).get("ok") is True, "removePlugin")
    check(api("routing")["feedback"] == [], "Feedback-Kanten des Moduls weg")
    xml = api("dump")["xml"]
    check("dawdFeedback" not in xml, "keine halben Feedback-Plugins im Edit")
    api("render", file=out)
    env = _envelope(out)
    check(max(env[1:]) < 0.001, "nach dem Abbau wieder trocken")

    # Feedback ist eine Node-Aktion (connect mit feedback)
    acts = [a for a in api("treeState")["nodes"][0]["actions"] if a["op"] == "connect"]
    check(any(a["params"].get("feedback") for a in acts), f"Aktion mit feedback: {acts}")


@t("routing_simple_chain_flow")
def _():
    # Simple-Mode: je Spur eine Kette (setChain), dasselbe Plugin in zwei
    # Ketten an verschiedener Stelle = verlinkte Instanzen (linkPlugin:
    # gleiche Einstellungen, eigenes Signal), Sends mit Pegel auf Busse;
    # routing.chains ist die Simple-Sicht samt complex-Markierung.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-chain-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=1.0)
    check(api("treeSeed", dir=d, label="chain").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)  # mischt Sorten in einem Node — Auto-Branch: auto_branch_flow
    api("addClip", track=0, file=w, section="Section 1")
    r = api("addClip", track=-1, file=w, section="Section 1")
    t2 = r["laneOf"]
    rev = api("addPlugin", name="Reverb")["id"]
    comp = api("addPlugin", name="Compressor")["id"]

    # Spur 1: Reverb -> Compressor -> Main
    r = api("setChain", track=0, plugins=[rev, comp])
    check(r.get("ok") is True, f"setChain t0: {r}")
    ch = {c["id"]: c for c in api("routing")["chains"]}
    check(ch["t0"]["plugins"] == [rev, comp] and ch["t0"]["toMain"] and ch["t0"]["complex"] == [],
          f"Kette t0: {ch['t0']}")

    # Spur 2 will dieselben in anderer Reihenfolge: geteilt -> verlinken
    r = api("setChain", track=t2, plugins=[comp, rev])
    check(r.get("error") == f"{rev} is shared — link it for this track instead", f"geteilt: {r}")
    c2 = api("linkPlugin", plugin=comp)
    r2 = api("linkPlugin", plugin=rev)
    check(c2.get("ok") and c2.get("link") == comp and r2.get("link") == rev, f"linkPlugin: {c2} {r2}")
    r = api("setChain", track=t2, plugins=[c2["id"], r2["id"]])
    check(r.get("ok") is True, f"setChain t2: {r}")
    rt = api("routing")
    ch = {c["id"]: c for c in rt["chains"]}
    check(ch[f"t{t2}"]["plugins"] == [c2["id"], r2["id"]], f"Kette t2: {ch}")
    links = {p["id"]: p["link"] for p in rt["plugins"]}
    check(links == {rev: rev, comp: comp, c2["id"]: comp, r2["id"]: rev}, f"Link-Gruppen: {links}")

    # Gleiche Einstellungen: ein Parameter wirkt in der ganzen Gruppe
    name = api("listParameters", plugin=rev)["parameters"][0]["name"]
    r = api("setParameter", plugin=rev, name=name, value=0.9)
    check(r.get("linked") == [r2["id"]], f"setParameter folgt dem Link: {r}")
    v = api("listParameters", plugin=r2["id"])["parameters"][0]["value"]
    check(abs(v - 0.9) < 0.001, f"verlinkter Wert: {v}")
    # Wet bleibt je Instanz
    api("setWet", plugin=rev, wet=0.2)
    wets = {p["id"]: p["wet"] for p in api("routing")["plugins"]}
    check(wets[rev] == 0.2 and wets[r2["id"]] == 1.0, f"Wet je Instanz: {wets}")

    # Umsortieren und Typ-Fehler mit Zurueckrollen
    check(api("setChain", track=0, plugins=[comp, rev]).get("ok") is True, "umsortieren")
    check({c["id"]: c for c in api("routing")["chains"]}["t0"]["plugins"] == [comp, rev], "neue Reihenfolge")
    osc = api("addPlugin", name="4OSC")["id"]
    before = api("routing")["edges"]
    r = api("setChain", track=0, plugins=[osc])
    check(r.get("error") == f"t0 > {osc}: audio cannot enter a midi plugin", f"Typ-Fehler: {r}")
    check(api("routing")["edges"] == before, "Zurueckgerollt")
    for args, err in (({"track": 0, "plugins": [rev, rev]}, f"{rev} twice in the chain — link it instead"),
                      ({"track": 0, "plugins": ["p99"]}, "no such plugin: p99"),
                      ({"track": 0, "plugins": "p1"}, "plugins must be a list"),
                      ({"track": 1, "plugins": []}, f"t1 is a lane — route its track t0")):
        r = api("setChain", **args)
        check(r.get("ok") is False and r.get("error") == err, f"setChain {args}: {r}")

    # Hoerbar und beide Ketten fuehren nach Main
    api("render", file=os.path.join(d, "o.wav"))
    check(api("peak").get("peak", 0) > 0.05, "beide Ketten klingen")

    # Send auf einen Bus: gehoert nicht zur Kette
    bus = api("addPlugin", name="Delay")["id"]
    api("connect", **{"from": bus, "to": "main"})
    r = api("connect", **{"from": "t0", "to": bus, "level": 0.3, "send": True})
    check(r.get("ok") is True, f"Send: {r}")
    c0 = {c["id"]: c for c in api("routing")["chains"]}["t0"]
    check(c0["plugins"] == [comp, rev] and c0["sends"] == [{"ok": True, "to": bus, "level": 0.3}]
          and c0["complex"] == [], f"Kette + Send: {c0}")
    check(any(e["send"] for e in api("routing")["edges"] if e["from"] == "t0" and e["to"] == bus),
          "Kante als Send markiert")

    # Complex-Teile markiert: Feedback in der Kette
    api("connect", **{"from": rev, "to": comp, "feedback": True})
    c0 = {c["id"]: c for c in api("routing")["chains"]}["t0"]
    check(c0["complex"] == [f"feedback {rev} > {comp}"], f"complex markiert: {c0['complex']}")

    # Leere Kette = Spur direkt auf Main
    check(api("setChain", track=t2, plugins=[]).get("ok") is True, "leere Kette")
    c = {c["id"]: c for c in api("routing")["chains"]}[f"t{t2}"]
    check(c["plugins"] == [] and c["toMain"], f"direkt auf Main: {c}")

    ops = [a["op"] for a in api("treeState")["nodes"][0]["actions"]]
    check(ops.count("setChain") == 4 and ops.count("linkPlugin") == 2, f"Aktionen: {ops}")


@t("tree_v2_migration")
def _():
    # v2-tree.json (kinds section/audio/midi/processing) wird beim Laden
    # gemappt: Clip-Edit und Plugins sind process, alles andere collect.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-v2mig-")
    r = api("treeSeed", dir=d, label="legacy2")
    check(r.get("ok") is True, f"seed: {r}")
    api("treeClose")

    # v2-Aktionen mit alten Kinds einsetzen
    tf = os.path.join(d, "tree.json")
    with open(tf) as f:
        js = json.load(f)

    def act(i, kind, op, **params):
        return {"id": i, "kind": kind, "op": op, "params": params, "file": "",
                "created": "2026-10-01T00:00:00Z"}

    js["nodes"][0]["actions"] = [
        act(1, "section", "addSection"),
        act(2, "audio", "addClip", **{"section": "Seed", "track": 0, "type": "audio"}),
        act(3, "audio", "deleteClip", **{"track": 0, "name": "x"}),
        act(4, "processing", "addPlugin", **{"plugin": "p", "track": 0}),
    ]
    with open(tf, "w") as f:
        json.dump(js, f)

    r = api("treeOpen", dir=d)
    check(r.get("ok") is True, f"open v2: {r}")
    acts = api("treeState")["nodes"][0].get("actions", [])
    check(len(acts) == 4, f"actions: {acts}")
    kinds = [a["kind"] for a in acts]
    check(kinds == ["collect", "collect", "process", "process"], f"mapped kinds: {kinds}")

    # Take-Daten leiten sich weiter ab (Typ steht in den params)
    n = api("treeState")["nodes"][0]
    check(n["takeType"] == "audio" and n["takeSection"] == "Seed" and n["takeTrack"] == 0,
          f"take data after migration: {n}")


@t("undo_flow")
def _():
    # Undo/Redo ueber Schnappschuesse: Edit und Aktionen des Nodes zurueck;
    # ein per Auto-Branch angelegter Node verschwindet beim Undo und kommt
    # beim Redo mit gleicher Id zurueck; Baum-Daten (Label) bleiben; eine neue
    # Aktion verwirft Redo; Projektwechsel loescht die Historie.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-undo-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="undo").get("ok") is True, "seed")
    secs = lambda: {x["name"] for x in api("state")["sections"]}

    check(api("addSection", name="A", length=4).get("ok") is True, "A")
    u = api("state")["undo"]
    check(u["canUndo"] is True and u["undoOp"] == "addSection" and u["canRedo"] is False, f"state.undo: {u}")
    r = api("undo")
    check(r.get("ok") is True and r.get("undone") == ["addSection"] and "A" not in secs(), f"undo A: {r}")
    check(api("treeState")["nodes"][0]["actions"] == [], "Aktion mit zurueckgenommen")
    r = api("redo")
    check(r.get("ok") is True and "A" in secs() and len(api("treeState")["nodes"][0]["actions"]) == 1, f"redo A: {r}")

    # Feinschliff (die Spur entsteht mit dem Clip)
    check(api("addClip", track=0, file=w, section="A").get("ok") is True, "addClip")
    api("trackMix", track=0, volumeDb=-6)
    api("undo")
    check(api("state")["trackList"][0]["volumeDb"] == 0.0, "trackMix zurueck")
    api("redo")
    check(api("state")["trackList"][0]["volumeDb"] == -6.0, "trackMix wieder da")

    # Auto-Branch-Node: Undo entfernt ihn, Redo holt ihn mit gleicher Id
    # (Master-Kette = Fokus "song", die Spur-Arbeit davor lag auf Track 1)
    r = api("addPlugin", name="Compressor", at="master")
    node = r.get("autoNode", {}).get("node")
    parent = r.get("autoNode", {}).get("parent")
    check(node is not None, f"Auto-Node: {r}")
    api("treeLabel", node=1, label="renamed")
    r = api("undo")
    ts = api("treeState")
    check(r.get("ok") is True and ts["current"] == parent and node not in [n["id"] for n in ts["nodes"]]
          and not os.path.exists(os.path.join(d, f"node-{node}.tracktionedit"))
          and api("routing")["plugins"] == [], f"Auto-Node weg: {r}")
    check(ts["nodes"][0]["label"] == "renamed", "Baum-Daten bleiben (Label)")
    r = api("redo")
    ts = api("treeState")
    n = {x["id"]: x for x in ts["nodes"]}.get(node, {})
    check(r.get("ok") is True and ts["current"] == node and n.get("auto") is True
          and [a["op"] for a in n.get("actions", [])] == ["addPlugin"] and len(api("routing")["plugins"]) == 1,
          f"Auto-Node zurueck: {r} {n}")

    # Mehrere Schritte, neue Aktion verwirft Redo
    api("treeSettings", autoBranch=False)
    api("addSection", name="B", length=2)
    api("addSection", name="C", length=2)
    r = api("undo", steps=2)
    check(r.get("undone") == ["addSection", "addSection"] and not {"B", "C"} & secs(), f"zwei Schritte: {r}")
    api("addSection", name="D", length=2)
    check(api("redo").get("error") == "nothing to redo", "neue Aktion verwirft Redo")

    # Manuell weiterverzweigt: Undo stoppt beim Auto-Node
    api("treeSettings", autoBranch=True)
    r = api("favoriteSection", name="A")
    sel = r.get("autoNode", {}).get("node")
    check(api("treeBranch", label="hand").get("ok") is True, "von Hand verzweigt")
    api("treeCheckout", node=sel)
    r = api("undo")
    check(r.get("ok") is False and r.get("error") == f"node {sel} has branches now — undo stops here", f"Stopp: {r}")

    # Projektwechsel loescht die Historie
    api("treeClose")
    api("treeOpen", dir=d)
    check(api("state")["undo"]["canUndo"] is False and api("undo").get("error") == "nothing to undo",
          "Historie nach treeOpen leer")
    api("treeClose")


@t("undo_delete_auto_node")
def _():
    # deleteClip legt per Auto-Branch einen process-Node an (aus einem
    # select-Node — im collect-Node bleibt Clip-Bearbeitung seit Praxistest 1
    # im Node); undoDelete holt den Clip zurueck und raeumt den leer
    # gewordenen Auto-Node weg.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-undodel-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="ud").get("ok") is True, "seed")
    r = api("addClip", track=0, file=w, section="Section 1")
    track = r.get("track")
    clip = api("state")["trackList"][track]["clips"][0]["name"]
    sel = api("favoriteClip", track=track, name=clip).get("autoNode", {}).get("node")
    check(sel is not None, "favoriteClip legt einen select-Node an")
    r = api("deleteClip", track=track, name=clip)
    node = r.get("autoNode", {}).get("node")
    check(r.get("ok") is True and node is not None, f"deleteClip im Auto-Node: {r}")
    r = api("undoDelete", undo=r.get("undo"))
    ts = api("treeState")
    check(r.get("ok") is True and r.get("removedNode") == node and ts["current"] == sel
          and node not in [n["id"] for n in ts["nodes"]], f"leerer Auto-Node weg: {r}")
    check(any(c["name"] == clip for t in api("state")["trackList"] for c in t["clips"]), "Clip zurueck")
    check(api("state")["undo"]["undoOp"] == "favoriteClip", f"Undo-Historie ohne den Auto-Node: {api('state')['undo']}")
    api("treeClose")


@t("batch_flow")
def _():
    # batch: mehrere Befehle in einem Aufruf, jeder ueber executeOp (Version,
    # Auto-Branch, Event-Log je Befehl); stopOnError (Default) bricht beim
    # ersten Fehler ab und markiert den Rest als skipped; nicht transaktional.
    # Das Log nur ab hier lesen: fruehere Tests (recipe_flow: saveRecipe mit
    # Schritt batch) duerfen "op": "batch" als Parameter geloggt haben
    events = os.path.join(os.path.dirname(INSTANCE_ERR), "events.jsonl")
    log_start = os.path.getsize(events) if os.path.exists(events) else 0
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-batch-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="batch").get("ok") is True, "seed")
    v0 = api("state")["version"]
    r = api("batch", commands=[{"op": "addSection", "name": "X", "length": 4},
                               {"op": "addSection", "name": "Y", "length": 4},
                               {"op": "updateSection", "name": "Y", "bpm": 90}])
    check(r.get("ok") is True and r.get("failed") == -1 and [x["ok"] for x in r["results"]] == [True] * 3
          and [x["op"] for x in r["results"]] == ["addSection", "addSection", "updateSection"],
          f"drei Befehle: {r}")
    check(r.get("version") == v0 + 3, f"Version je Befehl: {v0} -> {r.get('version')}")
    check({x["name"] for x in api("state")["sections"]} >= {"X", "Y"}, "Sections da")

    # Auto-Branch je Befehl: collect, dann process im selben Batch
    r = api("batch", commands=[{"op": "addClip", "track": 0, "file": w, "section": "X"},
                               {"op": "addPlugin", "name": "Compressor", "track": 0, "at": "end"}])
    # erst Fokus-Wechsel (Sections -> Spur), dann Sorten-Wechsel (collect -> process)
    check(r.get("ok") is True and r["results"][0].get("autoNode", {}).get("label", "").endswith(": Notes")
          and r["results"][1].get("autoNode", {}).get("kind") == "process", f"Auto-Branch im Batch: {r}")

    # stopOnError (Default): Abbruch beim ersten Fehler, Rest skipped
    r = api("batch", commands=[{"op": "addSection", "name": "Z", "length": 2},
                               {"op": "addSection", "name": "Z", "length": 2},
                               {"op": "addSection", "name": "W", "length": 2}])
    names = {x["name"] for x in api("state")["sections"]}
    check(r.get("ok") is False and r.get("failed") == 1 and r["results"][1].get("error") == "section exists: Z"
          and r["results"][2].get("skipped") is True and "Z" in names and "W" not in names,
          f"stopOnError: {r} {names}")
    r = api("batch", stopOnError=False,
            commands=[{"op": "addSection", "name": "Z", "length": 2}, {"op": "addSection", "name": "W", "length": 2}])
    check(r.get("ok") is False and r.get("failed") == 0 and r["results"][1].get("ok") is True
          and "W" in {x["name"] for x in api("state")["sections"]}, f"weiter nach Fehler: {r}")

    # Verboten und Grenzen
    r = api("batch", commands=[{"op": "quit"}, {"op": "batch", "commands": []}, {"name": "x"}])
    check([x.get("error") for x in r.get("results", [])] == ["quit is not allowed in a batch", None, None]
          and r["results"][1].get("skipped") is True, f"quit im Batch: {r}")
    r = api("batch", stopOnError=False, commands=[{"op": "batch", "commands": []}, {"name": "x"}])
    check([x.get("error") for x in r["results"]] == ["batch is not allowed in a batch", "missing op"], f"verschachtelt: {r}")
    check(api("batch").get("error") == "commands must be a non-empty array", "ohne commands")
    check(api("batch", commands=[{"op": "ping"}] * 201).get("error") == "too many commands (max 200)", "Grenze")
    check(api("ping").get("ok") is True, "Daemon laeuft weiter (quit nicht ausgefuehrt)")

    # Log: die Befehle einzeln, der Batch selbst nicht
    with open(events, "rb") as f:
        f.seek(log_start)
        log = f.read().decode(errors="replace")
    import re
    check(not re.search(r'"op":\s*"batch"', log) and re.search(r'"op":\s*"updateSection"', log),
          "Einzelbefehle im Log, kein batch")
    api("treeClose")


@t("auto_branch_flow")
def _():
    # Der Baum baut sich aus den Aktionen: ein Kind-Node entsteht bei
    # Wechsel der Sorte (collect/select/process) oder des Fokus (andere
    # Spur, Song = Sections/Master-Kette; Praxistest 1d: ein Node hielt 24
    # Aktionen ueber alle Spuren). Label "<Spur>: Notes|Sound|Mix" bzw.
    # "Song: Arrangement"; Feinschliff (trackMix, setParameter …) ist eine
    # Aktion, je Spur/Modul zusammengefasst; Fehlschlag laesst keinen Node
    # zurueck; treeSettings schaltet es ab (gespeichert).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-autobranch-")
    w = os.path.join(d, "tone.wav")
    make_wav(w, seconds=2.0)
    check(api("treeSeed", dir=d, label="ab").get("ok") is True, "seed")
    check(api("treeState").get("autoBranch") is True, "autoBranch Default an")
    check(api("addClip", track=0, file=w, section="Section 1").get("ok") is True, "addClip (collect)")
    check("autoNode" not in api("addClip", track=0, file=w, section="Section 1", start=2), "gleiche Spur, gleiche Sorte: gleicher Node")
    r = api("addSection", name="B", length=4)
    check(r.get("autoNode", {}).get("label") == "Song: Arrangement", f"Fokus-Wechsel Spur -> Song: {r.get('autoNode')}")
    check(api("treeState")["nodes"][-1].get("focus") == "song", "Fokus am Node gespeichert")

    r = api("addPlugin", name="Compressor", track=0, at="end")
    an = r.get("autoNode", {})
    check(r.get("ok") is True and an.get("kind") == "process" and an.get("label") == "Track 1: Sound", f"Spur-Klang = neuer Node: {r}")
    ts = api("treeState")
    nodes = {n["id"]: n for n in ts["nodes"]}
    check(ts["current"] == an.get("node") and [a["op"] for a in nodes[an["node"]]["actions"]] == ["addPlugin"], f"Aktion am neuen Node: {ts}")
    check(any(c for t in api("state")["trackList"] for c in t["clips"]), "Edit kopiert (Clip da)")
    check("autoNode" not in api("connect", **{"from": r["id"], "to": "main"}), "Modul der Spur: gleicher Fokus")
    # Feinschliff gleicher Spur bleibt im Node und wird zusammengefasst
    check("autoNode" not in api("setParameter", plugin=r["id"], name="Ratio", value=0.3), "Parameter im Node")
    api("setParameter", plugin=r["id"], name="Threshold", value=0.4)
    check("autoNode" not in api("trackMix", track=0, volumeDb=-3), "trackMix bleibt im Node")
    acts = [a["op"] for a in api("treeState")["nodes"][-1]["actions"]]
    check(acts.count("setParameter") == 1 and "trackMix" in acts, f"Feinschliff zusammengefasst: {acts}")

    # andere Spur = neuer Node mit ihrem Namen
    t2 = api("createTrack", type="midi", instrument="4OSC", name="Keys")
    check(t2.get("autoNode", {}).get("label") == "Keys: Notes", f"neue Spur: {t2.get('autoNode')}")

    clip = next(c["name"] for t in api("state")["trackList"] for c in t["clips"])
    track = next(t["index"] for t in api("state")["trackList"] if t["clips"])
    r = api("favoriteClip", track=track, name=clip)
    check(r.get("autoNode", {}).get("kind") == "select", f"select = neuer Node: {r}")
    sel_node = api("treeState")["current"]

    # Fehlschlag: kein Node bleibt zurueck
    before = len(api("treeState")["nodes"])
    r = api("addPlugin", name="Nope")
    ts = api("treeState")
    check(r.get("ok") is False and r.get("error") == "unknown plugin: Nope"
          and len(ts["nodes"]) == before and ts["current"] == sel_node, f"Rueckbau: {r} {ts['current']}")

    # Abschalten: die Aktion landet im aktuellen Node, Einstellung bleibt
    check(api("treeSettings", autoBranch=False).get("autoBranch") is False, "abgeschaltet")
    r = api("addPlugin", name="Delay")
    check(r.get("ok") is True and "autoNode" not in r, f"ohne Auto-Branch: {r}")
    api("treeClose")
    api("treeOpen", dir=d)
    check(api("treeSettings").get("autoBranch") is False, "Einstellung gespeichert")
    api("treeClose")


@t("instrument_collect_flow")
def _():
    # MIDI-Spur mit Instrument im Collect: createTrack instrument und
    # pickInstrument verdrahten Spur -> Instrument -> Main (hoerbar) und
    # buchen eine collect-Aktion; jede neue Spur ist ein Fokus-Wechsel und
    # bekommt ihren Node ("<Spur>: Notes").
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-instr-")
    check(api("treeSeed", dir=d, label="instr").get("ok") is True, "seed")
    check(api("addSection", name="M", length=4).get("ok") is True, "Section")
    tracks_before = api("state")["tracks"]

    for args, err in [({"type": "midi", "instrument": "Reverb"}, "not an instrument: Reverb"),
                      ({"type": "midi", "instrument": "Nope"}, "unknown plugin: Nope"),
                      ({"type": "audio", "instrument": "4OSC"}, "instrument needs type midi")]:
        r = api("createTrack", **args)
        check(r.get("ok") is False and r.get("error") == err, f"createTrack {args}: {r}")
    check(api("state")["tracks"] == tracks_before, "Fehlschlaege ohne Spur")

    r = api("createTrack", type="midi", instrument="4OSC")
    check(r.get("ok") is True and r.get("instrument") == "4OSC", f"createTrack mit 4OSC: {r}")
    t, pid = r.get("index"), r.get("id")
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check((f"t{t}", pid) in edges and (pid, "main") in edges, f"Spur -> 4OSC -> Main: {edges}")
    cur = lambda: next(n for n in api("treeState")["nodes"] if n["id"] == api("treeState")["current"])
    acts = cur()["actions"]
    check(acts[-1]["kind"] == "collect" and acts[-1]["op"] == "createTrack"
          and acts[-1]["params"].get("instrument") == "4OSC" and r.get("autoNode", {}).get("kind") == "collect", f"collect-Aktion: {acts[-1]} {r.get('autoNode')}")
    check(api("addMidiClip", track=t, section="M", notes=[{"pitch": 60, "start": 0, "length": 1}]).get("ok") is True,
          "Noten")
    check(api("render", file=os.path.join(d, "i.wav")).get("ok") is True and api("peak").get("peak", 0) > 0.01,
          "hoerbar ohne Process")

    # Stumme MIDI-Spur nachtraeglich
    s = api("createTrack", type="midi").get("index")
    r = api("pickInstrument", track=s, instrument="4OSC")
    check(r.get("ok") is True, f"pickInstrument: {r}")
    check(cur()["actions"][-1]["op"] == "pickInstrument" and cur()["actions"][-1]["kind"] == "collect", "pickInstrument ist collect-Aktion")
    a = api("createTrack").get("index")
    check(api("pickInstrument", track=a, instrument="4OSC").get("error") == "not a MIDI track (createTrack {type: 'midi'} makes one)", "Audio-Spur")
    # Praxistest 1k: instrument ohne type macht eine MIDI-Spur
    r = api("createTrack", instrument="4OSC")
    edges = {(e["from"], e["to"]) for e in api("routing")["edges"]}
    check(r.get("ok") is True and r.get("instrument") == "4OSC" and (f"t{r['index']}", r["id"]) in edges, f"createTrack {{instrument}} ohne type: {r}")
    check(api("pickInstrument", track=99, instrument="4OSC").get("error") == "no such track: 99", "fehlende Spur")
    api("treeClose")


def make_sine(path, freq, amp, seconds=4.0, rate=44100, side=False):
    # side = Stereo mit R = -L (reines Seitensignal, Mitte null)
    import math
    with wave.open(path, "w") as w:
        w.setnchannels(2 if side else 1)
        w.setsampwidth(2)
        w.setframerate(rate)
        frames = []
        for i in range(int(seconds * rate)):
            v = int(amp * 32767 * math.sin(2 * math.pi * freq * i / rate))
            frames.append(struct.pack("<hh", v, -v) if side else struct.pack("<h", v))
        w.writeframes(b"".join(frames))


@t("analyze_file_stereo_flow")
def _():
    # Praxistest 1b: analyze {file, start?, end?} misst die Datei statt
    # still das Projekt; Stereo-Mass (Korrelation, Seite/Mitte gesamt und je
    # Band); compareReference auf stillem Projekt ist ein Fehler statt -100 dB.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-anafile-")
    mono = os.path.join(d, "mono.wav")
    make_sine(mono, 1000, 0.5)
    side = os.path.join(d, "side.wav")
    make_sine(side, 1000, 0.5, side=True)
    check(api("treeSeed", dir=d, label="anafile").get("ok") is True, "seed")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "Section 4 s")

    a = api("analyze", file=mono, start=1, end=3)
    st = a.get("stereo", {})
    check(a.get("ok") is True and a.get("source") == "file" and abs(a.get("duration", 0) - 2.0) < 0.05
          and st.get("mono") is True and st.get("correlation") == 1.0 and st.get("widthDb") == -100.0,
          f"analyze file mono: {a}")
    a = api("analyze", file=side)
    st = a.get("stereo", {})
    b1k = next((b for b in a.get("bands", []) if b["hz"] == 1000.0), {})
    check(a.get("ok") is True and st.get("correlation") == -1.0 and st.get("widthDb") == 40.0 and b1k.get("widthDb") == 40.0,
          f"analyze file Seitensignal: {st} {b1k}")
    for args, err in [({"file": os.path.join(d, "nope.wav")}, "no such file"),
                      ({"file": mono, "start": 3, "end": 2}, "need 0 <= start < end"),
                      ({"file": mono, "track": 0}, "file analyses the file")]:
        r = api("analyze", **args)
        check(r.get("ok") is False and r.get("error", "").startswith(err), f"analyze {args}: {r}")

    r = api("compareReference", file=mono, section="Section 1")
    check(r.get("ok") is False and r.get("error", "").startswith("the project is silent"), f"stilles Projekt: {r}")
    check(api("addClip", track=0, file=mono, section="Section 1").get("ok") is True, "Mono-Clip")
    r = api("compareReference", file=side, section="Section 1")
    ds = r["diff"]["stereo"]
    check(r.get("ok") is True and ds["correlationDelta"] is not None and "correlation" not in ds
          and abs(ds["correlationDelta"] - (ds["mixCorrelation"] - ds["referenceCorrelation"])) < 0.015
          and any("narrower" in h or "mono" in h for h in r.get("hints", [])), f"Breite im Vergleich: {r.get('diff', {}).get('stereo')} {r.get('hints')}")
    api("treeClose")


@t("compact_state_flow")
def _():
    # Praxistest 1b: state/routing mit compact ohne die Zell-Matrix (die
    # MCP-Schicht setzt compact fuer Agenten; detail: true bringt die
    # Gruende gruppiert als reasons, Praxistest 1l); das UI bekommt ohne
    # Parameter weiter alles.
    sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "mcp"))
    import unidaw_mcp
    check(unidaw_mcp.compact({"op": "state"}).get("compact") is True
          and unidaw_mcp.compact({"op": "routing", "detail": True}) == {"op": "routing", "detail": True, "compact": True, "reasons": True}
          and unidaw_mcp.compact({"op": "routing", "compact": False}).get("compact") is False
          and unidaw_mcp.compact({"op": "batch", "commands": [{"op": "state"}, {"op": "ping"}]})["commands"][0].get("compact") is True
          and "compact" not in unidaw_mcp.compact({"op": "ping"}), "MCP setzt compact")
    api("treeClose")
