@t("compare_reference_flow")
def _():
    # compareReference: Mix und Referenz gleich gemessen (LUFS, LRA, True
    # Peak, RMS, Spektral-Balance in Oktavbaendern relativ zur Gesamtleistung),
    # Differenz Mix - Referenz und Hinweise; Referenz auch als mp3, mp3/ogg/
    # flac auch als Clip; Stereo-Seitensignal, 32-kHz-Referenz (Baender ueber 0,9 *
    # Nyquist null), referenceEnd hinter dem Dateiende abgelehnt.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-ref-")
    mix = os.path.join(d, "mix.wav")
    make_sine(mix, 1000, 0.5)
    quieter = os.path.join(d, "ref-quiet.wav")
    make_sine(quieter, 1000, 0.25)                    # gleicher Ton, -6 dB
    bass = os.path.join(d, "ref-bass.wav")
    make_sine(bass, 125, 0.5)                         # andere Klangfarbe
    check(api("treeSeed", dir=d, label="ref").get("ok") is True, "seed")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "Section 4 s")
    check(api("addClip", track=0, file=mix, section="Section 1").get("ok") is True, "Mix")

    a = api("analyze", section="Section 1")
    bands = {b["hz"]: b["db"] for b in a.get("bands", [])}
    check(len(bands) == 10 and bands.get(1000.0, -100) > -0.5, f"analyze mit Spektral-Balance: {bands}")
    a = api("analyze", section="Section 1", track=0.0)
    check(a.get("ok") is True and type(a.get("track")) is int and a["track"] == 0, f"analyze track = gepruefter Index: {a.get('track')!r}")

    r = api("compareReference", file=quieter, section="Section 1")
    diff = r.get("diff", {})
    b1k = {b["hz"]: b["db"] for b in diff.get("bands", [])}.get(1000.0)
    check(r.get("ok") is True and abs(diff.get("lufs", 0) - 6.0) < 0.5 and b1k is not None and abs(b1k) < 0.5,
          f"6 dB lauter, gleiche Klangfarbe: {diff}")
    check(any("louder than the reference" in h for h in r.get("hints", [])), f"Hinweis Lautheit: {r.get('hints')}")

    r = api("compareReference", file=bass, section="Section 1")
    hints = " | ".join(r.get("hints", []))
    check(r.get("ok") is True and "125" in hints and "1 kHz" in hints and abs(r["diff"]["lufs"] or 0) < 2.5,
          f"Klangfarbe anders (125 Hz vs 1 kHz): {hints} {r.get('diff', {}).get('lufs')}")

    # mp3-Referenz (ffmpeg erzeugt sie; ohne ffmpeg skip)
    mp3 = os.path.join(d, "ref.mp3")
    if shutil.which("ffmpeg") and subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", quieter, mp3]).returncode == 0:
        r = api("compareReference", file=mp3, section="Section 1")
        check(r.get("ok") is True and abs(r["diff"]["lufs"] - 6.0) < 0.7, f"mp3-Referenz: {r.get('diff', {}).get('lufs')} {r.get('error')}")
        # Komprimierte Formate auch als Clip: einmal nach media/<name>.<ext>.wav
        # dekodiert (ein Render mit ogg/mp3 im Edit kaeme sonst nicht zurueck),
        # Laenge und Lautheit wie die wav
        a_wav = api("analyze", section="Section 1")
        for ext in ("mp3", "ogg", "flac"):
            src = os.path.join(d, "mix." + ext)
            subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", mix, src], check=True)
            check(api("addSection", name=ext, length=4).get("ok") is True, f"Section {ext}")
            c = api("addClip", track=-1, file=src, section=ext)   # eigene Spur — eine neue Lane auf 0 stellte Section 1 stumm
            check(c.get("ok") is True and abs(c.get("length", 0) - 4.0) < 0.1, f"addClip {ext}: {c}")
            check(os.path.exists(os.path.join(d, "media", "mix." + ext + ".wav")), f"{ext} nach media/ dekodiert")
            a = api("analyze", section=ext)
            # mp3: ~50 ms Encoder-Delay vorne, das Ende faellt am Section-Ende weg (wie beim mp3-Referenztest 0,7)
            check(a.get("ok") is True and abs(a["lufs"] - a_wav["lufs"]) < 0.7, f"{ext}-Clip klingt wie die wav: {a.get('lufs')} vs {a_wav.get('lufs')}")
    else:
        print("    skip mp3 reference (no ffmpeg)")

    # Stereo-Seitensignal (R = -L): im Kanalmittel waere es weg; je Kanal
    # gemessen hat die Referenz dieselbe Klangfarbe wie der Mix
    side = os.path.join(d, "ref-side.wav")
    make_sine(side, 1000, 0.5, side=True)
    r = api("compareReference", file=side, section="Section 1")
    b1k = {b["hz"]: b["db"] for b in r.get("diff", {}).get("bands", [])}.get(1000.0)
    ref1k = {b["hz"]: b["db"] for b in r.get("reference", {}).get("bands", [])}.get(1000.0)
    check(r.get("ok") is True and ref1k is not None and ref1k > -0.5 and b1k is not None and abs(b1k) < 0.5
          and not any("missing" in h for h in r.get("hints", [])),
          f"Seitensignal-Referenz: ref 1k {ref1k}, diff 1k {b1k}, {r.get('hints')}")

    # 32-kHz-Referenz: das 16-kHz-Band liegt an Nyquist und ist null; die
    # Hoehen im Mix (18 kHz) sind kein "strong in the mix", 1 kHz bleibt gleich
    hi = os.path.join(d, "hi.wav")
    make_sine(hi, 18000, 0.4)                         # ohne Bezug auf gemeinsame Baender laege 1 kHz -2 dB
    t_hi = api("createTrack").get("index")
    check(api("addClip", track=t_hi, file=hi, section="Section 1").get("ok") is True, "Hoehen-Spur")
    ref32 = os.path.join(d, "ref-32k.wav")
    make_sine(ref32, 1000, 0.5, rate=32000)
    r = api("compareReference", file=ref32, section="Section 1")
    rb = {b["hz"]: b["db"] for b in r.get("reference", {}).get("bands", [])}
    db = {b["hz"]: b["db"] for b in r.get("diff", {}).get("bands", [])}
    hints = " | ".join(r.get("hints", []))
    check(r.get("ok") is True and 16000.0 in rb and rb[16000.0] is None and db.get(16000.0) is None
          and "16 kHz" not in hints and db.get(1000.0) is not None and abs(db[1000.0]) < 0.5,
          f"32-kHz-Referenz: ref 16k {rb.get(16000.0)}, diff 16k {db.get(16000.0)}, diff 1k {db.get(1000.0)}, {hints}")

    # Fehler: Texte sind API-Vertrag
    bad = os.path.join(d, "bad.wav")
    with open(bad, "w") as f:
        f.write("not audio")
    for args, err in [({"file": os.path.join(d, "nope.wav")}, "no such file: " + os.path.join(d, "nope.wav")),
                      ({"file": bad}, "cannot read reference: bad.wav"),
                      ({"file": quieter, "referenceStart": 99}, "need 0 <= referenceStart < referenceEnd within the file"),
                      ({"file": quieter, "referenceEnd": 5}, "need 0 <= referenceStart < referenceEnd within the file"),
                      ({"file": quieter, "section": "Nope"}, "no such section: Nope")]:
        r = api("compareReference", **args)
        check(r.get("ok") is False and r.get("error") == err, f"compareReference {args}: {r}")
    api("treeClose")


def make_groove(path, bpm, offset, seconds, meter=4, rate=44100):
    """Synthetischer Groove: Kick auf 1 (und 3 im 4er-Takt), Snare auf den
    uebrigen Schlaegen, Hi-Hat auf Achteln, Bass + Akkord wechseln je Takt
    (A-Moll, F, C, G) — Tempo, Takt und Takt-Eins sind bekannt."""
    import math, random
    rnd = random.Random(1)
    n = int(seconds * rate)
    buf = [0.0] * n
    beat = 60.0 / bpm

    def add(t0, fn, dur):
        s0 = int(t0 * rate)
        for i in range(max(0, -s0), min(int(dur * rate), n - s0)):
            buf[s0 + i] += fn(i / rate)

    k, t = 0, offset
    while t < seconds:
        pos, bar = k % meter, k // meter
        if pos == 0 or (meter == 4 and pos == 2):
            add(t, lambda x: 0.6 * math.exp(-x * 25) * math.sin(2 * math.pi * (50 + 80 * math.exp(-x * 40)) * x), 0.3)
        else:
            add(t, lambda x: 0.3 * math.exp(-x * 30) * (rnd.random() * 2 - 1), 0.2)
        for h in (0, 0.5):
            add(t + h * beat, lambda x: 0.08 * math.exp(-x * 80) * (rnd.random() * 2 - 1), 0.05)
        if pos == 0:
            root = [57, 53, 48, 55][bar % 4]
            f = [440 * 2 ** ((root + d - 69) / 12) for d in (0, 3 if root == 57 else 4, 7)]
            fb = 440 * 2 ** ((root - 24 - 69) / 12)
            add(t, lambda x, f=f, fb=fb: 0.05 * sum(math.sin(2 * math.pi * q * x) for q in f)
                + 0.15 * math.sin(2 * math.pi * fb * x), beat * meter)
        k += 1
        t = offset + k * beat
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in buf))


def make_syncopated(path, bpm=130, offset=0.144, seconds=16, rate=44100, chords=True, bass=True):
    """Praxistest 1c: Kick auf 1 und den Offbeats (1&, 2&, 3&, 4&), Bass-Achtel
    betont auf "und", 16tel-Hats mit Akzent auf den Vierteln, Akkordwechsel
    auf der Eins (Am Dm F C) — die staerksten Schlaege liegen zwischen den
    Beats, Tempo und Takt-Eins sind bekannt."""
    import math, random
    rnd = random.Random(3)
    n = int(seconds * rate)
    buf = [0.0] * n
    beat = 60.0 / bpm

    def add(t0, fn, dur):
        s0 = int(t0 * rate)
        for i in range(max(0, -s0), min(int(dur * rate), n - s0)):
            buf[s0 + i] += fn(i / rate)

    kick = lambda x: 0.6 * math.exp(-x * 25) * math.sin(2 * math.pi * (50 + 80 * math.exp(-x * 40)) * x)
    hz = lambda m: 440 * 2 ** ((m - 69) / 12)
    bar, t = 0, offset
    while t < seconds:
        for k in (0, 0.5, 1.5, 2.5, 3.5):
            add(t + k * beat, kick, 0.3)
        for s16 in range(16):
            a = 0.12 if s16 % 4 == 0 else 0.04
            add(t + s16 * beat / 4, lambda x, a=a: a * math.exp(-x * 80) * (rnd.random() * 2 - 1), 0.05)
        root = [57, 50, 53, 48][bar % 4]
        for e in range(8 if bass else 0):
            a = 0.25 if e % 2 else 0.12
            add(t + e * beat / 2, lambda x, f=hz(root - 24), a=a: a * math.exp(-x * 6) * math.sin(2 * math.pi * f * x), beat / 2)
        if chords:
            fs = [hz(root + d) for d in (0, 3 if root in (57, 50) else 4, 7)]
            add(t, lambda x, fs=fs: 0.05 * sum(math.sin(2 * math.pi * q * x) for q in fs), 4 * beat)
        bar += 1
        t = offset + bar * 4 * beat
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in buf))


def make_voice(path, notes, total, rate=44100, harm=6, attack=0.01, release=0.05, detune=0.0, glide=None, vibrato=None, seed=None, decay=None):
    """Synth-Linie mit bekannter Spielweise und bekanntem Klang fuer
    describeVoice/describeTimbre: notes = [(start, dur, midi)]; glide =
    (cents, ms) Einsatz von unten, vibrato = (cents, hz), detune = Cent L
    gegen R (Unison: breit, schwebt), attack/release in Sekunden; decay =
    (Sekunden, Sustain 0..1) faellt nach dem Attack linear auf den Sustain."""
    import math, random
    rnd = random.Random(seed)
    n = int(total * rate)
    L = [0.0] * n
    R = [0.0] * n
    for start, dur, m in notes:
        f0 = 440 * 2 ** ((m - 69) / 12)
        for side, cents in ((0, -detune), (1, detune)):
            ph = rnd.uniform(0, 2 * math.pi) if seed is not None else 0.0   # zufaellige Phase wie ein freilaufender Oszillator
            s0 = int(start * rate)
            for i in range(int(dur * rate)):
                if s0 + i >= n:
                    break
                t = i / rate
                c = cents
                if glide and t < glide[1] / 1000:
                    c += glide[0] * (1 - t / (glide[1] / 1000))
                if vibrato:
                    c += vibrato[0] * math.sin(2 * math.pi * vibrato[1] * t)
                ph += 2 * math.pi * f0 * 2 ** (c / 1200) / rate
                env = min(1.0, t / attack) * min(1.0, (dur - t) / release)
                if decay and t > attack:
                    env *= max(decay[1], 1.0 - (1.0 - decay[1]) * (t - attack) / decay[0])
                y = env * sum(math.sin(k * ph) / k for k in range(1, harm + 1))
                if detune:
                    (L if side == 0 else R)[s0 + i] += y
                    (R if side == 0 else L)[s0 + i] += 0.5 * y
                else:
                    L[s0 + i] += y / 2
                    R[s0 + i] += y / 2
    peak = max(1e-9, max(abs(v) for v in L + R))
    with wave.open(path, "w") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<hh", int(a / peak * 0.7 * 32767), int(b / peak * 0.7 * 32767)) for a, b in zip(L, R)))


def mix_wavs(path, parts):
    """Stereo-WAVs (16 bit, gleiche Rate) zu einem Stem summieren: parts =
    [(pfad, faktor)], Laenge der laengsten Datei."""
    chans = []
    rate = 44100
    for p, g in parts:
        with wave.open(p) as w:
            rate = w.getframerate()
            raw = w.readframes(w.getnframes())
        chans.append(([v * g for v in struct.unpack("<%dh" % (len(raw) // 2), raw)]))
    n = max(len(c) for c in chans)
    out = [sum(c[i] for c in chans if i < len(c)) for i in range(n)]
    with wave.open(path, "w") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v)))) for v in out))


def make_drums(path, bpm=130.0, offset=0.25, bars=6, rate=44100, bass=True, two_bar=False,
               kicks=(0, 6, 8, 10, 14), snares=(4, 12), push=None):
    """Schlagzeug mit bekannter Wahrheit (Praxistest 1d): Kick 1, 2+, 3, 3+, 4+
    (Sweep 175 -> 55 Hz; two_bar: jeder zweite Takt nur 3, 3+, 4+ wie die
    Referenz), Snare 2 und 4 (Koerper 250 Hz + Rauschen), 16tel-Hats mit
    Akzent auf den Vierteln, das "e" 25 ms vorgezogen, offene Hat auf 4+,
    Bass-Achtel 55/73 Hz als Uebersprechen. kicks/snares: andere 16tel;
    push: Versatz der geschlossenen Hats in s je 16tel im Viertel
    ({1: -0.025} = Standard, das "e")."""
    import math, random
    rnd = random.Random(7)
    beat = 60.0 / bpm
    s16 = beat / 4
    n = int((offset + bars * 4 * beat + 1.0) * rate)
    buf = [0.0] * n

    def add(t0, fn, dur):
        s0 = int(round(t0 * rate))
        for i in range(max(0, -s0), min(int(dur * rate), n - s0)):
            buf[s0 + i] += fn(i / rate)

    def kick(x):
        ph = 2 * math.pi * (55 * x + 120 / 40 * (1 - math.exp(-x * 40)))
        return 0.7 * math.exp(-x * 22) * math.sin(ph) + 0.25 * math.exp(-x * 900) * (rnd.random() * 2 - 1)

    def snare(x):
        return 0.35 * math.exp(-x * 28) * math.sin(2 * math.pi * 250 * x) + 0.3 * math.exp(-x * 22) * (rnd.random() * 2 - 1)

    def hat(a, decay):
        st = {"p": 0.0}

        def f(x):
            r = rnd.random() * 2 - 1
            y = r - st["p"]
            st["p"] = r
            return a * math.exp(-x * decay) * y
        return f

    push = {1: -0.025} if push is None else push
    for b in range(bars):
        t0 = offset + b * 4 * beat
        for sl in ((8, 10, 14) if two_bar and b % 2 == 1 else kicks):
            add(t0 + sl * s16, kick, 0.4)
        for sl in snares:
            add(t0 + sl * s16, snare, 0.35)
        for sl in range(16):
            if sl == 14:
                add(t0 + sl * s16, hat(0.10, 9), 0.5)
            else:
                add(t0 + sl * s16 + push.get(sl % 4, 0.0), hat(0.12 if sl % 4 == 0 else 0.05, 70), 0.08)
        if bass:
            for e in range(8):
                f = 55.0 if b % 2 == 0 else 73.4
                add(t0 + e * 2 * s16, lambda x, f=f: 0.25 * min(1, x / 0.01) * math.exp(-x * 4) * math.sin(2 * math.pi * f * x), 2 * s16)
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in buf))


def make_capture_source(path, rate=48000):
    """Mitschnitt mit drei Songs (s24 stereo): 0,5–4,5 s Ton mit 0,4 s
    Pause mittendrin (kuerzer als minGapSec), 6–11 s mit 1 s Pause bei 8–9 s
    (zwei kurze Stuecke, die zusammengehoeren), 12,5–16,5 s mit 1 s
    Fade-out; Stille am Anfang, dazwischen und am Ende (17,5 s)."""
    import math
    parts = [(0.5, 4.5, 440, 0.3), (6.0, 8.0, 220, 0.5), (9.0, 11.0, 220, 0.5), (12.5, 16.5, 660, 0.2)]
    n = int(17.5 * rate)
    out = bytearray(n * 6)
    for a, b, freq, amp in parts:
        for i in range(int(a * rate), int(b * rate)):
            t = i / rate
            if 2.0 <= t < 2.4:
                continue
            g = amp * min(1.0, (b - t) / 1.0) if a == 12.5 else amp
            v = int(g * 8388607 * math.sin(2 * math.pi * freq * t)) & 0xFFFFFF
            out[i * 6:i * 6 + 6] = v.to_bytes(3, "little") * 2
    with wave.open(path, "w") as w:
        w.setnchannels(2)
        w.setsampwidth(3)
        w.setframerate(rate)
        w.writeframes(bytes(out))


@t("capture_songs_flow")
def _():
    # Referenzen aus dem Systemaudio: capture startet den Mitschnitt (in der
    # Suite tests/fake_capture.py statt pw-record, UNIDAW_CAPTURE_CMD), Stop
    # repariert den Kopf eines abgebrochenen Schreibers, detectSongBoundaries
    # findet die drei Songs (Pause im Song bleibt, kurze Stuecke haengen
    # zusammen, Fade-out), saveCaptureSongs schneidet sie nach
    # <config>/references/. Ohne Edit und ohne Baum.
    api("treeClose")
    if os.path.exists(CAPTURE_SRC):
        os.remove(CAPTURE_SRC)

    st = api("captureStatus")
    check(st.get("ok") is True and st.get("capturing") is False, f"status ohne Mitschnitt: {st}")
    check(api("capture", on=False).get("error") == "no capture", "Stop ohne Mitschnitt")

    # Programm endet sofort (keine Quelle) -> Fehler, keine Datei
    r = api("capture", on=True, name="kaputt")
    check(r.get("ok") is False and "ended by itself" in r.get("error", "") and "no source" in r.get("error", ""),
          f"Programm endet sofort: {r}")
    check(api("captureStatus").get("capturing") is False, "nach dem Fehlstart kein Mitschnitt")
    check(api("capture", on=True, rate=1000).get("error") == "rate must be 8000 .. 192000", "rate geprueft")

    make_capture_source(CAPTURE_SRC)
    r = api("capture", on=True, name="Abend")
    check(r.get("ok") is True and r.get("capturing") is True, f"Start: {r}")
    file = r.get("file", "")
    check(file.endswith(os.path.join("config", "captures", "Abend.wav")), f"Datei unter <config>/captures: {file}")
    check(api("capture", on=True).get("error") == "capture in progress", "zweiter Start abgelehnt")
    time.sleep(0.4)
    st = api("captureStatus")
    check(st.get("capturing") is True and st.get("file") == file and st.get("seconds", 0) > 0.2,
          f"Status waehrend des Mitschnitts: {st}")
    check(st.get("levelDb", -100) < -60, f"Pegel am Ende der Quelle (still): {st.get('levelDb')}")
    check(st.get("reconnects") == 0 and st.get("reconnecting") is False, f"kein Neustart: {st}")
    check(file not in [c["file"] for c in st.get("captures", [])], "laufender Mitschnitt nicht in captures")
    check(api("detectSongBoundaries", file=file).get("error") == "capture in progress",
          "Songgrenzen erst nach dem Stop")

    r = api("capture", on=False)
    check(r.get("ok") is True and r.get("capturing") is False and r.get("file") == file, f"Stop: {r}")
    check(abs(r.get("seconds", 0) - 17.5) < 0.01, f"Kopf repariert, Laenge 17,5 s: {r.get('seconds')}")
    with wave.open(file) as w:
        check(w.getnframes() == int(17.5 * 48000), f"data-Groesse im Kopf: {w.getnframes()}")
    check(not os.path.exists(file[:-4] + ".log"), "Log nach erfolgreichem Stop geloescht")
    st = api("captureStatus")
    check([c["name"] for c in st.get("captures", [])] == ["Abend"]
          and abs(st["captures"][0]["seconds"] - 17.5) < 0.01, f"captures: {st.get('captures')}")
    check(api("capture", on=True, name="Abend").get("error") == "capture exists: Abend.wav", "Name belegt")

    b = api("detectSongBoundaries", file=file, minSongSec=3)
    songs = b.get("songs", [])
    check(b.get("ok") is True and len(songs) == 3, f"drei Songs: {b}")
    if len(songs) == 3:
        for s, (a, e) in zip(songs, [(0.5, 4.5), (6.0, 11.0), (12.5, 16.5)]):
            check(abs(s["start"] - a) <= 0.06, f"Start {s['start']} ~ {a}")
            check(e - 0.4 <= s["end"] <= e + 0.06, f"Ende {s['end']} ~ {e}")
            check("short" not in s, f"kein short: {s}")
        check(abs(songs[0]["levelDb"] - 20 * __import__("math").log10(0.3 / 2 ** 0.5)) < 0.5,
              f"Pegel Song 1 (RMS Sinus 0,3): {songs[0]['levelDb']}")
        check([s["index"] for s in songs] == [1, 2, 3], "index ab 1")
    gaps = b.get("gaps", [])
    check(len(gaps) == 2 and abs(gaps[0]["start"] - 4.5) <= 0.06 and abs(gaps[1]["end"] - 12.5) <= 0.06,
          f"Pausen zwischen den Songs: {gaps}")
    check(abs(b.get("duration", 0) - 17.5) < 0.01, "duration")

    # Standard minSongSec 30: alles ein Stueck, als short markiert;
    # minGapSec 1,2 trennt Song 2 nicht mehr in der 1-s-Pause, auch ohne Merge
    one = api("detectSongBoundaries", file=file).get("songs", [])
    check(len(one) == 1 and one[0].get("short") is True and abs(one[0]["start"] - 0.5) <= 0.06,
          f"Standard: ein kurzes Stueck: {one}")
    wide = api("detectSongBoundaries", file=file, minSongSec=0, minGapSec=1.2).get("songs", [])
    check(len(wide) == 3 and all(abs(s["start"] - a) <= 0.06 for s, a in zip(wide, [0.5, 6.0, 12.5])),
          f"minGapSec 1,2 ohne Merge: drei Songs: {wide}")
    split = api("detectSongBoundaries", file=file, minSongSec=0).get("songs", [])
    check(len(split) == 4, f"minSongSec 0: die 1-s-Pause trennt: {split}")
    # joinGapSec 0,9: die Stuecke von Song 2 (1 s Pause) haengen nicht mehr
    # zusammen und kommen einzeln als short (so bleibt ein Systemklang weit
    # weg von jedem Song allein, statt ueber die Stille angehaengt zu werden)
    alone = api("detectSongBoundaries", file=file, minSongSec=3, joinGapSec=0.9).get("songs", [])
    check([round(s["start"], 1) for s in alone] == [0.5, 6.0, 9.0, 12.5]
          and [bool(s.get("short")) for s in alone] == [False, True, True, False], f"joinGapSec 0,9: {alone}")

    for params, err in [({"file": "/nirgends.wav"}, "no such file: /nirgends.wav"),
                        ({"file": "rel.wav"}, "no such file: rel.wav"),
                        ({"file": file, "silenceDb": 0}, "silenceDb must be -120 .. -10"),
                        ({"file": file, "minGapSec": 0}, "minGapSec must be 0.1 .. 30"),
                        ({"file": file, "minSongSec": -1}, "minSongSec must be 0 .. 1800"),
                        ({"file": file, "joinGapSec": -1}, "joinGapSec must be 0 .. 120")]:
        check(api("detectSongBoundaries", **params).get("error") == err, f"Fehlertext {err}")

    # Ablegen: ein Fehler schreibt nichts
    refs = os.path.join(os.path.dirname(os.path.dirname(file)), "references")
    bad = api("saveCaptureSongs", file=file, songs=[{"start": 0.5, "end": 4.5}, {"start": 12.5, "end": 99}])
    check(bad.get("error") == "need 0 <= start < end <= file length (17.5 s)", f"Ende hinter der Datei: {bad}")
    check(not os.path.exists(refs) or not os.listdir(refs), "nach dem Fehler nichts geschrieben")
    check(api("saveCaptureSongs", file=file, songs=[]).get("error") == "need songs: [{start, end, name?}]", "ohne songs")

    pick = [{"start": s["start"], "end": s["end"]} for s in songs]
    if pick:
        pick[1]["name"] = "Zweiter: Song"
    r = api("saveCaptureSongs", file=file, songs=pick)
    saved = r.get("saved", [])
    check(r.get("ok") is True and r.get("dir") == refs and len(saved) == 3, f"drei abgelegt: {r}")
    check([x["name"] for x in saved] == ["Abend 01", "Zweiter Song", "Abend 03"], f"Namen: {[x['name'] for x in saved]}")
    for x, s in zip(saved, songs):
        with wave.open(x["file"]) as w:
            secs = w.getnframes() / w.getframerate()
            check(w.getnchannels() == 2 and w.getsampwidth() == 3 and w.getframerate() == 48000, "WAV s24 stereo 48 kHz")
            check(abs(secs - (s["end"] - s["start"])) < 0.01 and abs(x["seconds"] - secs) < 0.01, f"Laenge {secs}")
    if saved:
        check(wav_peak(saved[0]["file"], 0.1, 1.0) > 0.25, "Song 1 enthaelt den Ton")
    again = api("saveCaptureSongs", file=file, songs=pick[:1])
    check([x["name"] for x in again.get("saved", [])] == ["Abend 01 (2)"], f"vorhandene Datei bleibt, neuer Name: {again}")
    check(len(os.listdir(refs)) == 4, f"vier Dateien in references: {os.listdir(refs)}")
    # als Referenz nutzbar: die Datei-Analysen nehmen sie
    check(bool(saved) and api("detectKey", file=saved[0]["file"]).get("ok") is True, "Datei-Analyse auf der Referenz")

    # Wiederverbinden: das Programm endet mitten im Mitschnitt (wie
    # pw-record beim PipeWire-Neustart), dawd startet es in ein zweites
    # Segment; der Stop haengt beides zu einer Datei zusammen
    open(CAPTURE_SRC + ".crash", "w").close()
    r = api("capture", on=True, name="Neustart")
    check(r.get("ok") is True, f"Start mit Absturz: {r}")
    st = {}
    for _ in range(40):
        time.sleep(0.1)
        st = api("captureStatus")
        if st.get("reconnects", 0) >= 1 and not st.get("reconnecting"):
            break
    check(st.get("capturing") is True and st.get("reconnects") == 1 and st.get("reconnecting") is False,
          f"neu verbunden: {st}")
    # Das neu gestartete Programm braucht unter Last etwas, bis sein Segment
    # geschrieben ist — erst dann stoppen (sonst fehlt das zweite Segment)
    capdir = os.path.dirname(file)
    want = 2 * (os.path.getsize(CAPTURE_SRC) - 100)
    for _ in range(100):
        segs = [os.path.join(capdir, x) for x in os.listdir(capdir) if x != "Abend.wav"]
        if sum(os.path.getsize(x) for x in segs if os.path.isfile(x)) >= want:
            break
        time.sleep(0.05)
    r = api("capture", on=False)
    check(r.get("ok") is True and r.get("reconnects") == 1 and abs(r.get("seconds", 0) - 35.0) < 0.01,
          f"zwei Segmente, 2 x 17,5 s: {r}")
    capdir = os.path.dirname(file)
    check(sorted(os.listdir(capdir)) == ["Abend.wav", "Neustart.wav"], f"keine Segmente/Logs uebrig: {os.listdir(capdir)}")
    six = api("detectSongBoundaries", file=r.get("file", ""), minSongSec=3).get("songs", [])
    check(len(six) == 6 and abs(six[3]["start"] - 18.0) <= 0.06, f"sechs Songs, der vierte bei 18 s: {six}")


@t("detect_tempo_flow")
def _():
    # detectTempo: Tempo, Takt (3/4 vs 4/4), Takt-Eins und Beats aus einer
    # Datei oder dem eigenen Mix (Section, Spur, MIDI durch 4OSC); Bereich
    # in Sekunden der Quelle, detail liefert die Listen; ohne Puls bpm null;
    # Fehlertexte; read-only (Version bleibt).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-detect-tempo-")
    g128 = os.path.join(d, "g128.wav")
    make_groove(g128, 128, 0.37, 16)
    w90 = os.path.join(d, "w90.wav")
    make_groove(w90, 90, 0.2, 16, meter=3)
    pad = os.path.join(d, "pad.wav")
    make_sine(pad, 220, 0.3, seconds=6)

    # Datei ohne Projekt
    r = api("detectTempo", file=g128)
    check(r.get("ok") is True and abs((r.get("bpm") or 0) - 128) < 0.5 and r.get("timeSig") == "4/4"
          and r.get("source") == "file", f"128 BPM 4/4: {r}")
    check(abs((r.get("firstDownbeat") or 0) - 0.37) < 0.03 and r.get("maxDriftMs", 99) < 20 and r.get("confidence", 0) > 0.5,
          f"Takt-Eins 0,37 s, gerades Raster: {r.get('firstDownbeat')} {r.get('maxDriftMs')} {r.get('confidence')}")
    check("beats" not in r and r.get("bars", 0) >= 7, f"kompakt ohne Listen: {sorted(r)}")
    check(r.get("candidates") and abs(r["candidates"][0]["bpm"] - 128) < 1, f"Kandidaten: {r.get('candidates')}")

    r = api("detectTempo", file=w90)
    check(r.get("ok") is True and abs((r.get("bpm") or 0) - 90) < 0.5 and r.get("timeSig") == "3/4"
          and abs((r.get("firstDownbeat") or 0) - 0.2) < 0.03, f"Walzer 90 BPM 3/4: {r}")

    # Bereich: Zeiten in Sekunden der Datei, detail mit allen Beats
    r = api("detectTempo", file=g128, start=4, end=12, detail=True)
    beats, downs = r.get("beats", []), r.get("downbeats", [])
    beat = 60 / 128
    check(r.get("ok") is True and beats and 4 <= beats[0] < 4 + beat + 0.03 and beats[-1] <= 12, f"Beats im Bereich: {beats[:3]} {beats[-1:]}")
    check(downs and all(abs(((x - 0.37) / (4 * beat)) - round((x - 0.37) / (4 * beat))) < 0.05 for x in downs),
          f"Takt-Einsen auf dem Takt-Raster: {downs}")
    check(len(beats) == r.get("beatCount") and len(downs) == r.get("bars"), "Zaehler passen zu den Listen")

    r = api("detectTempo", file=pad)
    check(r.get("ok") is True and r.get("bpm") is None and r.get("hints"), f"ohne Puls: {r}")

    # Fehlertexte
    r = api("detectTempo", file=os.path.join(d, "nope.wav"))
    check(r.get("ok") is False and r.get("error", "").startswith("no such file"), f"Datei fehlt: {r}")
    r = api("detectTempo", file=g128, start=10, end=99)
    check(r.get("ok") is False and "file length" in r.get("error", ""), f"end hinter dem Dateiende: {r}")
    r = api("detectTempo")
    check(r.get("ok") is False and r.get("error") == "no edit", f"Mix ohne Projekt: {r}")

    # Mix: Audio-Clip in einer Section, Spur einzeln
    check(api("treeSeed", dir=d, label="tempo").get("ok") is True, "seed")
    check(api("updateSection", name="Section 1", length=16).get("ok") is True, "Section 16 s")
    check(api("addClip", track=0, file=g128, section="Section 1").get("ok") is True, "Groove als Clip")
    v = api("state").get("version")
    r = api("detectTempo", section="Section 1")
    check(r.get("ok") is True and r.get("source") == "mix" and abs((r.get("bpm") or 0) - 128) < 0.5
          and abs((r.get("firstDownbeat") or 0) - 0.37) < 0.03, f"Mix 128 BPM: {r}")
    check(r.get("version") == v, "read-only: Version bleibt")
    r = api("detectTempo", section="Section 1", track=0)
    check(r.get("ok") is True and r.get("track") == 0 and abs((r.get("bpm") or 0) - 128) < 0.5, f"Spur 0: {r}")

    # MIDI durch 4OSC in einer Section mit 100 BPM: Noten folgen dem Tempo
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("addSection", name="Midi", bars=8, bpm=100).get("ok") is True, "Section 100 BPM, 8 Takte")
    mt = api("createTrack", type="midi", instrument="4OSC")
    check(mt.get("ok") is True, f"MIDI-Spur mit 4OSC: {mt}")
    notes = [{"pitch": 36 if i % 4 == 0 else 60, "start": i * 0.6, "length": 0.15, "velocity": 127 if i % 4 == 0 else 70}
             for i in range(32)]
    check(api("addMidiClip", track=mt["index"], section="Midi", notes=notes).get("ok") is True, "Noten je Beat")
    r = api("detectTempo", section="Midi")
    sec = next((x for x in api("state").get("sections", []) if x["name"] == "Midi"), {})
    check(r.get("ok") is True and abs((r.get("bpm") or 0) - 100) < 1 and r.get("start") == round(sec.get("start", -1), 3),
          f"MIDI 100 BPM, Zeiten in Songsekunden: {r} {sec}")
    api("treeClose")


def make_chords(path, bpm, chords, bars, offset=0.0, drums=True, rate=44100):
    """Akkordfolge (MIDI-Noten je Takt, ein Takt je Akkord, 4/4) mit Bass
    eine Oktave unter dem Grundton, optional Kick auf 1/3 und Snare auf 2/4."""
    import math, random
    rnd = random.Random(2)
    beat = 60 / bpm
    n = int((offset + bars * 4 * beat + 0.5) * rate)
    buf = [0.0] * n

    def add(t0, fn, dur):
        s0 = int(t0 * rate)
        for i in range(max(0, -s0), min(int(dur * rate), n - s0)):
            buf[s0 + i] += fn(i / rate)

    hz = lambda m: 440 * 2 ** ((m - 69) / 12)
    for b in range(bars):
        notes, t = chords[b % len(chords)], offset + b * 4 * beat
        fs, fb = [hz(m) for m in notes], hz(notes[0] - 12)
        add(t, lambda x, fs=fs, fb=fb: math.exp(-x * 0.3) * (0.06 * sum(math.sin(2 * math.pi * q * x) + 0.3 * math.sin(4 * math.pi * q * x) for q in fs)
                                                          + 0.15 * math.sin(2 * math.pi * fb * x)), 4 * beat)
        for k in range(4 if drums else 0):
            if k % 2 == 0:
                add(t + k * beat, lambda x: 0.5 * math.exp(-x * 25) * math.sin(2 * math.pi * (50 + 80 * math.exp(-x * 40)) * x), 0.3)
            else:
                add(t + k * beat, lambda x: 0.25 * math.exp(-x * 30) * (rnd.random() * 2 - 1), 0.2)
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in buf))


def make_pluck_melody(path, transpose=0, bpm=96, rate=44100, melody=None):
    """Einstimmige gezupfte Melodie in a-Moll (mit F, Anfang und Schluss auf
    A), Karplus-Strong-Ton mit vielen Obertoenen; transpose verschiebt sie,
    melody ersetzt sie ([(MIDI-Note oder None, Schlaege)]). Ohne Zufall:
    gleicher Aufruf, gleiche Datei."""
    import random
    rnd = random.Random(96)
    melody = melody or [(69, 1), (72, 1), (76, 1.5), (74, 0.5), (72, 1), (71, 1), (69, 2), (64, 1), (67, 1), (69, 1.5), (71, 0.5),
              (72, 2), (71, 1), (67, 1), (69, 1), (72, 1), (76, 1), (79, 1), (77, 1.5), (76, 0.5), (74, 1), (72, 1),
              (71, 1), (72, 0.5), (71, 0.5), (67, 1), (64, 1), (69, 3), (None, 1)]
    beat = 60 / bpm
    buf = [0.0] * int((sum(b for _, b in melody) * beat + 1) * rate)
    pos = 0.0
    for note, beats in melody:
        if note is not None:
            period = round(rate / (440 * 2 ** ((note + transpose - 69) / 12)))
            ring = [rnd.uniform(-1, 1) for _ in range(period)]
            s0 = int(pos * beat * rate)
            for i in range(min(int((beats * beat + 0.25) * rate), len(buf) - s0)):
                j = i % period
                buf[s0 + i] += ring[j]
                ring[j] = 0.996 * 0.5 * (ring[j] + ring[(j + 1) % period])
        pos += beats
    peak = max(abs(v) for v in buf)
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", int(v / peak * 0.7 * 32767)) for v in buf))


@t("detect_key_flow")
def _():
    # detectKey: Tonart (mit Tonleiter, Alternativen, Paralleltonart-Hinweis)
    # und Akkorde je Beat geglaettet, mit Takt/Schlag ab der Takt-Eins; b-
    # Tonarten mit b geschrieben; ohne Puls 0,5-s-Schritte; Mix aus MIDI
    # durch 4OSC; read-only.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-detect-key-")
    C, F, G, Bb, Eb = [60, 64, 67], [53, 57, 60], [55, 59, 62], [58, 62, 65], [51, 55, 58]
    cmaj = os.path.join(d, "cmaj.wav")
    make_chords(cmaj, 100, [C, F, G, C], 6)
    r = api("detectKey", file=cmaj)
    seq = [(c["chord"], c.get("bar"), c.get("beat")) for c in r.get("chords", []) if c["chord"] != "N"]
    check(r.get("ok") is True and r.get("key") == "C major" and r.get("tonic") == "C" and r.get("mode") == "major"
          and r.get("scale") == ["C", "D", "E", "F", "G", "A", "B"], f"C-Dur: {r.get('key')} {r.get('scale')}")
    check(seq[:5] == [("C", 1, 1), ("F", 2, 1), ("G", 3, 1), ("C", 4, 1), ("F", 6, 1)], f"Akkorde je Takt: {seq}")
    check(r.get("bpm") == 100.0 and r.get("firstDownbeat") == 0.0 and r["summary"][0]["chord"] == "C", f"Raster + Zusammenfassung: {r.get('bpm')} {r.get('firstDownbeat')} {r.get('summary')}")
    check(all(0 <= c["confidence"] <= 1 and c["end"] > c["start"] for c in r["chords"]), "Akkord-Felder")

    bb = os.path.join(d, "bb.wav")
    make_chords(bb, 120, [Bb, Eb, F, Bb], 4, drums=False)
    r = api("detectKey", file=bb)
    names = [c["chord"] for c in r.get("chords", []) if c["chord"] != "N"]
    check(r.get("key") == "Bb major" and "Eb" in r.get("scale", []) and names[:3] == ["Bb", "Eb", "F"], f"B-Dur mit b: {r.get('key')} {names}")

    # Am F C G (Groove): C-Dur und A-Moll teilen die Toene
    g = os.path.join(d, "g.wav")
    make_groove(g, 128, 0.37, 12)
    r = api("detectKey", file=g)
    names = [c["chord"] for c in r.get("chords", []) if c["chord"] != "N"]
    alts = [a["key"] for a in r.get("alternatives", [])]
    check(r.get("key") in ("C major", "A minor") and ({"C major", "A minor"} - {r.get("key")}) <= set(alts)
          and names[:4] == ["Am", "F", "C", "G"], f"Am F C G: {r.get('key')} {alts} {names}")

    # Gezupfte Melodie (Karplus-Strong): der 3. Teilton zog die Tonart eine
    # Quinte nach oben (a-Moll -> e-Moll); auch transponiert. Liegt die
    # Quint-Tonart knapp dahinter, sagt es ein Hinweis
    for tr, want, fifth in ((0, "A minor", "E minor"), (3, "C minor", "G minor"), (-5, "E minor", None)):
        pl = os.path.join(d, f"pluck{tr}.wav")
        make_pluck_melody(pl, tr)
        r = api("detectKey", file=pl, bpm=96, firstDownbeat=0)
        hinted = [h for h in r.get("hints", []) if "is a fifth away" in h]
        check(r.get("ok") is True and r.get("key") == want, f"gezupft {want}: {r.get('key')} {r.get('confidence')} {r.get('alternatives')}")
        check(hinted == ([f"{fifth} is a fifth away and close — its scale differs by one note; check that note and where the melody comes to rest"] if fifth else []),
              f"Quint-Hinweis {want}: {r.get('hints')}")

    pad = os.path.join(d, "pad.wav")
    make_sine(pad, 220, 0.3, seconds=6)
    r = api("detectKey", file=pad)
    check(r.get("ok") is True and r.get("chords") and "bar" not in r["chords"][0]
          and any("no steady pulse" in h for h in r.get("hints", [])), f"ohne Puls: {r}")
    r = api("detectKey")
    check(r.get("ok") is False and r.get("error") == "no edit", f"Mix ohne Projekt: {r}")

    # Mix: Akkorde als MIDI durch 4OSC, Section mit 100 BPM
    check(api("treeSeed", dir=d, label="key").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=100).get("ok") is True, "4 Takte 100 BPM")
    mt = api("createTrack", type="midi", instrument="4OSC")
    notes = [{"pitch": p, "start": b * 2.4, "length": 2.3, "velocity": 90} for b, ch in enumerate([C, F, G, C]) for p in ch + [ch[0] - 12]]
    check(api("addMidiClip", track=mt.get("index"), section="Section 1", notes=notes).get("ok") is True, "Akkorde als MIDI")
    v = api("state").get("version")
    r = api("detectKey", section="Section 1")
    names = [c["chord"] for c in r.get("chords", []) if c["chord"] != "N"]
    check(r.get("ok") is True and r.get("source") == "mix" and r.get("key") == "C major" and names[:3] == ["C", "F", "G"],
          f"Mix C-Dur: {r.get('key')} {names} {r.get('error')}")
    check(r.get("version") == v, "read-only")
    api("treeClose")


def make_song_form(path, pickup=0.0, bpm=120, rate=22050, bridge=False):
    """Song mit bekanntem Aufbau (4/4, 120 BPM): Intro 4 Takte (leise Flaeche
    C Am), Strophe 8 (Am F C G, Kick/Snare), Refrain 8 (F G C Am, lauter,
    Hi-Hats), Strophe, Refrain, Outro 4 wie das Intro; optional ein Auftakt
    aus Snare-Schlaegen. bridge: vor dem Outro eine Bridge (Dm Em F G, so
    laut wie der Refrain, gleiche Tonart) und ein dritter Refrain."""
    import math, random
    rnd = random.Random(3)
    beat = 60 / bpm
    bar = 4 * beat
    C, F, G, Am = [60, 64, 67], [53, 57, 60], [55, 59, 62], [57, 60, 64]
    parts = [(4, [C, Am], 0), (8, [Am, F, C, G], 1), (8, [F, G, C, Am], 2),
             (8, [Am, F, C, G], 1), (8, [F, G, C, Am], 2), (4, [C, Am], 0)]
    if bridge:
        Dm, Em = [50, 53, 57], [52, 55, 59]
        parts[-1:-1] = [(8, [Dm, Em, F, G], 2), (8, [F, G, C, Am], 2)]
    n = int((pickup + sum(p[0] for p in parts) * bar + 1.0) * rate)
    buf = [0.0] * n

    def add(t0, fn, dur):
        s0 = int(t0 * rate)
        for i in range(max(0, -s0), min(int(dur * rate), n - s0)):
            buf[s0 + i] += fn(i / rate)

    hz = lambda m: 440 * 2 ** ((m - 69) / 12)
    for k in range(int(round(pickup / beat))):
        add(k * beat, lambda x: 0.2 * math.exp(-x * 30) * (rnd.random() * 2 - 1), 0.2)
    t = pickup
    for bars, chords, lvl in parts:
        for b in range(bars):
            notes = chords[b % len(chords)]
            fs, fb, amp = [hz(m) for m in notes], hz(notes[0] - 12), [0.5, 0.8, 1.3][lvl]
            add(t, lambda x, fs=fs, fb=fb, amp=amp: amp * math.exp(-x * 0.3) * (0.05 * sum(math.sin(2 * math.pi * q * x) for q in fs)
                                                                         + 0.12 * math.sin(2 * math.pi * fb * x)), bar)
            for k in range(4):
                tt = t + k * beat
                if lvl >= 1 and k % 2 == 0:
                    add(tt, lambda x: 0.5 * math.exp(-x * 25) * math.sin(2 * math.pi * (50 + 80 * math.exp(-x * 40)) * x), 0.3)
                elif lvl >= 1:
                    add(tt, lambda x, a=0.15 * lvl: a * math.exp(-x * 30) * (rnd.random() * 2 - 1), 0.2)
                if lvl == 2:
                    for h in (0, 0.5):
                        add(tt + h * beat, lambda x: 0.07 * math.exp(-x * 80) * (rnd.random() * 2 - 1), 0.05)
            t += bar
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in buf))


@t("analyze_structure_flow")
def _():
    # analyzeStructure: Abschnitte an den Phrasen (Neuheit je Takt), gleiche
    # Teile = gleicher Buchstabe, Rollen-Vermutung, Energie, Akkordfolge je
    # Teil, Auftakt als Takt 0; sectionCommands bauen das Geruest per batch;
    # detail je Takt; ohne Puls 2-s-Bloecke; Mix als Quelle; read-only.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-structure-")
    form = os.path.join(d, "form.wav")
    make_song_form(form, pickup=1.0)
    r = api("analyzeStructure", file=form, detail=True)
    secs = r.get("sections", [])
    check(r.get("ok") is True and r.get("bpm") == 120.0 and r.get("timeSig") == "4/4" and r.get("bars") == 40
          and abs((r.get("firstDownbeat") or 0) - 1.0) < 0.03, f"Raster: {r.get('bpm')} {r.get('bars')} {r.get('firstDownbeat')}")
    check([x["role"] for x in secs] == ["pickup", "intro", "verse", "chorus", "verse", "chorus", "outro"],
          f"Rollen: {[x['role'] for x in secs]}")
    check([x.get("startBar") for x in secs] == [0, 1, 5, 13, 21, 29, 37] and [x.get("bars") for x in secs] == [0, 4, 8, 8, 8, 8, 4],
          f"Takte: {[(x.get('startBar'), x.get('bars')) for x in secs]}")
    if len(secs) == 7:
        lab = [x["label"] for x in secs]
        check(lab[1] == lab[6] and lab[2] == lab[4] and lab[3] == lab[5] and len({lab[1], lab[2], lab[3]}) == 3, f"Buchstaben: {lab}")
        check(secs[3]["energy"] > secs[2]["energy"] > secs[1]["energy"], f"Energie: {[x['energy'] for x in secs]}")
        check(secs[2]["chords"] == "Am F C G Am F C G" and secs[3]["chords"] == "F G C Am F G C Am", f"Akkorde: {secs[2]['chords']} / {secs[3]['chords']}")
    check(len(r.get("barDetail", [])) == 41 and r["barDetail"][0]["bar"] == 0 and {"rmsDb", "low", "mid", "high", "density", "chord"} <= set(r["barDetail"][1]),
          f"detail je Takt: {len(r.get('barDetail', []))}")
    cmds = r.get("sectionCommands", [])
    check([c.get("name") for c in cmds] == ["pickup 1", "intro 1", "verse 1", "chorus 1", "verse 2", "chorus 2", "outro 1"]
          and abs(cmds[0].get("length", 0) - 1.0) < 0.03 and cmds[2] == {"op": "addSection", "name": "verse 1", "bars": 8, "bpm": 120.0, "timeSig": "4/4"},
          f"sectionCommands: {cmds[:3]}")

    pad = os.path.join(d, "pad.wav")
    make_sine(pad, 220, 0.3, seconds=8)
    r = api("analyzeStructure", file=pad)
    check(r.get("ok") is True and r.get("sections") and "startBar" not in r["sections"][0]
          and any("no steady pulse" in h for h in r.get("hints", [])), f"ohne Puls: {r}")
    r = api("analyzeStructure")
    check(r.get("ok") is False and r.get("error") == "no edit", f"Mix ohne Projekt: {r}")

    # Geruest per batch, dann der Song als Clip und der Mix als Quelle
    check(api("treeSeed", dir=d, label="form").get("ok") is True, "seed")
    b = api("batch", commands=cmds[1:])
    names = [x["name"] for x in api("state").get("sections", [])]
    check(b.get("ok") is True and names[1:] == ["intro 1", "verse 1", "chorus 1", "verse 2", "chorus 2", "outro 1"], f"batch: {b.get('failed')} {names}")
    st = {x["name"]: x for x in api("state")["sections"]}
    check(abs(st["verse 1"]["end"] - st["verse 1"]["start"] - 16.0) < 0.01 and st["verse 1"]["bpm"] == 120.0, f"8 Takte = 16 s: {st['verse 1']}")
    plain = os.path.join(d, "plain.wav")
    make_song_form(plain)
    check(api("updateSection", name="Section 1", length=82).get("ok") is True, "Section 1 fuer den Song")
    check(api("addClip", track=0, file=plain, section="Section 1").get("ok") is True, "Song als Clip")
    v = api("state").get("version")
    r = api("analyzeStructure", section="Section 1")
    check(r.get("ok") is True and r.get("source") == "mix"
          and [x["role"] for x in r.get("sections", [])] == ["intro", "verse", "chorus", "verse", "chorus", "outro"],
          f"Mix: {[x['role'] for x in r.get('sections', [])]} {r.get('error')}")
    check(r.get("version") == v, "read-only")
    api("treeClose")


@t("structure_parts_flow")
def _():
    # Praxistests 2/3 (analyzeStructure): verschiedene Teile mit aehnlichem
    # Klang hiessen alle "chorus", Refrain und Bridge verschmolzen; auf einem
    # Stem ohne Warnung ein geschaetztes Tempo; Takt 1 weit vor der ersten
    # erkannten Takt-Eins ohne Erklaerung. Raster vorgeben wie bei den
    # anderen Analyse-Ops.
    d = tempfile.mkdtemp(prefix="dawd-parts-")
    form = os.path.join(d, "bridge.wav")
    make_song_form(form, bridge=True)
    r = api("analyzeStructure", file=form)
    secs = r.get("sections", [])
    check([(x.get("startBar"), x.get("bars")) for x in secs] == [(1, 4), (5, 8), (13, 8), (21, 8), (29, 8), (37, 8), (45, 8), (53, 4)],
          f"Bridge eigener Teil: {[(x.get('startBar'), x.get('bars')) for x in secs]}")
    if len(secs) == 8:
        lab = [x["label"] for x in secs]
        check(lab[2] == lab[4] == lab[6] and lab[5] not in (lab[2], lab[1]) and secs[2]["role"] == "chorus" and secs[5]["role"] == "bridge",
              f"Refrain dreimal gleich, Bridge anders: {lab} {[x['role'] for x in secs]}")
    g = api("analyzeStructure", file=form, bpm=120, firstDownbeat=0)
    check(g.get("gridFrom") == "given" and g.get("bpm") == 120.0 and g.get("bars") == 56 and g.get("firstDownbeat") == 0.0, f"Raster vorgegeben: {g.get('gridFrom')} {g.get('bars')}")
    check(r.get("gridFrom") == "detected", f"sonst geschaetzt: {r.get('gridFrom')}")
    # findRepeats ueber den ganzen Song (Praxistest 2): Fehler statt "unique"
    r = api("findRepeats", file=form, start=0, end=100)
    check(r.get("ok") is False and "no repeat fits beside it" in r.get("error", ""), f"findRepeats ganzer Song: {r}")

    # Nichts kehrt wieder: Hinweis statt "alles chorus"
    C, F, G, Am, Dm, Em, E, D = [60, 64, 67], [53, 57, 60], [55, 59, 62], [57, 60, 64], [50, 53, 57], [52, 55, 59], [52, 56, 59], [50, 54, 57]
    norep = os.path.join(d, "norep.wav")
    make_chords(norep, 120, [Am, F, C, G] * 2 + [Dm, Em, F, G] * 2 + [C, E, Am, D] * 2, 24)
    r = api("analyzeStructure", file=norep)
    lab = [x["label"] for x in r.get("sections", [])]
    check(len(lab) == 3 and len(set(lab)) == 3 and any("no part comes back" in h for h in r.get("hints", [])), f"keine Wiederholung: {lab} {r.get('hints')}")

    # Ohne Drums: Tempo geschaetzt -> Hinweis auf das Raster des Mixes
    comp = os.path.join(d, "comp.wav")
    make_comping(comp, held=True)
    r = api("analyzeStructure", file=comp)
    check(any(h.startswith("tempo, meter and bar count are guessed") for h in r.get("hints", [])), f"Stem ohne Drums: {r.get('hints')}")

    # Drums erst nach 8 s (Flaeche ohne Einsatz davor): Takte davor zurueckgerechnet
    late = os.path.join(d, "late.wav")
    drums = os.path.join(d, "drums.wav")
    make_drums(drums, bars=8)
    rate = 44100
    pad = b"".join(struct.pack("<h", int(0.2 * min(1, i / rate / 3) * 32767 * math.sin(2 * math.pi * 220 * i / rate))) for i in range(8 * rate))
    with wave.open(drums) as w:
        beat = w.readframes(w.getnframes())
    with wave.open(late, "w") as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(rate)
        w.writeframes(pad + beat)
    t = api("detectTempo", file=late)
    r = api("analyzeStructure", file=late)
    check(t.get("firstDownbeat", 0) > 8 and r.get("firstDownbeat", 9) < 2
          and any(h.startswith("bars before " + str(t.get("firstDownbeat"))) for h in r.get("hints", [])),
          f"Takte vor der ersten Eins zurueckgerechnet: {t.get('firstDownbeat')} {r.get('firstDownbeat')} {r.get('hints')}")


@t("glide_steps_flow")
def _():
    # Glide bei Ganztonschritten (Todo analyse-messfehler, Punkt 8): 4OSC
    # legato mit 80 ms gleitet bei jedem Tonschritt; legatoGlideMs zaehlte
    # nur die Strecke 80 ct von beiden Noten — beim Ganzton (80-120 ct)
    # nie 50 ct, F4-G4 und D4-E4 galten nicht als Glide (glideShare 0,71).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-glide-steps-")
    check(api("treeSeed", dir=d, label="glide").get("ok") is True, "seed")
    api("treeSettings", autoBranch=False)
    api("updateSection", name="Section 1", length=6)
    t = api("createTrack", type="midi", instrument="4OSC")
    check(api("setParameter", plugin=t["id"], settings={"Wave 1": "sawUp", "Voice Mode": "legato"}).get("ok") is True, "4OSC legato")
    for ms, want in ((80, 1.0), (0, 0.0)):
        api("setParameter", plugin=t["id"], reals={"Legato": ms})
        for line in ([64, 65, 67, 64, 67, 62, 64, 67], [60, 62, 64, 66, 64, 62, 60, 62]):
            r = api("addMidiClip", track=t["index"], section="Section 1",
                    notes=[{"pitch": m, "beat": i, "beats": 1.05, "velocity": 100} for i, m in enumerate(line)])
            v = api("describeVoice", track=t["index"], section="Section 1")
            if v.get("ok") is False and "tools/fetch_ml.sh" in v.get("error", ""):
                print("    skip describeVoice (no ONNX Runtime/model)")
                api("treeClose")
                return
            vo = v.get("voice", {})
            check(vo.get("legatoChanges") == 7 and abs((vo.get("glideShare") or 0) - want) < 0.05
                  and (want == 0 or 65 <= (vo.get("glideMs") or 0) <= 95), f"Glide {ms} ms, Linie {line}: {vo.get('glideShare')} {vo.get('glideMs')}")
            api("deleteClip", track=t["index"], name=r.get("name", "Notes"))
    api("treeClose")


@t("chords_overtone_flow")
def _():
    # audioToMidi shape chords (Todo analyse-messfehler, Punkt 7): ohne
    # Raster eine klare Meldung statt "no notes found"; ein spaeter
    # Oberton im Ausklang (basic-pitch: E5 ueber C3 ab 0,95 s) ist kein
    # zweiter Anschlag und keine Akkord-Tonklasse; eine gespielte Oktave
    # bleibt mit keepOctaves zwei Toene. Eine gespielte Duodezime (G4 ueber
    # C3) ist ein Akkordton, kein Oberton (Todo 2026-10-30-chords-echte-
    # quinte: C3 C4 E4 G4 wurde C E); C3 allein bekommt kein G.
    d = tempfile.mkdtemp(prefix="dawd-chords-ot-")
    held, octave = os.path.join(d, "held.wav"), os.path.join(d, "octave.wav")
    make_voice(held, [(0.0, 2.0, 48), (2.0, 2.0, 53)], 4.5)
    make_voice(octave, [(0.0, 2.0, 48), (0.0, 2.0, 60), (2.0, 2.0, 53), (2.0, 2.0, 65)], 4.5)
    r = api("audioToMidi", file=held, shape="chords")
    if r.get("ok") is False and "tools/fetch_ml.sh" in r.get("error", ""):
        print("    skip audioToMidi (no ONNX Runtime/model)")
        return
    check(r.get("ok") is False and r.get("error", "").startswith("no bar grid on this source"), f"ohne Raster: {r}")
    g = {"bpm": 120, "firstDownbeat": 0}
    r = api("audioToMidi", file=held, shape="chords", keepOctaves=True, **g)
    hits = sorted({round(n["start"], 1) for n in r.get("notes", [])})
    pcs = {n["pitch"] % 12 for n in r.get("notes", []) if n["start"] < 1.5}
    check(r.get("ok") is True and hits == [0.0, 2.0] and pcs == {0} and not any(n["pitch"] % 12 == 7 for n in r.get("notes", [])),
          f"gehaltener Ton: zwei Anschlaege, kein Oberton: {r.get('notes')}")
    r = api("audioToMidi", file=octave, shape="chords", keepOctaves=True, **g)
    first = sorted(n["pitch"] for n in r.get("notes", []) if n["start"] < 0.1)
    check(first == [48, 60], f"Oktave C3+C4 mit keepOctaves: {r.get('notes')}")
    chord = os.path.join(d, "chord.wav")
    make_voice(chord, [(0.0, 2.0, m) for m in (48, 60, 64, 67)] + [(2.0, 2.0, m) for m in (53, 65, 69, 72)], 4.5)
    r = api("audioToMidi", file=chord, shape="chords", keepOctaves=True, **g)
    at = lambda t: sorted(n["pitch"] for n in r.get("notes", []) if abs(n["start"] - t) < 0.1)
    check(at(0.0) == [48, 60, 64, 67] and at(2.0) == [53, 65, 69, 72], f"C3 C4 E4 G4 / F3 F4 A4 C5 mit keepOctaves: {r.get('notes')}")
    r = api("audioToMidi", file=chord, shape="chords", **g)
    pcs = {n["pitch"] % 12 for n in r.get("notes", []) if n["start"] < 0.1}
    check(pcs == {0, 4, 7}, f"C3 C4 E4 G4: Tonklassen C E G: {r.get('notes')}")


def make_tone(path, freq=440.0, seconds=0.5, rate=44100, amp=0.5):
    """Kurzer Ton mit Ausklang (Sample fuer den Sampler)."""
    import math
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", int(amp * 32767 * math.exp(-i / rate * 6) * math.sin(2 * math.pi * freq * i / rate)))
                               for i in range(int(seconds * rate))))


@t("kit_relink_flow")
def _():
    # Eingebautes Drum Kit nach einem Umzug von unidaw (Todo
    # 2026-11-23-eingebautes-kit-mit-absolutem-pfad): das Edit traegt den
    # absoluten Pfad zum Kit der Binary, die den Song gebaut hat. Steht dort
    # nichts mehr (Worktree weg, AppImage unter neuem /tmp/.mount_…), biegt
    # unidaw die Pfade beim Laden auf das Kit der laufenden Binary um —
    # offener Node (treeOpen) und ein anderer Node im renderBatch.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-kit-relink-")
    check(api("treeSeed", dir=d, label="kit").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=2, bpm=120).get("ok") is True, "2 Takte")
    kit = api("createTrack", type="midi", instrument="Drum Kit")
    check(kit.get("ok") is True, f"createTrack Drum Kit: {kit}")
    files = [x["file"] for x in api("listSamples", plugin=kit.get("id")).get("samples", [])]
    kits = os.path.dirname(os.path.dirname(files[0])) if files else ""
    check(len(files) == 20 and os.path.basename(kits) == "kits", f"Kit-Dateien unter .../kits: {files[:1]}")
    notes = [{"pitch": 36 if i % 2 == 0 else 38, "start": i * 0.5, "length": 0.1, "velocity": 110} for i in range(8)]
    check(api("addMidiClip", track=kit["index"], section="Section 1", notes=notes).get("ok") is True, "Beat")
    before = os.path.join(d, "before.wav")
    check(api("render", file=before, section="Section 1").get("ok") is True, "Render vorher")
    br = api("treeBranch", label="other")
    check(br.get("ok") is True, f"Zweig: {br}")
    check(api("treeClose").get("ok") is True, "treeClose")

    # Kit-Pfade in allen Node-Edits auf einen Ordner biegen, den es nicht gibt
    gone = os.path.join(tempfile.gettempdir(), "dawd-kit-gone-%d" % os.getpid(), "Release", "kits")
    check(not os.path.exists(gone), "alter Kit-Ordner fehlt")
    moved = []
    for f in sorted(os.listdir(d)):
        if not f.endswith(".tracktionedit"):
            continue
        p = os.path.join(d, f)
        with open(p) as fh:
            text = fh.read()
        if kits + "/" in text:
            moved.append(f)
            with open(p, "w") as fh:
                fh.write(text.replace(kits + "/", gone + "/"))
    check("node-1.tracktionedit" in moved and "node-2.tracktionedit" in moved, f"alte Pfade in {moved}")

    r = api("treeOpen", dir=d)
    check(r.get("ok") is True, f"treeOpen: {r}")
    now = [x["file"] for x in api("listSamples", plugin=kit.get("id")).get("samples", [])]
    check(now == files, f"Kit der laufenden Binary: {now[:1]}")
    check("missingFiles" not in api("state"), "state ohne missingFiles")
    after = os.path.join(d, "after.wav")
    check(api("render", file=after, section="Section 1").get("ok") is True, "Render nach treeOpen")
    p0, p1 = wav_peak(before, 0, 4), wav_peak(after, 0, 4)
    check(p0 > 0.1 and abs(p1 - p0) < 0.01, f"Drums klingen wie vorher: {p0:.3f} / {p1:.3f}")

    # anderer Node: zum Rendern geladen, nicht offen
    out = os.path.join(d, "batch")
    r = api("renderBatch", dir=out, nodes=[1], sections=["Section 1"], song=False, formats=["wav"])
    rs = r.get("renders", [])
    check(r.get("ok") is True and len(rs) == 1 and abs(wav_peak(rs[0]["file"], 0, 4) - p0) < 0.01,
          f"Node 1 im renderBatch mit Drums: {r.get('error') or r.get('failed')}")
    api("treeClose")


@t("sampler_flow")
def _():
    # Drum Kit (Built-in: Sampler mit dem mitgelieferten Kit in GM-Belegung),
    # setSamples/listSamples (One-Shot auf einer Taste, melodisch mit
    # Bereich, Ausschnitt, ersetzen/anhaengen), Samples von ausserhalb ins
    # Projekt kopiert, komprimierte dekodiert, Fehlertexte ohne Aenderung,
    # process-Aktion (eine je Modul), Undo.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-sampler-")
    outside = tempfile.mkdtemp(prefix="dawd-samples-src-")
    check(any(p["name"] == "Drum Kit" and p["format"] == "builtin" and p["class"] == "instrument"
              for p in api("listPlugins").get("plugins", [])), "Drum Kit in listPlugins")
    check(api("treeSeed", dir=d, label="sampler").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=2, bpm=120).get("ok") is True, "2 Takte")
    kit = api("createTrack", type="midi", instrument="Drum Kit")
    check(kit.get("ok") is True and kit.get("instrument") == "Drum Kit", f"createTrack Drum Kit: {kit}")
    ls = api("listSamples", plugin=kit.get("id"))
    by = {x["low"]: x for x in ls.get("samples", [])}
    check(len(by) == 20 and by[36]["name"] == "kick" and by[38]["name"] == "snare" and by[42]["name"] == "hihat closed"
          and all(x["oneShot"] and x["low"] == x["high"] == x["root"] for x in by.values()), f"Kit in GM-Belegung: {sorted(by)}")
    notes = [{"pitch": 36 if i % 2 == 0 else 38, "start": i * 0.5, "length": 0.1, "velocity": 110} for i in range(8)]
    check(api("addMidiClip", track=kit["index"], section="Section 1", notes=notes).get("ok") is True, "Beat")
    out = os.path.join(d, "kit.wav")
    check(api("render", file=out).get("ok") is True and wav_peak(out, 0, 4) > 0.1, "Drum Kit klingt im Render")

    # Eigener Sampler: Ton von ausserhalb des Projekts
    tone = os.path.join(outside, "tone.wav")
    make_tone(tone)
    sp = api("addPlugin", name="Sampler")
    sid = sp.get("id")
    r = api("setSamples", plugin=sid, samples=[{"file": tone, "note": 60, "gainDb": -3},
                                               {"file": tone, "root": 60, "low": 48, "high": 59, "name": "keys", "start": 0.1, "length": 0.2}])
    s = r.get("samples", [])
    check(r.get("ok") is True and len(s) == 2 and s[0]["oneShot"] is True and s[0]["gainDb"] == -3
          and s[1]["oneShot"] is False and (s[1]["low"], s[1]["high"], s[1]["root"]) == (48, 59, 60) and s[1]["name"] == "keys"
          and abs(s[1]["start"] - 0.1) < 1e-6 and abs(s[1]["length"] - 0.2) < 1e-6, f"setSamples: {s}")
    check(all(x["file"].startswith(os.path.join(d, "media", "samples")) for x in s), f"ins Projekt kopiert: {[x['file'] for x in s]}")
    os.remove(tone)   # das Projekt braucht die Quelle nicht mehr
    check(api("listSamples", plugin=sid).get("samples") == s, "listSamples wie die Antwort")
    r = api("setSamples", plugin=sid, append=True, samples=[{"file": by[42]["file"], "note": 62}])
    check(r.get("ok") is True and len(r["samples"]) == 3 and r["samples"][2]["file"] == by[42]["file"], f"append, Kit-Datei bleibt im Repo: {r.get('samples', [])[-1:]}")
    if shutil.which("ffmpeg"):
        ogg = os.path.join(outside, "tone.ogg")
        make_tone(os.path.join(outside, "t2.wav"))
        subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", os.path.join(outside, "t2.wav"), ogg], check=True)
        r = api("setSamples", plugin=sid, append=True, samples=[{"file": ogg, "note": 64}])
        check(r.get("ok") is True and r["samples"][-1]["file"].endswith(".ogg.wav"), f"ogg dekodiert: {r.get('samples', [])[-1:]} {r.get('error')}")

    # Fehlertexte, der Sampler bleibt unveraendert
    before = api("listSamples", plugin=sid).get("samples")
    good = {"file": by[36]["file"], "note": 36}
    for args, err in [({"plugin": sid, "samples": [good, {"file": "/nope.wav", "note": 1}]}, "sample 1: no such file: /nope.wav"),
                      ({"plugin": sid, "samples": [{"file": by[36]["file"], "note": 200}]}, "sample 0: note must be 0..127"),
                      ({"plugin": sid, "samples": [{"file": by[36]["file"], "low": 70, "high": 60}]}, "sample 0: low must not be above high"),
                      ({"plugin": sid, "samples": "x"}, "samples must be a list of {file, note | low/high/root, ...}"),
                      ({"plugin": sid, "update": [{"index": 9, "gainDb": 1}]}, "update 0: no such sample (give index from listSamples or its name)"),
                      ({"plugin": sid, "update": [{"index": 0, "gain": 1}]}, "update 0: unknown field gain (use: index, name, gainDb, pan, note, root, low, high, velLow, velHigh, roundRobin, choke, attack, release, oneShot, start, length, rename)"),
                      ({"plugin": sid, "update": [{"index": 0, "gainDb": 99}]}, "update 0: gainDb must be -48..48"),
                      ({"plugin": sid, "samples": [good] * 65}, "too many samples (a sampler holds at most 64)"),
                      ({"plugin": "p99", "samples": []}, "no such plugin: p99")]:
        r = api("setSamples", **args)
        check(r.get("ok") is False and r.get("error") == err, f"setSamples {err}: {r}")
    osc = api("addPlugin", name="4OSC").get("id")
    r = api("setSamples", plugin=osc, samples=[])
    check(r.get("ok") is False and r.get("error", "").startswith("not a sampler: "), f"4OSC ist kein Sampler: {r}")
    check(api("listSamples", plugin=sid).get("samples") == before, "nach Fehlern unveraendert")

    # Node-Aktion: process, mehrere setSamples am selben Modul = eine
    acts = [a for a in api("treeState")["nodes"][0]["actions"] if a["op"] == "setSamples"]
    check(len(acts) == 1 and acts[0]["kind"] == "process" and acts[0]["params"]["plugin"] == sid, f"eine process-Aktion: {acts}")
    # Undo: die letzte Belegung zurueck
    n = len(before)
    check(api("setSamples", plugin=sid, samples=[good]).get("ok") is True, "ersetzen")
    u = api("undo")
    check(u.get("ok") is True and len(api("listSamples", plugin=sid).get("samples", [])) == n, f"undo: {u.get('undone')}")

    # Praxistest 1b: einzelne Samples aendern (Gain, Bereich, Name), der Rest
    # bleibt; weit verstimmte Samples melden eine Warnung
    r = api("setSamples", plugin=sid, update=[{"index": 0, "gainDb": -9}, {"name": "keys", "low": 55, "rename": "keys2"}])
    s = r.get("samples", [])
    check(r.get("ok") is True and len(s) == n and s[0]["gainDb"] == -9 and s[1]["low"] == 55 and s[1]["name"] == "keys2"
          and s[1]["high"] == 59, f"update einzelner Samples: {s}")
    r = api("setSamples", plugin=sid, append=True, samples=[{"file": by[42]["file"], "root": 67}])
    check(r.get("ok") is True and any("24 semitones" in w for w in r.get("warnings", [])), f"Warnung bei weiter Verstimmung: {r.get('warnings')}")
    api("treeClose")


@t("sample_library_flow")
def _():
    # sampleLibraries/findSamples: die Kits sind immer da, Ordner anmelden
    # (Index im Hintergrund, bleibt in <config>), Suche ueber Ordner- und
    # Dateinamen, blaettern mit dir, Vorhoer-/versteckte Ordner und
    # unlesbare Dateien fallen weg, Symlink-Schleifen haengen nicht.
    lib = tempfile.mkdtemp(prefix="dawd-library-")
    for rel in ("Drums/Kick/Kick Hard.wav", "Drums/Kick/Kick Soft.wav", "Drums/Snare/Snare Tight.wav",
                "Loops/Beat 90 bpm.wav", ".previews/Kick Preview.wav", "Previews/Kick Preset.wav"):
        os.makedirs(os.path.dirname(os.path.join(lib, rel)), exist_ok=True)
        make_tone(os.path.join(lib, rel), seconds=0.3)
    with open(os.path.join(lib, "Drums", "Kick", "Kick Broken.wav"), "wb") as f:
        f.write(b"not audio at all")
    with open(os.path.join(lib, "Drums", "Kick", "Kick Live.aif"), "wb") as f:   # Abletons "able"-Codec
        f.write(b"FORM\x00\x00\x10\x00AIFCFVER\x00\x00\x00\x04\xa2\x80Q@able\x00\x00\x01T" + b"\x00" * 64)
    os.symlink(lib, os.path.join(lib, "Drums", "loop"))   # Windows-Junction-artig

    libs = api("sampleLibraries").get("libraries", [])
    check(libs and libs[0]["builtin"] is True and libs[0]["files"] == 20, f"Kits eingebaut: {libs}")
    r = api("findSamples", query="kick")
    check(r.get("ok") is True and [x["name"] for x in r["samples"]][:2] == ["036 kick", "035 kick deep"], f"Kits durchsuchbar: {r}")

    check(api("sampleLibraries", add=lib).get("ok") is True, "anmelden")
    for _ in range(100):
        cur = [x for x in api("sampleLibraries")["libraries"] if x["dir"] == lib]
        if cur and not cur[0]["indexing"]:
            break
        time.sleep(0.1)
    # Kick Hard/Soft, Snare Tight, Beat 90 bpm und die kaputte WAV (faellt erst
    # bei der Suche weg); ohne Vorhoerer, able-AIFF und die Schleife
    check(cur and cur[0]["files"] == 5, f"5 Dateien im Index: {cur}")
    r = api("findSamples", query="kick", limit=10)
    names = [x["name"] for x in r.get("samples", [])]
    check("Kick Hard" in names and "Kick Soft" in names and "Kick Broken" not in names and "Kick Preview" not in names
          and "Kick Preset" not in names and "Kick Live" not in names, f"Treffer: {names}")
    hard = next((x for x in r["samples"] if x["name"] == "Kick Hard"), {})
    check(hard.get("folder") == "Drums/Kick" and hard.get("library") == lib and abs(hard.get("duration", 0) - 0.3) < 0.01
          and hard.get("channels") == 1, f"Felder: {hard}")
    r = api("findSamples", query="drums tight")
    check([x["name"] for x in r.get("samples", [])] == ["Snare Tight"], f"Ordnerworte zaehlen: {r.get('samples')}")
    r = api("findSamples", dir=os.path.join(lib, "Loops"))
    check(r.get("total") == 1 and r["samples"][0]["name"] == "Beat 90 bpm", f"blaettern: {r}")
    check(len(api("findSamples", query="kick", limit=1).get("samples", [])) == 1, "limit")

    # Schon angemeldet: ok mit note, nichts doppelt (Praxistest remix-1)
    for again in (lib, os.path.join(lib, "Drums")):
        r = api("sampleLibraries", add=again)
        check(r.get("ok") is True and r.get("note") == "already in the library: " + lib
              and sum(1 for x in r.get("libraries", []) if x["dir"] == lib) == 1, f"add {again} noch einmal: {r}")
    for args, err in [({"add": "/nope/dir"}, "no such dir: /nope/dir"),
                      ({"remove": libs[0]["dir"]}, "the built-in kits cannot be removed")]:
        r = api("sampleLibraries", **args)
        check(r.get("ok") is False and r.get("error") == err, f"sampleLibraries {args}: {r}")
    r = api("findSamples")
    check(r.get("ok") is False and r.get("error", "").startswith("need a query"), f"ohne Anfrage: {r}")
    check(api("sampleLibraries", remove=lib).get("ok") is True and not api("findSamples", query="tight").get("samples"), "abmelden")


def write_mono(path, samples, rate=44100):
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in samples))


def wait_analysis(timeout=300):
    a = {}
    for _ in range(timeout * 10):
        a = api("sampleLibraries").get("analysis", {})
        if not a.get("running"):
            return a
        time.sleep(0.1)
    return a


@t("sound_search_flow")
def _():
    # Suche nach Klang: sampleLibraries {analyze} baut im Hintergrund CLAP-
    # Vektoren und Merkmale; findSamples {text | like} ordnet nach
    # Aehnlichkeit, category/oneShot/Dauer filtern, sort ordnet nach einem
    # Merkmal. Erzeugte Signale mit bekannten Eigenschaften (Vibrato, Punch,
    # Loop mit 120 BPM, zwei gleiche Dateien) und die mitgelieferten Kits.
    import math
    import random
    api("treeClose")
    r = api("findSamples", text="kick drum")
    if r.get("ok") is False and "tools/fetch_ml.sh" in r.get("error", ""):
        print("    skip sound search (" + r["error"] + ")")
        return
    rate = 44100
    lib = tempfile.mkdtemp(prefix="dawd-sounds-")
    for d in ("Tones", "Hits", "Copies", "Loops"):
        os.makedirs(os.path.join(lib, d))
    n = int(2.0 * rate)
    write_mono(os.path.join(lib, "Tones", "steady.wav"), [0.5 * math.sin(2 * math.pi * 440 * i / rate) for i in range(n)])
    phase, vib = 0.0, []
    for i in range(n):   # 6 Hz, +-50 Cent
        phase += 2 * math.pi * 440 * 2 ** (50 * math.sin(2 * math.pi * 6 * i / rate) / 1200) / rate
        vib.append(0.5 * math.sin(phase))
    write_mono(os.path.join(lib, "Tones", "vibrato.wav"), vib)
    rnd = random.Random(1)
    write_mono(os.path.join(lib, "Hits", "hit punchy.wav"),
               [math.exp(-i / rate * 60) * (0.6 * math.sin(2 * math.pi * 60 * i / rate) + 0.3 * rnd.uniform(-1, 1)) for i in range(int(0.8 * rate))])
    write_mono(os.path.join(lib, "Hits", "hit boomy.wav"),
               [min(1.0, i / (0.01 * rate)) * math.exp(-i / rate * 2) * 0.8 * math.sin(2 * math.pi * 60 * i / rate) for i in range(int(1.5 * rate))])
    loop = [0.0] * int(8 * rate)
    for b in range(16):   # 120 BPM: Klick alle 0,5 s
        for i in range(int(0.03 * rate)):
            loop[int(b * 0.5 * rate) + i] = 0.8 * math.exp(-i / rate * 200) * rnd.uniform(-1, 1)
    write_mono(os.path.join(lib, "Loops", "clicks.wav"), loop)
    kits = api("sampleLibraries")["libraries"][0]["dir"]
    for name in ("a.wav", "b.wav"):
        shutil.copy(os.path.join(kits, "basic", "038 snare.wav"), os.path.join(lib, "Copies", name))
    with open(os.path.join(lib, "Hits", "broken.wav"), "wb") as f:
        f.write(b"RIFF\x10\x00\x00\x00WAVEfmt nonsense")

    check(api("sampleLibraries", add=lib).get("ok") is True, "anmelden")
    for _ in range(100):
        cur = [x for x in api("sampleLibraries")["libraries"] if x["dir"] == lib]
        if cur and not cur[0]["indexing"]:
            break
        time.sleep(0.1)
    r = api("sampleLibraries", analyze=True)
    check(r.get("ok") is True and r["analysis"]["total"] >= 28, f"Analyse startet: {r.get('analysis')}")
    a = wait_analysis()
    libs = {x["dir"]: x for x in api("sampleLibraries")["libraries"]}
    check(not a.get("running") and a.get("failed") == 1 and libs[lib]["analyzed"] == 7 and libs[kits]["analyzed"] == 20,
          f"analysiert (broken.wav faellt weg): {a}, {libs}")

    r = api("findSamples", dir=lib, sort="duration", order="asc", limit=20)
    by = {x["name"]: x for x in r.get("samples", [])}
    check(r.get("ok") is True and len(by) == 7 and r.get("analyzed") == 7, f"alle mit Merkmalen: {r}")
    vf, sf = by["vibrato"]["features"], by["steady"]["features"]
    check(35 <= vf.get("vibratoCents", 0) <= 70 and 5 <= vf.get("vibratoHz", 0) <= 7 and "vibratoCents" not in sf,
          f"Vibrato gemessen: {vf} / {sf}")
    check(abs(sf.get("pitchHz", 0) - 440) < 3 and sf.get("note") == "A4", f"Tonhoehe: {sf}")
    pf, bf = by["hit punchy"]["features"], by["hit boomy"]["features"]
    check(pf["punchDb"] > bf["punchDb"] + 6 and pf["oneShot"] and bf["oneShot"] and pf["low"] > 0.3, f"Punch: {pf} / {bf}")
    lf = by["clicks"]["features"]
    check(lf["oneShot"] is False and abs(lf.get("bpm", 0) - 120) < 2, f"Loop mit Tempo: {lf}")

    r = api("findSamples", dir=lib, sort="punch")
    names = [x["name"] for x in r["samples"]]
    check(names.index("hit punchy") < names.index("hit boomy") and r.get("sortedBy") == "punch desc", f"sort punch: {names}")
    r = api("findSamples", dir=lib, sort="punch", order="asc")
    names = [x["name"] for x in r["samples"]]
    check(names.index("hit boomy") < names.index("hit punchy") and r.get("sortedBy") == "punch asc", f"order asc: {names}")
    r = api("findSamples", text="a tone with vibrato", dir=lib)
    check(r.get("onlyWithVibrato") is True and [x["name"] for x in r.get("samples", [])] == ["vibrato"],
          f"vibrato im Text filtert: {r}")
    r = api("findSamples", dir=lib, oneShot=False)
    check([x["name"] for x in r["samples"]] == ["clicks"], f"oneShot false: {r.get('samples')}")
    r = api("findSamples", dir=lib, maxDuration=1.0)
    names = [x["name"] for x in r["samples"]]
    check("hit punchy" in names and "hit boomy" not in names and all(x["duration"] <= 1.0 for x in r["samples"]),
          f"maxDuration: {r.get('samples')}")

    # Text: Kits ohne Kategorie-Filter, dann mit erkannter Kategorie
    r = api("findSamples", text="kick drum", dir=kits, category="any", limit=3)
    check(r.get("ok") is True and r["samples"][0]["name"] in ("036 kick", "035 kick deep") and "category" not in r,
          f"Text kick drum: {r}")
    r = api("findSamples", text="a cowbell", dir=kits, category="any", limit=1)
    check(r["samples"][0]["name"] == "056 cowbell" and r["samples"][0]["similarity"] > 0.3, f"Text cowbell: {r}")
    r = api("findSamples", text="bright hi-hat", dir=kits)
    check(r.get("category") == "hihat" and r.get("categoryFromText") is True and r["samples"]
          and all(x["category"] == "hihat" for x in r["samples"]), f"Kategorie aus dem Text: {r}")
    r = api("findSamples", text="Bassdrum mit viel Punch", dir=kits)
    check(r.get("text", "").startswith("kick drum") and r.get("category") == "kick" and r.get("sortedBy") == "punch desc"
          and r.get("sortFromText") is True and [x["category"] for x in r["samples"]] == ["kick", "kick"],
          f"deutsch, Kategorie und Sortierung aus dem Text: {r}")
    r = api("findSamples", text="dunkler Drone mit viel Raum, teure Hallige", dir=kits, category="any")
    check(r.get("text") == "dark drone with lots of room expensive reverberant", f"ausgefallenes e, Raum: {r.get('text')}")

    # Referenz: die gleiche Datei unter anderem Namen zuerst, sich selbst nicht
    a_file = os.path.join(lib, "Copies", "a.wav")
    r = api("findSamples", like={"file": a_file}, category="any", limit=3)
    s = r.get("samples", [])
    check(r.get("ok") is True and s and s[0]["name"] == "b" and s[0]["similarity"] > 0.99 and all(x["name"] != "a" for x in s)
          and r.get("reference", {}).get("features", {}).get("oneShot") is True, f"like file: {r}")
    r = api("findSamples", like=a_file, category="any", limit=3)
    check(r.get("ok") is True and [x["name"] for x in r.get("samples", [])] == [x["name"] for x in s], f"like als Pfad wie {{file}}: {r}")
    r = api("findSamples", like={"file": os.path.join(lib, "Loops", "clicks.wav"), "start": 0, "end": 2}, dir=lib, limit=1)
    check(r.get("ok") is True and r["samples"][0]["name"] == "clicks", f"like Ausschnitt findet die Datei selbst: {r}")

    for args, err in [({"text": "x", "category": "foo"}, "unknown category: foo ("),
                      ({"sort": "foo"}, "unknown sort: foo ("),
                      ({"sort": "punch", "order": "up"}, "order is asc or desc"),
                      ({"text": "x", "like": {"file": a_file}}, "text or like, not both"),
                      ({"like": {"file": "/nope.wav"}}, "no such file: /nope.wav"),
                      ({"like": {"file": a_file, "start": 5}}, "need 0 <= start < end <= file length"),
                      ({"like": "/nope.wav"}, "no such file: /nope.wav"),
                      ({"like": 5}, "like needs a file path, {file, start?, end?}"),
                      ({"like": {"start": 0, "end": 1}}, "no edit")]:
        r = api("findSamples", **args)
        check(r.get("ok") is False and r.get("error", "").startswith(err), f"findSamples {args}: {r}")
    r = api("sampleLibraries", analyze="/nope/dir")
    check(r.get("ok") is False and r.get("error") == "no such dir: /nope/dir", f"analyze dir: {r}")

    # Erneut: nichts Neues, alles unveraendert; abmelden vergisst die Analyse
    api("sampleLibraries", analyze=lib)
    a = wait_analysis()
    check(a.get("unchanged") == 8 and a.get("total") == 8, f"inkrementell: {a}")
    api("sampleLibraries", remove=lib)
    api("sampleLibraries", add=lib)
    cur = [x for x in api("sampleLibraries")["libraries"] if x["dir"] == lib]
    check(cur and cur[0]["analyzed"] == 0, f"abgemeldet = vergessen: {cur}")
    api("sampleLibraries", remove=lib)


@t("sound_license_block_flow")
def _():
    # Klang-Analyse je Ordner sperren (Lizenz verbietet Data Mining / KI-
    # Nutzung; Decision 2026-11-18-klang-analyse-je-hersteller):
    # sampleLibraries {noAnalysis} loescht die Klang-Daten darunter, die
    # Analyse und like ueberspringen den Ordner, die Namenssuche bleibt; die
    # Sperre steht in libraries.json und gilt nach dem Neustart, auch von
    # Hand eingetragen. Eigene Instanz (eigener --config).
    port = PORT + 1
    run_dir = tempfile.mkdtemp(prefix="dawd-noanalysis-run-")
    config = os.path.join(run_dir, "config")
    lib = tempfile.mkdtemp(prefix="dawd-noanalysis-lib-")
    free, blocked = os.path.join(lib, "Free"), os.path.join(lib, "Blocked")
    kits = api("sampleLibraries")["libraries"][0]["dir"]
    for d, names in ((free, ("036 kick", "038 snare")), (blocked, ("042 hat", "049 crash"))):
        os.makedirs(d)
        for n in names:
            src = next(f for f in os.listdir(os.path.join(kits, "basic")) if f.startswith(n.split()[0]))
            shutil.copy(os.path.join(kits, "basic", src), os.path.join(d, n + ".wav"))
    procs = []

    def start():
        err = open(os.path.join(run_dir, "unidaw.err"), "a")
        procs.append(subprocess.Popen(
            [os.path.abspath(UNIDAW_BIN), "--port", str(port), "--log", "events.jsonl", "--config", "config",
             "--interface-sim"],
            cwd=run_dir, stdout=subprocess.DEVNULL, stderr=err, start_new_session=True))
        check(_wait_health(port), "Instanz startet")

    def stop():
        try:
            _api_at(port, "quit")
        except Exception:
            pass
        try:
            procs[-1].wait(timeout=20)
        except subprocess.TimeoutExpired:
            os.killpg(procs[-1].pid, signal.SIGKILL)

    def mine():
        return next(x for x in _api_at(port, "sampleLibraries")["libraries"] if x["dir"] == lib)

    def wait_done():
        for _ in range(3000):
            a = _api_at(port, "sampleLibraries")
            if not a["analysis"].get("running") and not any(x["indexing"] for x in a["libraries"]):
                return a["analysis"]
            time.sleep(0.1)
        return {}

    start()
    try:
        r = _api_at(port, "findSamples", text="kick drum")
        if r.get("ok") is False and "tools/fetch_ml.sh" in r.get("error", ""):
            print("    skip sound license block (" + r["error"] + ")")
            return
        check(_api_at(port, "sampleLibraries", add=lib).get("ok") is True, "anmelden")
        wait_done()
        check(_api_at(port, "sampleLibraries", analyze=lib).get("ok") is True, "Analyse startet")
        wait_done()
        check(mine()["analyzed"] == 4 and "noAnalysis" not in mine(), f"alle vier analysiert: {mine()}")

        r = _api_at(port, "sampleLibraries", noAnalysis=blocked)
        check(r.get("ok") is True and r.get("removed") == 2 and r.get("noAnalysis") == [blocked],
              f"sperren loescht zwei: {r}")
        check(mine()["analyzed"] == 2 and mine().get("noAnalysis") == 2, f"zwei bleiben, zwei gesperrt: {mine()}")
        with open(os.path.join(config, "libraries.json")) as f:
            check(json.load(f).get("noAnalysis") == [blocked], "Sperre in libraries.json")

        r = _api_at(port, "findSamples", like={"file": os.path.join(blocked, "042 hat.wav")})
        check(r.get("ok") is False and r.get("error", "").startswith("no sound analysis for files in " + blocked),
              f"like auf gesperrte Datei: {r}")
        r = _api_at(port, "findSamples", like=os.path.join(free, "038 snare.wav"), dir=lib, category="any")
        check(r.get("ok") is True and r.get("analyzed") == 2 and r.get("notAnalyzed") == 2
              and [x["name"] for x in r["samples"]] == ["036 kick"], f"like nur ueber Free: {r}")
        r = _api_at(port, "findSamples", text="hi-hat", dir=blocked, category="any")
        check(r.get("hint", "").startswith("no sound analysis in " + blocked), f"Hinweis im gesperrten Ordner: {r}")
        r = _api_at(port, "findSamples", query="hat", dir=blocked)
        check(r.get("ok") is True and [x["name"] for x in r["samples"]] == ["042 hat"], f"Namenssuche bleibt: {r}")

        r = _api_at(port, "sampleLibraries", analyze=blocked)
        check(r.get("ok") is False and r.get("error", "").startswith("no sound analysis in " + blocked),
              f"analyze im gesperrten Ordner: {r}")
        r = _api_at(port, "sampleLibraries", analyze=lib)
        a = wait_done()
        check(r.get("ok") is True and a.get("total") == 2 and a.get("unchanged") == 2 and mine()["analyzed"] == 2,
              f"Analyse ueberspringt den Ordner: {a}")

        for args, err in [({"noAnalysis": blocked}, "already without sound analysis: " + blocked),
                          ({"noAnalysis": os.path.join(blocked, "x")}, "already without sound analysis: " + blocked),
                          ({"noAnalysis": "relative/dir"}, "noAnalysis needs an absolute folder path"),
                          ({"allowAnalysis": free}, "not blocked: " + free),
                          ({"allowAnalysis": os.path.join(blocked, "x")},
                           "blocked through its parent " + blocked + " - allow that folder instead")]:
            r = _api_at(port, "sampleLibraries", **args)
            check(r.get("ok") is False and r.get("error") == err, f"{args}: {r}")
        check(_api_at(port, "sampleLibraries").get("noAnalysis") == [blocked], "Fehler aendern nichts")

        # Neustart: Sperre bleibt; von Hand eingetragene Sperre loescht beim Start
        stop()
        with open(os.path.join(config, "libraries.json")) as f:
            j = json.load(f)
        j["noAnalysis"].append(free)
        with open(os.path.join(config, "libraries.json"), "w") as f:
            json.dump(j, f)
        start()
        r = _api_at(port, "sampleLibraries")
        check(r.get("noAnalysis") == [blocked, free] and mine()["analyzed"] == 0, f"nach Neustart nichts analysiert: {r}")

        # Freigeben: Analyse holt den Ordner nach
        check(_api_at(port, "sampleLibraries", allowAnalysis=free).get("noAnalysis") == [blocked], "Free freigeben")
        _api_at(port, "sampleLibraries", analyze=lib)
        wait_done()
        check(mine()["analyzed"] == 2, f"Free wieder analysiert: {mine()}")
        r = _api_at(port, "sampleLibraries", allowAnalysis=blocked)
        check(r.get("noAnalysis") == [] and "noAnalysis" not in mine(), f"alles frei: {r}")
        with open(os.path.join(config, "libraries.json")) as f:
            check("noAnalysis" not in json.load(f), "libraries.json ohne Sperre")
    finally:
        stop()


@t("analysis_licence_block_flow")
def _():
    # Analyse-Ops auf Material aus gesperrten Ordnern (Decision
    # 2026-11-18-analyse-ops-auf-gesperrten-samples): Datei aus dem Ordner
    # lehnen ML-Ops und Messungen ab, Pegel (analyze) bleibt frei; eine Spur
    # mit dem Material lehnt audioToMidi ab, detectTempo misst mit
    # licenceNote. Kopien (setSamples), Clip-FX und Freeze behalten die
    # Herkunft (.dawd-origins.json); allowAnalysis wirkt sofort. Eigene
    # Instanz (eigener --config), audioToMidi mode drums braucht kein Modell.
    port = PORT + 1
    run_dir = tempfile.mkdtemp(prefix="dawd-licence-run-")
    lib = tempfile.mkdtemp(prefix="dawd-licence-lib-")
    blocked, free = os.path.join(lib, "Vendor"), os.path.join(lib, "Free")
    os.makedirs(blocked)
    os.makedirs(free)
    clicks = [0.0] * (44100 * 8)
    for k in range(16):   # 120 BPM, betonte Eins
        for i in range(400):
            clicks[int(k * 0.5 * 44100) + i] = (0.9 if k % 4 == 0 else 0.5) * math.sin(i * 0.3) * (1 - i / 400)
    loop, hit, free_loop = os.path.join(blocked, "loop.wav"), os.path.join(blocked, "hit.wav"), os.path.join(free, "loop.wav")
    write_mono(loop, clicks)
    write_mono(free_loop, clicks)
    write_mono(hit, clicks[:8000])
    d = tempfile.mkdtemp(prefix="dawd-licence-")
    err = open(os.path.join(run_dir, "unidaw.err"), "a")
    proc = subprocess.Popen([os.path.abspath(UNIDAW_BIN), "--port", str(port), "--log", "events.jsonl", "--config", "config",
                             "--interface-sim"], cwd=run_dir, stdout=subprocess.DEVNULL, stderr=err, start_new_session=True)
    check(_wait_health(port), "Instanz startet")

    def call(op, **kw):
        return _api_at(port, op, **kw)

    def refused(r, *parts):
        return r.get("ok") is False and all(p in r.get("error", "") for p in parts)

    def origins(path):
        with open(os.path.join(os.path.dirname(path), ".dawd-origins.json")) as f:
            return json.load(f).get(os.path.basename(path), [])

    try:
        check(call("treeSeed", dir=d, label="licence").get("ok") is True, "seed")
        check(call("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
        check(call("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "4 Takte 120 BPM")
        check(call("detectTempo", file=loop).get("ok") is True, "vor der Sperre frei")
        check(call("sampleLibraries", noAnalysis=blocked).get("noAnalysis") == [blocked], "Ordner sperren")

        # Datei aus dem Ordner
        msg = "no analysis of files in " + blocked + " (blocked for its licence"
        check(refused(call("detectTempo", file=loop), msg), "detectTempo {file} abgelehnt")
        check(refused(call("audioToMidi", file=loop, mode="drums"), msg), "audioToMidi {file} abgelehnt")
        check(refused(call("analyze", file=loop, embed=True), msg), "analyze {embed} abgelehnt")
        r = call("analyze", file=loop)
        check(r.get("ok") is True and "licenceNote" not in r, f"analyze {{file}} misst Pegel: {r}")
        check(call("detectTempo", file=free_loop).get("ok") is True, "Datei aus freiem Ordner")

        # Sampler-Spur mit Kopie aus dem Ordner
        kit = call("createTrack", type="midi", instrument="Sampler", name="Kit")
        r = call("setSamples", plugin=kit["id"], samples=[{"file": hit, "note": 36}])
        copy = r.get("samples", [{}])[0].get("file", "")
        check(r.get("ok") is True and copy.startswith(os.path.join(d, "media", "samples")), f"setSamples kopiert: {r}")
        check(origins(copy) == [hit], f"Kopie kennt ihre Quelle: {origins(copy)}")
        notes = [{"pitch": 36, "start": i * 0.5, "length": 0.1, "velocity": 110} for i in range(16)]
        check(call("addMidiClip", track="Kit", section="Section 1", notes=notes).get("ok") is True, "Beat")
        check(refused(call("detectTempo", file=copy), msg, "is made from " + hit), "Kopie als Datei abgelehnt")
        r = call("audioToMidi", track="Kit", mode="drums")
        check(refused(r, "no analysis of material from a folder blocked for its licence", 'track "Kit" plays ' + hit),
              f"audioToMidi {{track}} abgelehnt: {r}")
        r = call("detectTempo", track="Kit")
        check(r.get("ok") is True and 'track "Kit" plays ' + hit in r.get("licenceNote", ""), f"detectTempo misst mit Hinweis: {r}")
        r = call("analyze", track="Kit")
        check(r.get("ok") is True and "licenceNote" not in r, f"analyze {{track}} ohne Hinweis: {r}")

        # Audio-Clip: Mix mit Hinweis, freie Spur frei, Clip-FX behaelt die Herkunft
        tl = call("addClip", track=-1, file=loop, section="Section 1")["track"]
        tf = call("addClip", track=-1, file=free_loop, section="Section 1")["track"]
        r = call("batch", commands=[{"op": "detectKey"}, {"op": "analyze"}])
        res = r.get("results", [{}, {}])
        check("plays " + loop in res[0].get("licenceNote", "") and "licenceNote" not in res[1] and "licenceNote" not in r,
              f"Hinweis je Befehl im batch: {r}")
        check(call("audioToMidi", track=tf, mode="drums").get("ok") is True, "freie Spur frei")
        rv = call("addPlugin", name="Reverb")["id"]
        name = call("state")["trackList"][tl]["clips"][0]["name"]
        r = call("processClip", track=tl, name=name, plugins=[rv])
        check(r.get("ok") is True and loop in origins(r.get("file", "")), f"Clip-FX kennt die Quelle: {r}")
        check(refused(call("detectTempo", file=r["file"]), "is made from " + loop), "Clip-FX-Datei abgelehnt")

        # Modell-Ops (basic-pitch): Ablehnung vor dem Modell; compareReference
        # misst mit Hinweis und laesst nur die Artikulation weg
        r = call("describeVoice", track="Kit")
        if "tools/fetch_ml.sh" in r.get("error", ""):
            print("    skip describeVoice/articulation (" + r["error"] + ")")
        else:
            check(refused(r, 'track "Kit" plays ' + hit), f"describeVoice {{track}} abgelehnt: {r}")
            r = call("compareReference", file=free_loop, articulation=True)
            check(r.get("ok") is True and "plays " + loop in r.get("licenceNote", "")
                  and any(h.startswith("articulation not compared - no analysis of material") for h in r.get("hints", [])),
                  f"compareReference ohne Artikulation: {r.get('licenceNote')} {r.get('hints')}")

        # Freeze: das Audio der Spur stammt aus der Kopie
        check(call("freezeTrack", track="Kit").get("ok") is True, "Kit gefroren")
        fz = [os.path.join(d, "freeze", f) for f in os.listdir(os.path.join(d, "freeze")) if f.endswith(".wav")]
        check(len(fz) == 1 and hit in origins(fz[0]), f"Freeze kennt die Quelle: {fz}")
        check(refused(call("audioToMidi", track="Kit", mode="drums"), 'plays ' + hit), "gefrorene Spur abgelehnt")

        # Freigabe wirkt sofort
        check(call("sampleLibraries", allowAnalysis=blocked).get("noAnalysis") == [], "freigeben")
        check(call("audioToMidi", track="Kit", mode="drums").get("ok") is True, "Spur wieder frei")
        r = call("detectTempo", file=loop)
        check(r.get("ok") is True and "licenceNote" not in r, f"Datei wieder frei: {r}")
    finally:
        try:
            call("quit")
        except Exception:
            pass
        try:
            proc.wait(timeout=20)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid, signal.SIGKILL)


@t("notes_in_beats_flow")
def _():
    # Noten in Beats: addMidiClip {startBeat, lengthBeats, notes: [{pitch,
    # beat, beats}]} rechnet ueber das Tempo der Section (90 BPM: ein Beat =
    # 0,667 s), setMidiNotes auch; clipPeaks liefert Beats mit; Sekunden und
    # Beats in einer Liste abgelehnt.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-beats-")
    check(api("treeSeed", dir=d, label="beats").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "A 120 BPM")
    check(api("addSection", name="B", bars=4, bpm=90).get("ok") is True, "B 90 BPM")
    b = next(x for x in api("state")["sections"] if x["name"] == "B")
    r = api("addMidiClip", track=-1, section="B", startBeat=4,
            notes=[{"pitch": 60, "beat": 0, "beats": 1}, {"pitch": 64, "beat": 2, "beats": 0.5, "velocity": 80}])
    check(r.get("ok") is True and abs(r["start"] - (b["start"] + 4 * 60 / 90)) < 1e-3 and r.get("startBeat") == 4.0
          and r.get("lengthBeats") == 2.5 and abs(r["length"] - 2.5 * 60 / 90) < 1e-3, f"Clip in Beats: {r}")
    name = next(c["name"] for c in api("state")["trackList"][r["track"]]["clips"])
    n = api("clipPeaks", track=r["track"], name=name).get("notes", [])
    check(len(n) == 2 and abs(n[0]["length"] - 60 / 90) < 1e-3 and abs(n[1]["start"] - 2 * 60 / 90) < 1e-3
          and (n[0]["beat"], n[0]["beats"], n[1]["beat"], n[1]["beats"]) == (0.0, 1.0, 2.0, 0.5) and n[1]["velocity"] == 80,
          f"Noten in Sekunden und Beats: {n}")

    r2 = api("setMidiNotes", track=r["track"], name=name, notes=[{"pitch": 67, "beat": 1, "beats": 1.5}])
    n = api("clipPeaks", track=r["track"], name=name).get("notes", [])
    check(r2.get("ok") is True and len(n) == 1 and n[0]["beat"] == 1.0 and n[0]["beats"] == 1.5
          and abs(n[0]["start"] - 60 / 90) < 1e-3, f"setMidiNotes in Beats: {n}")
    r = api("addMidiClip", track=-1, section="Section 1", lengthBeats=8, notes=[{"pitch": 60, "beat": 0, "beats": 1}])
    check(r.get("ok") is True and abs(r["length"] - 4.0) < 1e-3 and r.get("lengthBeats") == 8.0, f"lengthBeats bei 120 BPM: {r}")

    for args, err in [({"notes": [{"pitch": 60, "beat": 0, "beats": 1}, {"pitch": 62, "start": 0, "length": 1}]},
                       "notes mix seconds (start/length) and beats (beat/beats) — use one per call"),
                      ({"notes": [{"pitch": 60, "beat": -1, "beats": 1}]}, "invalid note"),
                      ({"notes": [{"pitch": 60, "beat": 0, "beats": 0}]}, "invalid note"),
                      ({"start": 1, "startBeat": 2, "notes": [{"pitch": 60, "beat": 0, "beats": 1}]}, "use start (seconds) or startBeat, not both"),
                      ({"length": 1, "lengthBeats": 2, "notes": [{"pitch": 60, "beat": 0, "beats": 1}]}, "use length (seconds) or lengthBeats, not both"),
                      ({"startBeat": -1, "notes": [{"pitch": 60, "beat": 0, "beats": 1}]}, "start must be >= 0")]:
        r = api("addMidiClip", track=-1, section="B", **args)
        check(r.get("ok") is False and str(r.get("error")).startswith(err), f"addMidiClip {err}: {r}")
    api("treeClose")


@t("beats_eighth_time_flow")
def _():
    # Beat-Einheit bei x/8 (Todo 2026-11-25-beat-einheit-bei-achtel-takten-nennen):
    # ein Beat ist der Notenwert des Nenners (in 3/8 und 6/8 eine Achtel),
    # bpm zaehlt Viertel - wie die Engine (240 / (bpm * Nenner) s je Beat).
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-eighths-")
    check(api("treeSeed", dir=d, label="eighths").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=72, timeSig="3/8").get("ok") is True, "3/8 72 BPM")
    check(api("addSection", name="Six", bars=2, bpm=120, timeSig="6/8").get("ok") is True, "6/8 120 BPM")
    secs = {x["name"]: x for x in api("state")["sections"]}
    a, six = secs["Section 1"], secs["Six"]
    # Taktlaenge: 3/8 bei 72 = 1,25 s, 6/8 bei 120 = 1,5 s
    check(abs(a["length"] - 4 * 1.25) < 1e-3 and abs(a["bars"] - 4) < 1e-3 and a["timeSig"] == "3/8",
          f"3/8: vier Takte = 5 s: {a}")
    check(abs(six["length"] - 2 * 1.5) < 1e-3 and abs(six["bars"] - 2) < 1e-3 and six["timeSig"] == "6/8",
          f"6/8: zwei Takte = 3 s: {six}")

    # 3/8: Beat 1 = eine Achtel = 0,4167 s, drei Beats = ein Takt
    r = api("addMidiClip", track=-1, section="Section 1", startBeat=1, lengthBeats=3,
            notes=[{"pitch": 60, "beat": 0, "beats": 1}, {"pitch": 64, "beat": 2, "beats": 1}])
    check(r.get("ok") is True and abs(r["start"] - (a["start"] + 60 / 72 / 2)) < 1e-3
          and abs(r["length"] - 1.25) < 1e-3 and r.get("startBeat") == 1.0 and r.get("lengthBeats") == 3.0,
          f"3/8: startBeat 1 = 0,417 s, lengthBeats 3 = 1,25 s: {r}")
    name = next(c["name"] for c in api("state")["trackList"][r["track"]]["clips"])
    n = api("clipPeaks", track=r["track"], name=name).get("notes", [])
    check(len(n) == 2 and abs(n[1]["start"] - 2 * 60 / 72 / 2) < 1e-3 and abs(n[0]["length"] - 60 / 72 / 2) < 1e-3
          and (n[1]["beat"], n[1]["beats"]) == (2.0, 1.0), f"3/8: Noten in Achteln: {n}")

    # 6/8: startBeat 6 = Takt 2 = 1,5 s, Beat 3 = 0,75 s
    r = api("addMidiClip", track=-1, section="Six", startBeat=6, lengthBeats=6,
            notes=[{"pitch": 67, "beat": 3, "beats": 1.5}])
    check(r.get("ok") is True and abs(r["start"] - (six["start"] + 1.5)) < 1e-3
          and abs(r["length"] - 1.5) < 1e-3, f"6/8: startBeat 6 = ein Takt = 1,5 s: {r}")
    name = next(c["name"] for c in api("state")["trackList"][r["track"]]["clips"])
    n = api("clipPeaks", track=r["track"], name=name).get("notes", [])
    check(len(n) == 1 and abs(n[0]["start"] - 0.75) < 1e-3 and abs(n[0]["length"] - 0.375) < 1e-3,
          f"6/8: Beat 3 = 0,75 s, 1,5 Beats = 0,375 s: {n}")
    api("treeClose")


@t("midi_pattern_lane_flow")
def _():
    # Praxistest 1b: Clip in Beats mit Noten in Sekunden abgelehnt,
    # unbekannte Notenfelder mit Namen, startBeat/lengthBeats je Note als
    # Alias; addMidiClip legt Clips nebeneinander in die spielende Lane statt
    # je Clip eine neue Lane (die die alte stummschaltet) — neue Lane nur bei
    # Ueberlappung oder newLane, mit Meldung; setMidiNotes waechst nicht
    # ueber den naechsten Clip.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-pattern-")
    check(api("treeSeed", dir=d, label="pattern").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "4 Takte 120 BPM")
    r = api("addMidiClip", track=-1, section="Section 1", startBeat=0, lengthBeats=4,
            notes=[{"pitch": 36, "start": 0, "length": 1}])
    check(r.get("ok") is False and "notes use start/length (seconds)" in r.get("error", ""), f"Beats-Clip, Sekunden-Noten: {r}")
    r = api("addMidiClip", track=-1, section="Section 1", startBeat=0, lengthBeats=4,
            notes=[{"pitch": 36, "startBeat": 0, "lenght": 1}])
    check(r.get("ok") is False and r.get("error", "").startswith("unknown note field 'lenght'"), f"Tippfehler im Feld: {r}")

    a = api("addMidiClip", track=-1, section="Section 1", startBeat=0, lengthBeats=4, name="Bar",
            notes=[{"pitch": 36, "startBeat": 0, "lengthBeats": 0.5}])
    check(a.get("ok") is True and a.get("notesIn") == "beats" and a.get("newLane") is True, f"erster Clip, Alias-Felder: {a}")
    group = a["laneOf"]
    b = api("addMidiClip", track=group, section="Section 1", startBeat=4, lengthBeats=4, name="Bar",
            notes=[{"pitch": 38, "beat": 1, "beats": 0.5}])
    check(b.get("ok") is True and b.get("newLane") is False and b.get("track") == a["track"] and b.get("name") == "Bar 2",
          f"zweiter Clip in dieselbe Lane: {b}")
    c = api("addMidiClip", track=a["track"], section="Section 1", startBeat=8, lengthBeats=4, name="Fill",
            notes=[{"pitch": 38, "beat": 0, "beats": 0.25}])
    check(c.get("ok") is True and c.get("newLane") is False and c.get("track") == a["track"], f"direkt auf die Lane: {c}")
    o = api("addMidiClip", track=group, section="Section 1", startBeat=2, lengthBeats=4,
            notes=[{"pitch": 42, "beat": 0, "beats": 0.25}])
    check(o.get("ok") is False and o.get("error", "").startswith("overlaps 'Bar' (0.0-2.0 s), 'Bar 2' (2.0-4.0 s) on "),
          f"Ueberlappung = Fehler (Decision 2026-10-29-ueberlappung-fehler): {o}")
    o = api("addMidiClip", track=group, section="Section 1", startBeat=2, lengthBeats=4, newLane=True,
            notes=[{"pitch": 42, "beat": 0, "beats": 0.25}])
    check(o.get("ok") is True and o.get("newLane") is True and o.get("newLaneReason") == "newLane: true"
          and o.get("mutedLanes") == [a["lane"]], f"newLane: neue Lane mit Meldung: {o}")

    # setMidiNotes waechst bis zum naechsten Clip, nicht darueber
    api("laneActive", track=a["track"])
    r = api("setMidiNotes", track=a["track"], name="Bar", notes=[{"pitch": 36, "beat": 0, "beats": 1}, {"pitch": 36, "beat": 6, "beats": 1}])
    clips = {x["name"]: x for x in api("state")["trackList"][a["track"]]["clips"]}
    check(r.get("ok") is True and abs(clips["Bar"]["length"] - 2.0) < 1e-3 and "silent" in r.get("warning", "")
          and "next clip Bar 2" in r.get("warning", ""), f"setMidiNotes ohne Ueberlappung: {r} {clips.get('Bar')}")

    # Kopien bilden ein Pattern: setMidiNotes {copies: true} aendert alle
    r = api("setMidiNotes", track=a["track"], name="Fill", notes=[{"pitch": 36, "beat": 0, "beats": 1}], copies=True)
    check(r.get("ok") is False and r.get("error", "").startswith("clip has no copies"), f"ohne Kopien: {r}")
    # copies ist keine Wiederholungszahl (Praxistest remix-1: copies 16)
    r = api("setMidiNotes", track=a["track"], name="Fill", notes=[{"pitch": 36, "beat": 0, "beats": 1}], copies=16)
    check(r.get("ok") is False and r.get("error", "").startswith("copies must be true or false"), f"copies 16: {r}")
    api("deleteClip", track=a["track"], name="Fill")
    dup = api("duplicateClip", track=a["track"], name="Bar 2", startBeat=8, count=2)
    clips = {x["name"]: x for x in api("state")["trackList"][a["track"]]["clips"]}
    copies = [c["name"] for c in dup.get("clips", [])]
    check(dup.get("ok") is True and len(copies) == 2 and all(clips[n].get("pattern") == "Bar 2" for n in copies + ["Bar 2"])
          and "pattern" not in clips["Bar"], f"Pattern-Markierung: {clips}")
    r = api("setMidiNotes", track=a["track"], name=copies[1], copies=True,
            notes=[{"pitch": 38, "beat": 0, "beats": 0.5}, {"pitch": 42, "beat": 2, "beats": 0.5}])
    peaks = {n: api("clipPeaks", track=a["track"], name=n).get("notes", []) for n in copies + ["Bar 2", "Bar"]}
    check(r.get("ok") is True and sorted(r.get("updated", [])) == sorted(copies + ["Bar 2"])
          and all([x["pitch"] for x in peaks[n]] == [38, 42] for n in copies + ["Bar 2"]) and len(peaks["Bar"]) >= 1
          and peaks["Bar"][0]["pitch"] == 36, f"alle Kopien geaendert, Bar nicht: {r} {peaks}")
    api("treeClose")


@t("quantize_groove_flow")
def _():
    # quantizeClip: Noten aufs Raster der Section (destruktiv, Undo), strength,
    # swing, window, Fehlertexte; extractGroove liest aus einem Render mit
    # geswingten 16teln die Verschiebung je Rasterplatz, quantizeClip {groove}
    # legt sie auf einen geraden Clip.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-quant-")
    check(api("treeSeed", dir=d, label="quant").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=8, bpm=100).get("ok") is True, "8 Takte 100 BPM")
    a = api("addMidiClip", track=-1, section="Section 1", startBeat=0, lengthBeats=4, name="Off",
            notes=[{"pitch": 60, "beat": b, "beats": 0.5} for b in (0.05, 1.1, 1.95, 3.02)])
    lane = a["track"]

    def beats(name):
        return [round(n["beat"], 3) for n in api("clipPeaks", track=lane, name=name).get("notes", [])]

    r = api("quantizeClip", track=lane, name="Off", grid="1/4", strength=0.5)
    check(r.get("ok") is True and r.get("moved") == 4 and beats("Off") == [0.025, 1.05, 1.975, 3.01], f"strength 0.5: {r} {beats('Off')}")
    r = api("quantizeClip", track=lane, name="Off", grid="1/4")
    check(r.get("ok") is True and beats("Off") == [0.0, 1.0, 2.0, 3.0], f"1/4 voll: {beats('Off')}")
    u = api("undo")
    check(u.get("ok") is True and beats("Off") == [0.025, 1.05, 1.975, 3.01], f"undo: {beats('Off')}")

    s8 = api("addMidiClip", track=lane, section="Section 1", startBeat=4, lengthBeats=4, name="Eighths",
             notes=[{"pitch": 62, "beat": b * 0.5, "beats": 0.25} for b in range(8)])
    r = api("quantizeClip", track=lane, name="Eighths", grid="1/8", swing=0.5)
    check(r.get("ok") is True and beats("Eighths")[:4] == [0.0, 0.75, 1.0, 1.75], f"swing 0.5 auf 1/8: {beats('Eighths')}")
    w = api("addMidiClip", track=lane, section="Section 1", startBeat=8, lengthBeats=4, name="Window",
            notes=[{"pitch": 64, "beat": 0.4, "beats": 0.25}, {"pitch": 64, "beat": 1.05, "beats": 0.25}])
    r = api("quantizeClip", track=lane, name="Window", grid="1/4", window=0.5)
    check(r.get("ok") is True and beats("Window") == [0.4, 1.0], f"window: nur nahe Noten: {beats('Window')}")
    for args, err in [({"name": "Nope"}, "no such MIDI clip"), ({"name": "Off", "grid": "1/5"}, "grid must be"),
                      ({"name": "Off", "strength": 2}, "strength must be 0..1"),
                      ({"name": "Off", "groove": {"slots": []}}, "groove needs slots"),
                      ({"name": "Off", "groove": {"slots": [{"slot": 0, "offset": 0}]}, "swing": 0.2}, "use swing or groove")]:
        r = api("quantizeClip", track=lane, **args)
        check(r.get("ok") is False and r.get("error", "").startswith(err), f"quantizeClip {args}: {r}")

    # Groove aus einem Render: Drum Kit, 16tel-Hats mit ungeraden Plaetzen
    # 0.3 Raster spaeter, Kick/Snare auf den Vierteln
    kit = api("createTrack", type="midi", instrument="Drum Kit")
    notes = []
    for bar in range(8):
        for k in range(16):
            beat = bar * 4 + k * 0.25 + (0.3 * 0.25 if k % 2 else 0)
            notes.append({"pitch": 42, "beat": beat, "beats": 0.1, "velocity": 90})
            if k % 4 == 0:
                notes.append({"pitch": 36 if k % 8 == 0 else 38, "beat": beat, "beats": 0.2, "velocity": 120})
    check(api("addMidiClip", track=kit["index"], section="Section 1", startBeat=0, lengthBeats=32, notes=notes).get("ok") is True, "Beat")
    out = os.path.join(d, "swing.wav")
    api("trackMix", track=lane, mute=True)
    check(api("render", file=out, section="Section 1").get("ok") is True, "Render")
    g = api("extractGroove", file=out, grid="1/16")
    slots = {x["slot"]: x for x in g.get("slots", [])}
    odd = [slots[k]["offset"] for k in range(1, 16, 2) if "offset" in slots.get(k, {})]
    even = [slots[k]["offset"] for k in range(0, 16, 2) if "offset" in slots.get(k, {})]
    check(g.get("ok") is True and len(slots) == 16 and odd and even and all(abs(o - 0.3) < 0.1 for o in odd)
          and all(abs(e) < 0.1 for e in even) and abs((g.get("swing") or 0) - 0.3) < 0.1,
          f"extractGroove: swing {g.get('swing')} odd {odd} even {even} {g.get('error')}")
    straight = api("addMidiClip", track=lane, section="Section 1", startBeat=12, lengthBeats=4, name="Straight",
                   notes=[{"pitch": 42, "beat": k * 0.25, "beats": 0.1} for k in range(4)])
    r = api("quantizeClip", track=lane, name="Straight", groove=g)
    bs = beats("Straight")
    check(r.get("ok") is True and r.get("grid") == 0.25 and abs(bs[0]) < 0.02 and abs(bs[1] - (0.25 + 0.075)) < 0.03
          and abs(bs[2] - 0.5) < 0.02, f"Groove auf geraden Clip: {r} {bs}")
    r = api("extractGroove", file=out, instrument="cowbell")
    check(r.get("ok") is False and r.get("error", "").startswith("instrument must be"), f"extractGroove instrument: {r}")
    api("treeClose")


@t("clip_split_duplicate_flow")
def _():
    # splitClip (at/atBeat, links behaelt den Namen, rechts ein freier),
    # duplicateClip (hinter den Clip, count Kopien am Stueck — ueber
    # Section-Grenzen: section_span_flow —, start in eine andere Section),
    # duplicateSection (Kopie mit Clips und Tempo,
    # spaetere Sections ruecken), Fehlertexte, Undo.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-dup-")
    check(api("treeSeed", dir=d, label="dup").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "A: 4 Takte 120 BPM (8 s)")
    check(api("addSection", name="B", bars=2).get("ok") is True, "B")
    kit = api("createTrack", type="midi", instrument="Drum Kit")
    r = api("addMidiClip", track=kit["index"], section="Section 1", lengthBeats=4,
            notes=[{"pitch": 36, "beat": b, "beats": 0.25} for b in range(4)])
    lane = r["track"]

    def clips():
        return {c["name"]: c for c in api("state")["trackList"][lane]["clips"]}

    r = api("duplicateClip", track=lane, name="Notes", count=3)
    made = [(c["name"], c["start"]) for c in r.get("clips", [])]
    check(r.get("ok") is True and made == [("Notes 2", 2.0), ("Notes 3", 4.0), ("Notes 4", 6.0)] and "skipped" not in r,
          f"count 3 am Stueck: {made} {r.get('skipped')}")
    b0 = next(x for x in api("state")["sections"] if x["name"] == "B")["start"]
    r = api("duplicateClip", track=lane, name="Notes", start=b0)
    check(r.get("ok") is True and r["clips"][0]["name"] == "Notes 5" and abs(r["clips"][0]["start"] - b0) < 1e-6, f"in Section B: {r}")
    n0 = api("clipPeaks", track=lane, name="Notes")["notes"]
    n5 = api("clipPeaks", track=lane, name="Notes 5")["notes"]
    check([(x["pitch"], x["beat"]) for x in n0] == [(x["pitch"], x["beat"]) for x in n5], "Kopie mit denselben Noten")
    out = os.path.join(d, "dup.wav")
    check(api("render", file=out).get("ok") is True and wav_peak(out, 6.0, 6.2) > 0.05 and wav_peak(out, b0, b0 + 0.2) > 0.05,
          "Kopien klingen (6 s und Section B)")

    r = api("splitClip", track=lane, name="Notes", atBeat=2)
    cl = clips()
    check(r.get("ok") is True and r["left"]["name"] == "Notes" and abs(r["left"]["length"] - 1.0) < 1e-6
          and r["right"]["name"] == "Notes 6" and abs(r["right"]["start"] - 1.0) < 1e-6 and abs(r["right"]["length"] - 1.0) < 1e-6,
          f"split: {r}")
    check(len(api("clipPeaks", track=lane, name="Notes")["notes"]) == 2 and len(api("clipPeaks", track=lane, name="Notes 6")["notes"]) == 2,
          "je zwei Noten links und rechts")
    tone = os.path.join(d, "tone.wav")
    make_tone(tone, seconds=1.0)
    a = api("addClip", track=-1, file=tone, section="B")
    aname = next(c["name"] for c in api("state")["trackList"][a["track"]]["clips"])
    r = api("splitClip", track=a["track"], name=aname, at=b0 + 0.4)
    check(r.get("ok") is True and abs(r["left"]["length"] - 0.4) < 1e-3 and abs(r["right"]["length"] - 0.6) < 1e-3, f"Audio-Split: {r}")

    for op, args, err in [("splitClip", {"track": lane, "name": "Notes", "at": 5.0}, "split point must lie inside the clip (0.000 .. 1.000 s)"),
                          ("splitClip", {"track": lane, "name": "Notes"}, "need at (song seconds) or atBeat (beats from the clip start)"),
                          ("splitClip", {"track": lane, "name": "Nope", "at": 0.5}, "no such clip: Nope"),
                          ("duplicateClip", {"track": lane, "name": "Notes", "count": 0}, "count must be 1..64"),
                          ("duplicateClip", {"track": lane, "name": "Notes", "start": 999}, "start lies outside every section (start 999.00 s; the sections end at "),
                          ("duplicateSection", {"name": "Nope"}, "no such section: Nope"),
                          ("duplicateSection", {"name": "B", "newName": "Section 1"}, "section exists: Section 1")]:
        r = api(op, **args)
        check(r.get("ok") is False and (r.get("error") == err or (err.endswith("end at ") and r.get("error", "").startswith(err))), f"{op} {err}: {r}")

    # Section duplizieren: Kopie direkt dahinter, B rueckt um 8 s
    before = len(clips())
    in_a = sum(1 for t in api("state")["trackList"] for c in t["clips"] if c["start"] < 8.0 - 1e-6)
    r = api("duplicateSection", name="Section 1")
    secs = [(x["name"], x["start"], x["bpm"]) for x in api("state")["sections"]]
    check(r.get("ok") is True and r.get("name") == "Section 1 2" and r.get("clips") == in_a and r.get("bars") == 4,
          f"duplicateSection: {r} (Clips in A: {in_a})")
    check(secs == [("Section 1", 0.0, 120.0), ("Section 1 2", 8.0, 120.0), ("B", 16.0, 120.0)], f"Reihenfolge: {secs}")
    cl = clips()
    check(len(cl) == before + 5 and abs(cl["Notes 5"]["start"] - 16.0) < 1e-6 and any(abs(c["start"] - 14.0) < 1e-6 for c in cl.values()),
          f"Clips kopiert, B-Clip gerueckt: {sorted((c['name'], c['start']) for c in cl.values())}")
    u = api("undo")
    check(u.get("ok") is True and [x["name"] for x in api("state")["sections"]] == ["Section 1", "B"], f"undo: {u.get('undone')}")
    acts = [a["op"] for a in api("treeState")["nodes"][0]["actions"]]
    check("splitClip" in acts and "duplicateClip" in acts and "duplicateSection" not in acts, f"Aktionen: {acts}")
    api("treeClose")


@t("clip_props_flow")
def _():
    # setClip: Audio-Gain, Blenden (hoerbar im Render), rueckwaerts (Rampe
    # gespiegelt), MIDI transponieren (Noten) und leiser, state zeigt die
    # Werte, Fehlertexte ohne Aenderung, eine process-Aktion je Clip, Undo.
    import math
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-clipprops-")
    ramp = os.path.join(d, "ramp.wav")
    with wave.open(ramp, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(44100)
        w.writeframes(b"".join(struct.pack("<h", int(0.8 * 32767 * (i / 88200) * math.sin(2 * math.pi * 440 * i / 44100)))
                               for i in range(88200)))
    flat = os.path.join(d, "flat.wav")
    make_sine(flat, 440, 0.5, seconds=2.0)
    check(api("treeSeed", dir=d, label="props").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=2).get("ok") is True, "2 s")
    a = api("addClip", track=0, file=flat, section="Section 1")
    t = a["track"]
    name = api("state")["trackList"][t]["clips"][0]["name"]
    out = os.path.join(d, "a.wav")
    api("render", file=out)
    base = wav_peak(out, 1.0, 1.1)

    r = api("setClip", track=t, name=name, gainDb=-6, fadeIn=0.5, fadeOut=0.5, fadeCurve="linear")
    check(r.get("ok") is True and r["gainDb"] == -6 and r["fadeIn"] == 0.5 and r["fadeOut"] == 0.5 and r["reversed"] is False, f"setClip: {r}")
    api("render", file=out)
    check(abs(wav_peak(out, 1.0, 1.1) / base - 0.5) < 0.05, f"-6 dB in der Mitte: {wav_peak(out, 1.0, 1.1)} vs {base}")
    check(wav_peak(out, 0.0, 0.05) < 0.1 * base and wav_peak(out, 1.95, 2.0) < 0.1 * base, "Ein- und Ausblende")
    c = api("state")["trackList"][t]["clips"][0]
    check((c.get("gainDb"), c.get("fadeIn"), c.get("fadeOut"), c.get("reversed")) == (-6.0, 0.5, 0.5, False), f"state: {c}")
    # Kurve in state und Antwort; eine Blende ohne fadeCurve laesst sie stehen
    # (das Popover schickte sonst immer "linear" mit — UI-Pruefung 2026-10-25)
    check(c.get("fadeCurve") == "linear", f"state fadeCurve: {c}")
    check(api("setClip", track=t, name=name, fadeCurve="convex").get("fadeCurve") == "convex", "fadeCurve convex")
    r = api("setClip", track=t, name=name, fadeIn=0.4)
    c = api("state")["trackList"][t]["clips"][0]
    check(r.get("fadeCurve") == "convex" and c.get("fadeCurve") == "convex" and c.get("fadeIn") == 0.4, f"Kurve bleibt: {r} {c}")
    check(api("setClip", track=t, name=name, fadeIn=0.5, fadeCurve="linear").get("ok") is True, "zurueck auf linear")

    # Rueckwaerts: eine anschwellende Rampe klingt abschwellend
    check(api("addSection", name="R", length=2).get("ok") is True, "Section R")
    rr = api("addClip", track=-1, file=ramp, section="R")
    rname = api("state")["trackList"][rr["track"]]["clips"][0]["name"]
    rs = next(x for x in api("state")["sections"] if x["name"] == "R")["start"]
    check(api("setClip", track=rr["track"], name=rname, reverse=True).get("reversed") is True, "reverse")
    api("render", file=out)
    check(wav_peak(out, rs, rs + 0.3) > 3 * wav_peak(out, rs + 1.7, rs + 2.0), "Rampe rueckwaerts: vorne laut")

    # MIDI: transponieren verschiebt die Noten, gainDb nur leiser
    m = api("addMidiClip", track=-1, section="Section 1", notes=[{"pitch": 90, "beat": 0, "beats": 1}, {"pitch": 94, "beat": 1, "beats": 1}])
    mname = api("state")["trackList"][m["track"]]["clips"][0]["name"]
    r = api("setClip", track=m["track"], name=mname, transpose=7, gainDb=-3)
    pitches = [n["pitch"] for n in api("clipPeaks", track=m["track"], name=mname)["notes"]]
    check(r.get("ok") is True and r.get("transpose") == 7 and r.get("gainDb") == -3 and pitches == [97, 101], f"MIDI +7: {r} {pitches}")
    # absolut (Praxistest 1d: 0 setzte nicht zurueck): +12 heisst +12 gegenueber dem Original, 0 zurueck
    r = api("setClip", track=m["track"], name=mname, transpose=12)
    pitches = [n["pitch"] for n in api("clipPeaks", track=m["track"], name=mname)["notes"]]
    check(r.get("transpose") == 12 and pitches == [102, 106], f"MIDI absolut +12: {r} {pitches}")
    r = api("setClip", track=m["track"], name=mname, transpose=0)
    pitches = [n["pitch"] for n in api("clipPeaks", track=m["track"], name=mname)["notes"]]
    check(r.get("ok") is True and r.get("transpose") == 0 and pitches == [90, 94], f"MIDI zurueck auf 0: {r} {pitches}")

    for args, err in [({"track": t, "name": name}, "nothing to set (gainDb, fadeIn, fadeOut, fadeCurve, transpose, reverse, normalize, crossfade)"),
                      ({"track": t, "name": name, "gainDb": 30}, "gainDb must be -48..24 for audio clips"),
                      ({"track": t, "name": name, "fadeIn": 1.5, "fadeOut": 1.0}, "fades must be >= 0 and fit into the clip together (2.000 s)"),
                      ({"track": t, "name": name, "fadeCurve": "wobbly"}, "fadeCurve must be linear, convex, concave, sCurve or auto"),
                      ({"track": m["track"], "name": mname, "fadeIn": 0.1}, "fades, crossfade and reverse work on audio clips only"),
                      ({"track": m["track"], "name": mname, "gainDb": 3},
                       "gainDb must be -100..0 for MIDI clips (they can only get quieter — use velocity or the track fader)"),
                      ({"track": m["track"], "name": mname, "transpose": 60}, "transpose must be -48..48 semitones"),
                      ({"track": m["track"], "name": mname, "transpose": 48, "gainDb": -3}, "transpose moves a note out of 0..127"),
                      ({"track": t, "name": "nope", "gainDb": 0}, "no such clip: nope")]:
        r = api("setClip", **args)
        check(r.get("ok") is False and r.get("error") == err, f"setClip {err}: {r}")
    c = api("state")["trackList"][t]["clips"][0]
    check((c.get("gainDb"), c.get("fadeIn")) == (-6.0, 0.5), "nach Fehlern unveraendert")

    acts = [x for x in api("treeState")["nodes"][0]["actions"] if x["op"] == "setClip"]
    check(len(acts) == 3 and all(x["kind"] == "process" for x in acts), f"eine Aktion je Clip: {[x['params'].get('name') for x in acts]}")
    check(api("setClip", track=t, name=name, gainDb=0).get("ok") is True and api("undo").get("ok") is True
          and api("state")["trackList"][t]["clips"][0]["gainDb"] == -6.0, "undo")
    api("treeClose")


@t("clip_normalize_flow")
def _():
    # setClip normalize: Peak/RMS des hoerbaren Bereichs (Quelldatei ohne
    # Clip-Gain) auf targetDb ueber gainDb — hoerbar im Render, nur der Bereich
    # nach trimClip zaehlt, Vorgaben ohne targetDb, Fehlertexte ohne
    # Aenderung, eine Aktion je Clip, Undo.
    import math
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-normalize-")
    sine = os.path.join(d, "sine.wav")
    make_sine(sine, 440, 0.25, seconds=2.0)   # Peak -12.04 dBFS, RMS -15.05 dBFS
    two = os.path.join(d, "two.wav")           # 1 s laut (0.5), 1 s leise (0.05)
    with wave.open(two, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(44100)
        w.writeframes(b"".join(struct.pack("<h", int((0.5 if i < 44100 else 0.05) * 32767 * math.sin(2 * math.pi * 440 * i / 44100)))
                               for i in range(88200)))
    quiet = os.path.join(d, "quiet.wav")
    make_sine(quiet, 440, 0.0005, seconds=1.0)
    check(api("treeSeed", dir=d, label="norm").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "4 s")
    a = api("addClip", track=0, file=sine, section="Section 1")
    t = a["track"]
    name = api("state")["trackList"][t]["clips"][0]["name"]
    out = os.path.join(d, "a.wav")
    api("render", file=out)
    base = wav_peak(out, 0.5, 1.5)

    r = api("setClip", track=t, name=name, normalize="peak")
    n = r.get("normalized", {})
    check(r.get("ok") is True and n.get("mode") == "peak" and abs(n.get("measuredDb", 0) + 12.04) < 0.05
          and n.get("targetDb") == -1 and abs(r.get("gainDb", 0) - 11.04) < 0.05, f"peak auf -1: {r}")
    api("render", file=out)
    ratio = wav_peak(out, 0.5, 1.5) / base
    check(abs(ratio - 10 ** (11.04 / 20)) < 0.1, f"im Render lauter: {ratio:.3f}")
    check(abs(api("state")["trackList"][t]["clips"][0]["gainDb"] - 11.04) < 0.05, "state gainDb")

    # RMS mit eigenem Ziel; misst ohne den gesetzten Clip-Gain
    r = api("setClip", track=t, name=name, normalize="rms", targetDb=-18)
    check(r.get("ok") is True and abs(r["normalized"]["measuredDb"] + 15.05) < 0.05 and abs(r["gainDb"] + 2.95) < 0.05, f"rms -18: {r}")
    r = api("setClip", track=t, name=name, normalize="rms")
    check(r.get("ok") is True and r["normalized"]["targetDb"] == -20 and abs(r["gainDb"] + 4.95) < 0.05, f"rms Vorgabe -20: {r}")

    # Nur der hoerbare Bereich: nach dem Trimmen zaehlt der leise Teil
    check(api("addSection", name="T", length=4).get("ok") is True, "Section T")
    b = api("addClip", track=-1, file=two, section="T")
    bname = api("state")["trackList"][b["track"]]["clips"][0]["name"]
    ts = next(x for x in api("state")["sections"] if x["name"] == "T")["start"]
    check(api("trimClip", track=b["track"], name=bname, start=ts + 1.0).get("ok") is True, "links getrimmt")
    r = api("setClip", track=b["track"], name=bname, normalize="peak", targetDb=-6)
    check(r.get("ok") is True and abs(r["normalized"]["measuredDb"] + 26.02) < 0.1 and abs(r["gainDb"] - 20.02) < 0.1,
          f"nur der leise Teil: {r}")

    m = api("addMidiClip", track=-1, section="Section 1", notes=[{"pitch": 60, "beat": 0, "beats": 1}])
    mname = api("state")["trackList"][m["track"]]["clips"][0]["name"]
    q = api("addClip", track=-1, file=quiet, section="Section 1")
    qname = api("state")["trackList"][q["track"]]["clips"][0]["name"]
    before = api("state")["trackList"][t]["clips"][0]["gainDb"]
    for args, err in [({"track": m["track"], "name": mname, "normalize": "peak"}, "normalize works on audio clips only"),
                      ({"track": t, "name": name, "normalize": "loud"}, "normalize must be peak or rms"),
                      ({"track": t, "name": name, "normalize": "peak", "gainDb": 0}, "normalize sets gainDb itself — send one of them"),
                      ({"track": t, "name": name, "targetDb": -3}, "targetDb needs normalize (peak or rms)"),
                      ({"track": t, "name": name, "normalize": "peak", "targetDb": 3}, "targetDb must be -60..0 dBFS"),
                      ({"track": q["track"], "name": qname, "normalize": "peak"}, "normalizing needs 65.2 dB of clip gain, more than -48..24 allows"),
                      ({"track": t, "name": name}, "nothing to set (gainDb, fadeIn, fadeOut, fadeCurve, transpose, reverse, normalize, crossfade)")]:
        r = api("setClip", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")
    check(api("state")["trackList"][t]["clips"][0]["gainDb"] == before, "nach Fehlern unveraendert")

    acts = [x for x in api("treeState")["nodes"][0]["actions"] if x["op"] == "setClip"]
    check(len(acts) == 2 and acts[0]["params"].get("normalize") == "rms", f"eine Aktion je Clip: {[x['params'] for x in acts]}")
    check(api("setClip", track=t, name=name, normalize="peak").get("ok") is True and api("undo").get("ok") is True
          and api("state")["trackList"][t]["clips"][0]["gainDb"] == before, "undo")
    api("treeClose")


@t("crossfade_flow")
def _():
    # setClip crossfade: ueberlappende Audio-Clips einer Lane blenden ueber
    # die Ueberlappung (autoCrossfade der Engine). Standard an, Kurve convex
    # (Decision 2026-10-25-crossfade-standard): zwei gleiche Signale in Phase
    # haben in der Mitte +3 dB (gleiche Leistung); fadeCurve linear haelt den
    # Pegel; nur an einem Clip blendet nur der; aus = sie addieren; ein
    # ausgeschalteter bleibt nach treeOpen aus; folgt moveClip; Clips eines
    # bestehenden Projekts ohne Flag werden beim Laden an; Fehlertexte; eine
    # Aktion je Clip; Undo.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-xfade-")
    sine = os.path.join(d, "sine.wav")
    make_sine(sine, 440, 0.25, seconds=2.0)
    check(api("treeSeed", dir=d, label="xfade").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "4 s")
    a = api("addClip", track=0, file=sine, section="Section 1")
    t = a["track"]
    an = api("state")["trackList"][t]["clips"][0]["name"]
    b = api("duplicateClip", track=t, name=an)   # Kopie auf derselben Lane
    check(b.get("ok") is True and len(b.get("clips", [])) == 1, f"Kopie: {b}")
    bn = b["clips"][0]["name"]

    def clips():
        return {c["name"]: c for c in api("state")["trackList"][t]["clips"]}

    # 440 Hz: ab 1.5 s und 1.0 s laeuft B in Phase mit A
    check(api("moveClip", track=t, name=bn, start=1.5).get("ok") is True, "B ueberlappt A um 0.5 s")
    c = clips()
    check(c[an]["crossfade"] and c[bn]["crossfade"] and c[an]["fadeCurveAuto"] and c[bn]["fadeCurveAuto"]
          and c[bn]["fadeCurve"] == "convex" and c[an]["fadeCurve"] == "linear"
          and abs(c[an]["fadeOut"] - 0.5) < 0.01 and abs(c[bn]["fadeIn"] - 0.5) < 0.01
          and c[an]["fadeIn"] == 0 and c[bn]["fadeOut"] == 0, f"Standard: Crossfade an, Kurve convex: {c}")
    out = os.path.join(d, "x.wav")
    api("render", file=out)
    base = wav_peak(out, 0.5, 1.0)
    mid = wav_peak(out, 1.7, 1.8)
    check(1.3 * base < mid < 1.5 * base, f"convex: gleiches Material +3 dB in der Mitte: {mid} vs {base}")
    check(wav_peak(out, 1.5, 2.0) < 1.5 * base, f"kein Verdoppeln: {wav_peak(out, 1.5, 2.0)} vs {base}")

    for n in (an, bn):
        r = api("setClip", track=t, name=n, fadeCurve="linear")
        check(r.get("ok") is True and r.get("crossfade") is True and r.get("fadeCurveAuto") is False
              and r.get("fadeCurve") == "linear", f"linear {n}: {r}")
    api("render", file=out)
    over = wav_peak(out, 1.5, 2.0)
    check(0.85 * base < over < 1.15 * base, f"linear haelt den Pegel: {over} vs {base}")
    acts = [x for x in api("treeState")["nodes"][0]["actions"] if x["op"] == "setClip"]
    check(len(acts) == 2, f"eine Aktion je Clip: {[x['params'] for x in acts]}")

    # Nur an A: A blendet aus, B setzt voll ein
    check(api("setClip", track=t, name=bn, crossfade=False).get("ok") is True, "B aus")
    c = clips()
    check(abs(c[an]["fadeOut"] - 0.5) < 0.01 and c[bn]["fadeIn"] == 0, f"nur A blendet: {c}")
    api("render", file=out)
    check(wav_peak(out, 1.7, 1.8) > 1.3 * base, f"B voll unter A: {wav_peak(out, 1.7, 1.8)}")
    check(api("undo").get("ok") is True and clips()[bn]["crossfade"] is True, "undo: B wieder an")

    # Verschieben: die Blenden folgen der neuen Ueberlappung
    check(api("moveClip", track=t, name=bn, start=1.0).get("ok") is True, "B auf 1.0 s")
    c = clips()
    check(abs(c[an]["fadeOut"] - 1.0) < 0.01 and abs(c[bn]["fadeIn"] - 1.0) < 0.01, f"Blenden folgen: {c}")
    api("render", file=out)
    over = wav_peak(out, 1.0, 2.0)
    check(0.85 * base < over < 1.15 * base, f"nach dem Verschieben: {over} vs {base}")

    # Beide aus: die Ueberlappung addiert
    for n in (an, bn):
        check(api("setClip", track=t, name=n, crossfade=False).get("ok") is True, f"{n} aus")
    api("render", file=out)
    check(wav_peak(out, 1.4, 1.6) > 1.8 * base, f"ohne Crossfade addiert: {wav_peak(out, 1.4, 1.6)} vs {base}")
    check(api("setClip", track=t, name=an, crossfade=True).get("ok") is True, "A wieder an")

    m = api("addMidiClip", track=-1, section="Section 1", notes=[{"pitch": 60, "beat": 0, "beats": 1}])
    mname = api("state")["trackList"][m["track"]]["clips"][0]["name"]
    for args, err in [({"track": m["track"], "name": mname, "crossfade": True}, "fades, crossfade and reverse work on audio clips only"),
                      ({"track": t, "name": an, "crossfade": "yes"}, "crossfade must be true or false"),
                      ({"track": t, "name": an, "fadeCurve": "sine"}, "fadeCurve must be linear, convex, concave, sCurve or auto")]:
        r = api("setClip", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")

    # treeOpen: A an (Blende neu gerechnet), B bleibt aus, linear bleibt linear
    api("treeClose")
    check(api("treeOpen", dir=d).get("ok") is True, "treeOpen")
    c = clips()
    check(c[an]["crossfade"] is True and c[bn]["crossfade"] is False and abs(c[an]["fadeOut"] - 1.0) < 0.01
          and c[bn]["fadeIn"] == 0 and c[an]["fadeCurveAuto"] is False, f"nach treeOpen: aus bleibt aus: {c}")
    api("render", file=out)
    check(wav_peak(out, 1.2, 1.3) > 1.5 * base, f"Render nach treeOpen: B voll unter A: {wav_peak(out, 1.2, 1.3)}")

    # Bestehendes Projekt (vor dem Standard): Clips ohne Flag und ohne Kurve
    # werden beim Laden an, mit convex
    api("treeClose")
    for f in [os.path.join(d, n) for n in os.listdir(d) if n.startswith("node-") and n.endswith(".tracktionedit")]:
        x = open(f).read()
        x = re.sub(r' (autoCrossfade|dawdAutoCurve|fadeInType|fadeOutType)="[^"]*"', "", x)
        open(f, "w").write(x)
    check(api("treeOpen", dir=d).get("ok") is True, "treeOpen altes Projekt")
    c = clips()
    check(c[an]["crossfade"] and c[bn]["crossfade"] and c[bn]["fadeCurveAuto"] and c[bn]["fadeCurve"] == "convex"
          and abs(c[bn]["fadeIn"] - 1.0) < 0.01, f"altes Projekt: an, convex: {c}")
    api("render", file=out)
    mid = wav_peak(out, 1.45, 1.55)
    check(1.3 * base < mid < 1.5 * base, f"altes Projekt blendet convex: {mid} vs {base}")
    r = api("setClip", track=t, name=bn, fadeCurve="auto")
    check(r.get("ok") is True and r.get("fadeCurveAuto") is True, f"fadeCurve auto: {r}")
    api("treeClose")


@t("marker_flow")
def _():
    # Marker: benannte Zeitpunkte neben den Sections — addMarker per Zeit oder
    # Takt/Schlag, state.markers mit Section/Takt, updateMarker verschieben/
    # umbenennen (eine Aktion je Marker), deleteMarker; Section-Ops nehmen sie
    # mit (Einfuegen schiebt, Loeschen entfernt die im Bereich, Umordnen zieht
    # sie mit, Kopieren kopiert sie mit eindeutigem Suffix); Fehlertexte;
    # Undo; treeOpen.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-marker-")
    check(api("treeSeed", dir=d, label="marker").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "A 4 Takte 120 BPM")
    for n in ("B", "C"):
        check(api("addSection", name=n, bars=4).get("ok") is True, n)   # A 0-8, B 8-16, C 16-24

    def marks():
        return [(m["name"], m["time"]) for m in api("state")["markers"]]

    r = api("addMarker", name="Drop", time=10)
    check(r.get("ok") is True and (r.get("name"), r.get("time"), r.get("section"), r.get("bar"), r.get("beat")) == ("Drop", 10.0, "B", 6, 1.0), f"Drop: {r}")
    r = api("addMarker", bar=3, beat=3)
    check(r.get("ok") is True and r.get("name") == "Marker 1" and r.get("time") == 5.0 and r.get("section") == "Section 1", f"Takt 3 Schlag 3: {r}")
    check(marks() == [("Marker 1", 5.0), ("Drop", 10.0)], f"state.markers nach Zeit: {marks()}")

    for op, args, err in [("addMarker", {"name": "X"}, "time or bar needed"),
                          ("addMarker", {"name": "Drop", "time": 1}, "marker exists: Drop"),
                          ("addMarker", {"time": 30}, "time must lie in the song (0..24.000 s)"),
                          ("addMarker", {"time": 1, "bar": 2}, "give time or bar, not both"),
                          ("addMarker", {"time": 1, "beat": 2}, "beat needs bar"),
                          ("addMarker", {"bar": 0}, "bar and beat count from 1"),
                          ("updateMarker", {"name": "Drop"}, "nothing to update (time, bar/beat or newName)"),
                          ("updateMarker", {"name": "Drop", "newName": "Marker 1"}, "marker exists: Marker 1"),
                          ("updateMarker", {"name": "Nope", "time": 1}, "no such marker: Nope"),
                          ("deleteMarker", {"name": "Nope"}, "no such marker: Nope")]:
        r = api(op, **args)
        check(r.get("ok") is False and r.get("error") == err, f"{op} {err}: {r}")
    check(marks() == [("Marker 1", 5.0), ("Drop", 10.0)], "nach Fehlern unveraendert")

    check(api("updateMarker", name="Drop", time=12).get("time") == 12.0, "verschoben")
    r = api("updateMarker", name="Drop", newName="Big Drop")
    check(r.get("ok") is True and r.get("name") == "Big Drop" and r.get("time") == 12.0, f"umbenannt: {r}")
    acts = api("treeState")["nodes"][0]["actions"]
    um = [a for a in acts if a["op"] == "updateMarker"]
    check(len(um) == 1 and um[0]["kind"] == "collect" and um[0]["params"].get("newName") == "Big Drop", f"eine Aktion je Marker: {um}")
    check([a["kind"] for a in acts if a["op"] == "addMarker"] == ["collect", "collect"], "addMarker collect")

    # Section-Ops: Einfuegen schiebt, Loeschen nimmt die Zeit samt Marker weg
    check(api("addSection", name="X", length=8, position="after", after="Section 1").get("ok") is True, "X nach A")
    check(marks() == [("Marker 1", 5.0), ("Big Drop", 20.0)], f"Einfuegen schiebt: {marks()}")
    check(api("deleteSection", name="X").get("ok") is True and marks() == [("Marker 1", 5.0), ("Big Drop", 12.0)], f"X weg: {marks()}")
    check(api("moveSection", name="B", position="first").get("ok") is True, "B nach vorn")
    check(marks() == [("Big Drop", 4.0), ("Marker 1", 13.0)], f"Umordnen zieht mit: {marks()}")
    # Kopieren kopiert die Marker mit Suffix (Matthias 2026-10-25)
    r = api("duplicateSection", name="B")
    check(r.get("ok") is True and r.get("markers") == ["Big Drop 2"], f"B kopiert: {r}")
    check(marks() == [("Big Drop", 4.0), ("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"Kopie mit Marker: {marks()}")
    r = api("duplicateSection", name="B")
    check(r.get("ok") is True and r.get("markers") == ["Big Drop 3"]
          and marks() == [("Big Drop", 4.0), ("Big Drop 3", 12.0), ("Big Drop 2", 20.0), ("Marker 1", 29.0)], f"Suffix eindeutig: {r} {marks()}")
    check(api("undo").get("ok") is True and marks() == [("Big Drop", 4.0), ("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"undo Kopie: {marks()}")
    check(api("deleteSection", name="B").get("ok") is True and marks() == [("Big Drop 2", 4.0), ("Marker 1", 13.0)], f"B samt Marker weg: {marks()}")
    check(api("undo").get("ok") is True and marks() == [("Big Drop", 4.0), ("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"undo: {marks()}")

    r = api("deleteMarker", name="Big Drop")
    check(r.get("ok") is True and marks() == [("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"deleteMarker: {r}")
    check([a["kind"] for a in api("treeState")["nodes"][0]["actions"] if a["op"] == "deleteMarker"] == ["process"], "deleteMarker process")
    check(api("undo").get("ok") is True and marks() == [("Big Drop", 4.0), ("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"undo deleteMarker: {marks()}")
    check(api("redo").get("ok") is True and marks() == [("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"redo: {marks()}")
    api("treeClose")
    check(api("treeOpen", dir=d).get("ok") is True and marks() == [("Big Drop 2", 12.0), ("Marker 1", 21.0)], f"nach treeOpen: {marks()}")
    api("treeClose")


@t("tempo_ramp_flow")
def _():
    # updateSection ramp: das Tempo der Section gleitet von ihrem bpm zum bpm
    # der naechsten (Kurve 0 in der Tempospur) — Sections behalten ihre
    # Sekunden, MIDI-Noten folgen der Rampe (Abstaende werden kuerzer), die
    # naechste Section beginnt auf ihrer Sekunde, bars ueber die Rampe und
    # bars setzen, ohne Folge-Tempo keine Wirkung, exportMidi schreibt
    # Stufen, duplicateSection kopiert die Rampe, Fehlertexte, Undo, treeOpen.
    import math
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-ramp-")
    check(api("treeSeed", dir=d, label="ramp").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", bars=4, bpm=100).get("ok") is True, "A 4 Takte 100")
    check(api("addSection", name="B", bars=4, bpm=140).get("ok") is True, "B 4 Takte 140")
    m = api("addMidiClip", track=-1, section="Section 1", notes=[{"pitch": 60, "beat": b, "beats": 0.5} for b in range(0, 17, 4)])
    mt, mname = m["track"], api("state")["trackList"][m["track"]]["clips"][0]["name"]

    def secs():
        return {x["name"]: x for x in api("state")["sections"]}

    def starts():
        return [n["start"] for n in api("clipPeaks", track=mt, name=mname)["notes"]]

    check([round(x, 3) for x in starts()] == [0.0, 2.4, 4.8, 7.2, 9.6], f"ohne Rampe 0.6 s je Beat: {starts()}")
    r = api("updateSection", name="Section 1", ramp=True)
    check(r.get("ok") is True and r.get("ramp") is True and r.get("bpm") == 100 and r.get("bpmEnd") == 140, f"Rampe an: {r}")
    s1 = secs()
    beats = s1["Section 1"]["bars"] * 4
    # Lineare Rampe in Beats: 9.6 s * 40 / (60 ln 1.4) = 19.02 Beats
    check(abs(beats - 9.6 * 40 / (60 * math.log(1.4))) < 0.05, f"Beats der Rampe: {beats}")
    check(abs(s1["B"]["start"] - 9.6) < 1e-9 and s1["B"]["bars"] == 4 and abs(s1["Section 1"]["length"] - 9.6) < 1e-9, f"Sekunden bleiben: {s1}")
    check(s1["Section 1"]["ramp"] is True and s1["Section 1"]["bpmEnd"] == 140 and s1["B"]["ramp"] is False, "state ramp/bpmEnd")

    # Noten folgen der Rampe wie die Engine sie rechnet (4 Stufen je Beat)
    n = int(min(100, max(1, 4 * beats)))

    def t_of(b):
        t, k = 0.0, 0
        while (k + 1) * beats / n <= b + 1e-9:
            t += beats / n * 60 / (100 + 40 * k / n)
            k += 1
        return t + (b - k * beats / n) * 60 / (100 + 40 * k / n)
    st = starts()
    check(len(st) == 5 and all(abs(a - t_of(b)) < 0.003 for a, b in zip(st, range(0, 17, 4))), f"Noten auf der Rampe: {st} vs {[round(t_of(b), 3) for b in range(0, 17, 4)]}")
    check(st[1] - st[0] > 1.15 * (st[4] - st[3]), f"schneller werdend: {st}")
    # Die naechste Section beginnt auf ihrer Sekunde: Note auf Beat 0 von B
    b = api("addMidiClip", track=mt, section="B", newLane=True, notes=[{"pitch": 62, "beat": 0, "beats": 1}, {"pitch": 62, "beat": 1, "beats": 1}])
    bn = [c for c in api("state")["trackList"][b["track"]]["clips"] if c["start"] > 9][0]
    bnotes = api("clipPeaks", track=b["track"], name=bn["name"])["notes"]
    check(abs(bn["start"] - 9.6) < 1e-6 and abs(bnotes[0]["start"]) < 0.001 and abs(bnotes[1]["start"] - 60 / 140) < 0.001, f"B ab 9.6 s in 140: {bn} {bnotes}")
    # Taktwechsel hinter der Rampe: B bleibt auf seiner Sekunde und in 140
    check(api("updateSection", name="B", timeSig="3/4").get("ok") is True, "B in 3/4")
    bnotes = api("clipPeaks", track=b["track"], name=bn["name"])["notes"]
    check(abs(bnotes[0]["start"]) < 0.001 and abs(bnotes[1]["start"] - 60 / 140) < 0.001, f"B nach Taktwechsel: {bnotes}")
    check(all(abs(a - b2) < 0.003 for a, b2 in zip(starts(), st)), f"Rampe nach Taktwechsel gleich: {starts()} vs {st}")

    # bars setzen: die Rampe dauert so lange, wie 4 Takte von 100 nach 140 brauchen
    r = api("updateSection", name="Section 1", bars=4)
    s1 = secs()
    check(r.get("ok") is True and r.get("bars") == 4 and s1["Section 1"]["bars"] == 4 and abs(s1["B"]["start"] - s1["Section 1"]["end"]) < 1e-9
          and 6.857 < s1["Section 1"]["length"] < 9.6, f"4 Takte Rampe: {r} {s1['Section 1']}")

    # exportMidi: Tempo-Stufen von 100 nach 140
    f = os.path.join(d, "ramp.mid")
    check(api("exportMidi", file=f).get("ok") is True, "exportMidi")
    _, _, trs = read_mid(f)
    bpms = [round(60000000 / e[2], 1) for e in trs[0] if e[1] == "tempo"]
    check(len(bpms) > 20 and bpms[0] == 100 and bpms[-1] == 140 and bpms == sorted(bpms), f"Stufen: {bpms[:4]} … {bpms[-3:]} ({len(bpms)})")

    # Ohne Folge-Tempo: keine Wirkung; Kopie traegt die Rampe mit
    r = api("updateSection", name="B", ramp=True)
    check(r.get("ok") is True and r.get("ramp") is True and r.get("bpmEnd") == 140, f"letzte Section: {r}")
    check(api("duplicateSection", name="Section 1", newName="A2").get("ok") is True, "Kopie")
    s1 = secs()
    # Reihenfolge Section 1, A2, B: A2 rampt nach B, Section 1 in A2 (gleiches Tempo, flach)
    check(s1["A2"]["ramp"] is True and s1["A2"]["bpm"] == 100 and s1["A2"]["bpmEnd"] == 140, f"Kopie rampt nach B: {s1['A2']}")
    # Sekunden bleiben (wie bei jedem Tempowechsel): flach bei 100 sind es weniger Takte
    check(s1["Section 1"]["bpmEnd"] == 100 and s1["Section 1"]["ramp"] is True
          and abs(s1["Section 1"]["bars"] - s1["Section 1"]["length"] / 2.4) < 0.001, f"Section 1 flach: {s1['Section 1']}")

    for args, err in [({"name": "B", "ramp": "yes"}, "ramp must be true or false"),
                      ({"name": "B"}, "nothing to update (label, start, length, bars, color, bpm, timeSig or ramp)")]:
        r = api("updateSection", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")
    check(api("undo").get("ok") is True and "A2" not in secs(), "undo Kopie")
    check(api("undo").get("ok") is True and secs()["B"]["ramp"] is False, "undo Rampe B")
    acts = [a for a in api("treeState")["nodes"][0]["actions"] if a["op"] == "updateSection" and "ramp" in a["params"]]
    check(len(acts) == 1 and acts[0]["kind"] == "collect", f"Aktion mit ramp: {acts}")
    before = starts()
    api("treeClose")
    check(api("treeOpen", dir=d).get("ok") is True and secs()["Section 1"]["ramp"] is True, "treeOpen")
    check(all(abs(a - b) < 1e-6 for a, b in zip(starts(), before)), f"Noten nach treeOpen gleich: {starts()} vs {before}")
    check(api("updateSection", name="Section 1", ramp=False).get("ok") is True and secs()["Section 1"]["bpmEnd"] == 100, "Rampe aus")
    api("treeClose")


@t("tempo_ramp_eighths_flow")
def _():
    # Rampe in x/8-Takten: die Beats der Engine zaehlen dort Achtel, bpm
    # Viertel — bars und Laenge mit Rampe stimmen in 3/8 und 6/8, die
    # naechste Section beginnt auf ihrer Sekunde, Noten folgen der Rampe
    # (Todo 2026-11-25-tempo-rampe-bars-bei-achtel-takten).
    import math
    for sig, num in (("3/8", 3), ("6/8", 6)):
        api("treeClose")
        d = tempfile.mkdtemp(prefix="dawd-ramp8-")
        check(api("treeSeed", dir=d, label="ramp8").get("ok") is True, "seed")
        check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
        check(api("updateSection", name="Section 1", bars=4, bpm=72, timeSig=sig).get("ok") is True, f"A {sig} 72")
        check(api("addSection", name="B", bars=4, bpm=96, timeSig=sig).get("ok") is True, f"B {sig} 96")

        def secs():
            return {x["name"]: x for x in api("state")["sections"]}

        # Ohne Rampe: 4 Takte = 4 * num Achtel zu 60/72/2 s
        s = secs()
        flat = 4 * num * 30 / 72
        check(abs(s["Section 1"]["length"] - flat) < 1e-6 and s["Section 1"]["bars"] == 4, f"{sig} flach: {s['Section 1']}")
        # Rampe an, Sekunden bleiben: Viertel der linearen Rampe = L * 24 / (60 ln(96/72))
        r = api("updateSection", name="Section 1", ramp=True)
        s = secs()
        quarters = flat * 24 / (60 * math.log(96 / 72))
        check(r.get("ok") is True and abs(s["Section 1"]["bars"] - quarters * 2 / num) < 0.02, f"{sig} Rampe an: bars {s['Section 1']['bars']} statt {quarters * 2 / num:.3f}")
        check(abs(s["B"]["start"] - flat) < 1e-9, f"{sig} B bleibt: {s['B']}")

        # bars setzen: 4 Takte = 4 * num Achtel, Engine-Stufen (4 je Achtel)
        eighths = 4 * num
        n = int(min(100, 4 * eighths))
        want = sum(eighths / n * 30 / (72 + 24 * k / n) for k in range(n))
        r = api("updateSection", name="Section 1", ramp=True, bars=4)
        s = secs()
        check(r.get("ok") is True and abs(s["Section 1"]["bars"] - 4) < 0.002 and abs(s["Section 1"]["length"] - want) < 0.002,
              f"{sig} 4 Takte Rampe: bars {s['Section 1']['bars']} Laenge {s['Section 1']['length']} statt {want:.4f}")
        check(abs(s["B"]["start"] - s["Section 1"]["end"]) < 1e-9 and s["B"]["bars"] == 4, f"{sig} B danach: {s['B']}")

        # Note auf Beat 0 und 1 von B: B beginnt auf seiner Sekunde, in 96
        # (Beat = Achtel in x/8)
        b = api("addMidiClip", track=-1, section="B", notes=[{"pitch": 62, "beat": 0, "beats": 1}, {"pitch": 62, "beat": 1, "beats": 1}])
        bn = [c for c in api("state")["trackList"][b["track"]]["clips"]][0]
        bnotes = api("clipPeaks", track=b["track"], name=bn["name"])["notes"]
        check(abs(bn["start"] - s["B"]["start"]) < 1e-6 and abs(bnotes[0]["start"]) < 0.001 and abs(bnotes[1]["start"] - 30 / 96) < 0.001,
              f"{sig} B in 96: {bn} {bnotes}")
        api("treeClose")


@t("section_delete_flow")
def _():
    # deleteSection: der Zeitbereich der Section samt der Clips darin weg
    # (Clips ueber ihren Grenzen werden abgeschnitten: section_time_flow),
    # spaetere ruecken nach links; die letzte Section bleibt; Undo holt
    # alles zurueck; process-Aktion.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-secdel-")
    tone = os.path.join(d, "tone.wav")
    make_tone(tone, seconds=1.0)
    check(api("treeSeed", dir=d, label="del").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "A 4 s")
    for n in ("B", "C"):
        check(api("addSection", name=n, length=4).get("ok") is True, n)
    for n in ("Section 1", "B", "C"):
        check(api("addClip", track=0, file=tone, section=n).get("ok") is True, "Clip in " + n)

    def layout():
        st = api("state")
        return ([(x["name"], x["start"]) for x in st["sections"]],
                sorted(c["start"] for t in st["trackList"] for c in t["clips"]))

    before = layout()
    r = api("deleteSection", name="B")
    check(r.get("ok") is True and r.get("clips") == 1 and r.get("cut") == 0 and r.get("length") == 4.0, f"deleteSection: {r}")
    check(layout() == ([("Section 1", 0.0), ("C", 4.0)], [0.0, 4.0]), f"C rueckt nach links: {layout()}")
    acts = [a for a in api("treeState")["nodes"][0]["actions"] if a["op"] == "deleteSection"]
    check(len(acts) == 1 and acts[0]["kind"] == "process", f"process-Aktion: {acts}")
    check(api("undo").get("ok") is True and layout() == before, f"undo: {layout()}")
    for args, err in [({"name": "Nope"}, "no such section: Nope")]:
        r = api("deleteSection", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")
    check(api("deleteSection", name="B").get("ok") is True and api("deleteSection", name="C").get("ok") is True, "B und C weg")
    r = api("deleteSection", name="Section 1")
    check(r.get("ok") is False and r.get("error") == "cannot delete the only section", f"letzte bleibt: {r}")
    api("treeClose")


def make_notes_wav(path, notes, rate=44100, total=None):
    """Klavieraehnliche Toene (Grundton + 2 Obertoene, kurzer Anschlag,
    Abklingen): notes = [(pitch, start, dauer)]."""
    import math
    total = total or max(t + d for _, t, d in notes) + 0.3
    n = int(total * rate)
    buf = [0.0] * n
    for pitch, t0, dur in notes:
        f = 440 * 2 ** ((pitch - 69) / 12)
        s0 = int(t0 * rate)
        for i in range(min(int(dur * rate), n - s0)):
            t = i / rate
            buf[s0 + i] += 0.25 * min(1, t / 0.005) * math.exp(-t * 3) * sum(math.sin(2 * math.pi * f * h * t) / h for h in (1, 2, 3))
    with wave.open(path, "w") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(b"".join(struct.pack("<h", int(max(-1, min(1, v)) * 32767)) for v in buf))


@t("harmony_compare_flow")
def _():
    # Praxistest 1b: compareReference vergleicht die Harmonie je Takt ueber
    # Tonklassen-Profile (Korrelation) statt Akkordnamen — gleiche Akkorde
    # ~1, andere Akkorde in Takt 3/4 als Hinweis.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-harmony-")

    def prog(chords):
        return [(p, bar * 2.0 + beat * 0.5, 0.5) for bar, ch in enumerate(chords) for beat in range(4) for p in ch]

    same = [(60, 64, 67), (65, 69, 72), (67, 71, 74), (69, 72, 76)]
    other = same[:2] + [(66, 70, 73), (61, 65, 68)]
    mix, ref_same, ref_other = (os.path.join(d, n) for n in ("mix.wav", "same.wav", "other.wav"))
    make_notes_wav(mix, prog(same), total=8.0)
    make_notes_wav(ref_same, prog(same), total=8.0)
    make_notes_wav(ref_other, prog(other), total=8.0)
    check(api("treeSeed", dir=d, label="harmony").get("ok") is True, "seed")
    check(api("updateSection", name="Section 1", bars=4, bpm=120).get("ok") is True, "4 Takte 120 BPM")
    check(api("addClip", track=0, file=mix, section="Section 1").get("ok") is True, "Mix")
    h = api("compareReference", file=ref_same, section="Section 1").get("diff", {}).get("harmony", {})
    check(h.get("barSeconds") == 2.0 and len(h.get("bars", [])) == 4 and h.get("similarity", 0) > 0.9, f"gleiche Harmonie: {h}")
    r = api("compareReference", file=ref_other, section="Section 1")
    h = r.get("diff", {}).get("harmony", {})
    sims = [b["similarity"] for b in h.get("bars", [])]
    check(len(sims) == 4 and min(sims[:2]) > 0.9 and max(sims[2:]) < 0.5
          and any("harmony differs in bars 3, 4" in x for x in r.get("hints", [])), f"andere Akkorde in Takt 3/4: {sims} {r.get('hints')}")
    api("treeClose")


@t("audio_to_midi_flow")
def _():
    # audioToMidi (basic-pitch ueber ONNX Runtime): Tonleiter bei 44,1 und
    # 48 kHz, Akkorde polyphon/melody/bass ohne Oberton-Geister, Bereich,
    # Mix als Quelle; addMidiFromAudio legt die Noten als MIDI-Clip in eine
    # Section (collect). Ohne ONNX Runtime/Modell: nur die Meldung.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-a2m-")
    scale_notes = [(p, 0.2 + i * 0.4, 0.38) for i, p in enumerate([60, 62, 64, 65, 67, 69, 71, 72])]
    s44 = os.path.join(d, "scale44.wav")
    make_notes_wav(s44, scale_notes, total=3.8)
    r = api("audioToMidi", file=s44)
    if r.get("ok") is False and ("tools/fetch_ml.sh" in r.get("error", "")):
        print("    skip audioToMidi (no ONNX Runtime/model: " + r["error"] + ")")
        return
    got = [(n["pitch"], n["start"]) for n in r.get("notes", [])]
    check(r.get("ok") is True and [p for p, _ in got] == [p for p, _, _ in scale_notes]
          and all(abs(s - e[1]) < 0.03 for (_, s), e in zip(got, scale_notes)), f"Tonleiter: {got}")
    check(r.get("lowest") == 60 and r.get("highest") == 72 and r.get("count") == 8 and all(60 <= n["velocity"] <= 127 for n in r["notes"]),
          f"Zusammenfassung: {r.get('lowest')} {r.get('highest')} {r.get('count')}")
    s48 = os.path.join(d, "scale48.wav")
    make_notes_wav(s48, scale_notes, rate=48000, total=3.8)
    check([n["pitch"] for n in api("audioToMidi", file=s48).get("notes", [])] == [60, 62, 64, 65, 67, 69, 71, 72], "48 kHz (Resampling)")
    r = api("audioToMidi", file=s44, start=1.0, end=2.5)
    # 64 klingt bei 1,0 s noch (Start 0,987) — sie beginnt am Bereichsanfang
    check([n["pitch"] for n in r.get("notes", [])] == [64, 65, 67, 69] and r["notes"][0]["start"] >= 1.0, f"Bereich in Dateisekunden: {r.get('notes')}")

    chord = os.path.join(d, "chord.wav")
    make_notes_wav(chord, [(60, 0.2, 1.5), (64, 0.2, 1.5), (67, 0.2, 1.5), (65, 1.9, 1.5), (69, 1.9, 1.5), (72, 1.9, 1.5)], total=3.6)
    poly = sorted(n["pitch"] for n in api("audioToMidi", file=chord).get("notes", []))
    check(poly == [60, 64, 65, 67, 69, 72], f"Akkorde ohne Oberton-Geister: {poly}")
    check([n["pitch"] for n in api("audioToMidi", file=chord, mode="melody").get("notes", [])] == [67, 72], "melody = Oberstimme")
    check([n["pitch"] for n in api("audioToMidi", file=chord, mode="bass", maxPitch=72).get("notes", [])] == [60, 65], "bass = Unterstimme")
    with_ghosts = api("audioToMidi", file=chord, keepHarmonics=True).get("count", 0)
    check(with_ghosts >= 6, f"keepHarmonics: {with_ghosts}")
    # Bass mit Oktav-Plucks (E1/E2 im Wechsel): die Einstimmen-Linie behaelt beide
    octs = os.path.join(d, "octaves.wav")
    make_notes_wav(octs, [(28 if i % 2 == 0 else 40, 0.2 + i * 0.3, 0.28) for i in range(10)], total=3.4)
    bl = [n["pitch"] for n in api("audioToMidi", file=octs, mode="bass").get("notes", [])]
    check(bl.count(28) >= 4 and bl.count(40) >= 4, f"Oktavspruenge im Bass bleiben: {bl}")
    # Gezupfte Melodie (Karplus-Strong, 96 BPM): jeder Ton klingt 0,25 s in
    # den naechsten — basic-pitch teilte ihn beim neuen Einsatz (in melody
    # gewann der hoehere Nachklang), der 7. Teilton kam als Note (A4 -> G7).
    # Polyphon und melody: genau die Melodie (Todo
    # 2026-11-23-audiotomidi-obertoene-gezupft; Melodie wie MELODY in
    # tools/short/make_melody.py)
    line = [(69, 1), (72, 1), (76, 1), (72, 1), (74, 1), (72, 1), (69, 2), (65, 1), (69, 1), (72, 1.5), (71, 0.5),
            (69, 2), (64, 1), (68, 1), (69, 1), (72, 1), (76, 1.5), (74, 0.5), (77, 1), (76, 1), (74, 1), (72, 1),
            (71, 1), (69, 1), (68, 1), (71, 1), (69, 3), (None, 1)]
    # +7: der letzte Ton (3 Schlaege) teilte sich mitten im Ausklang, ohne
    # dass ein anderer Ton einsetzt (Todo 2026-11-24-audiotomidi-teilung-im-ausklang)
    for tr in (0, 7):
        pluck = os.path.join(d, f"line{tr}.wav")
        make_pluck_melody(pluck, transpose=tr, melody=line)
        want = [p + tr for p, _ in line if p is not None]
        for mode in ("polyphonic", "melody"):
            ns = api("audioToMidi", file=pluck, bpm=96, mode=mode).get("notes", [])
            got = [n["pitch"] for n in ns]
            check(got == want, f"gezupft {tr:+d} {mode}: {len(got)} Noten {got}")
    # Suite-Melodie (make_pluck_melody), auch transponiert: ein Ton einen
    # Halbton neben dem Nachklang verlor seinen Einsatz (72 -> 71 kam spaet),
    # der Nachklang daneben wurde nicht angehaengt (Goertzel sah den Nachbarn),
    # tief gezupft kamen der 9. und 17. Teilton und Teilungen beim Abbruch des
    # Vortons (Todo 2026-11-23-audiotomidi-halbton-neben-nachklang)
    base = [69, 72, 76, 74, 72, 71, 69, 64, 67, 69, 71, 72, 71, 67, 69, 72, 76, 79, 77, 76, 74, 72, 71, 72, 71, 67, 64, 69]
    for tr in (0, -12, -5, 3, 7):
        pl = os.path.join(d, f"pluck{tr}.wav")
        make_pluck_melody(pl, tr)
        for mode in ("polyphonic", "melody"):
            got = [n["pitch"] for n in api("audioToMidi", file=pl, bpm=96, mode=mode).get("notes", [])]
            check(got == [p + tr for p in base], f"Suite-Melodie {tr:+d} {mode}: {len(got)} Noten {got}")
    for args, err in [({"file": chord, "mode": "beats"}, "mode must be polyphonic, melody, bass or drums"),
                      ({"file": chord, "minPitch": 80, "maxPitch": 70}, "need 0 <= minPitch <= maxPitch <= 127")]:
        r = api("audioToMidi", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")

    # Mix als Quelle, dann direkt in den Song
    check(api("treeSeed", dir=d, label="a2m").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=4).get("ok") is True, "4 s")
    check(api("addClip", track=0, file=s44, section="Section 1").get("ok") is True, "Tonleiter als Clip")
    r = api("audioToMidi", section="Section 1")
    check(r.get("source") == "mix" and [n["pitch"] for n in r.get("notes", [])] == [60, 62, 64, 65, 67, 69, 71, 72], f"Mix: {r.get('notes')}")
    check(api("addSection", name="M", length=4).get("ok") is True, "Section M")
    r = api("addMidiFromAudio", file=s44, insertSection="M")
    check(r.get("ok") is True and r.get("transcribed") == 8 and r.get("notes") == 8, f"addMidiFromAudio: {r}")
    name = api("state")["trackList"][r["track"]]["clips"][0]["name"]
    pitches = [n["pitch"] for n in api("clipPeaks", track=r["track"], name=name).get("notes", [])]
    check(pitches == [60, 62, 64, 65, 67, 69, 71, 72], f"MIDI-Clip in M: {pitches}")
    r = api("addMidiFromAudio", file=s44)
    check(r.get("ok") is False and r.get("error") == "need insertSection (the section to put the clip in)", f"ohne Ziel: {r}")
    api("treeClose")


@t("audio_to_midi_legato_flow")
def _():
    # audioToMidi/addMidiFromAudio {legato, bends, keepOctaves} und Velocity
    # aus dem Pegel (Todo 2026-10-18 Analyse, P3; Praxistest 1c: gehaltene
    # Toene zerfielen in Fragmente, der Glide fehlte) an Linien mit bekannter
    # Wahrheit: Vibrato-Dyaden, Staccato, 4OSC legato mit 80 ms Glide in
    # Halb- und Ganztonschritten, eine Linie ueber zwei Oktaven.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-a2m-legato-")
    held = os.path.join(d, "held.wav")
    make_voice(held, [(0.0, 2.0, 65), (0.0, 2.0, 69), (2.0, 2.0, 64), (2.0, 2.0, 67)], 4.5, vibrato=(40, 6))
    r = api("audioToMidi", file=held)
    if r.get("ok") is False and "tools/fetch_ml.sh" in r.get("error", ""):
        print("    skip audioToMidi (no ONNX Runtime/model: " + r["error"] + ")")
        return
    f4 = [n for n in r.get("notes", []) if n["pitch"] == 65]
    check(len(f4) >= 3 and "fragmentsMerged" not in r, f"ohne legato zerfaellt das gehaltene F4: {len(f4)}")
    r = api("audioToMidi", file=held, legato=True)
    held_notes = {n["pitch"]: n for n in r.get("notes", []) if n["pitch"] in (64, 65, 67, 69)}
    check(r.get("ok") is True and sorted(n["pitch"] for n in r["notes"] if n["pitch"] in (64, 65, 67, 69)) == [64, 65, 67, 69]
          and all(n["length"] >= 1.7 for n in held_notes.values()) and r.get("fragmentsMerged", 0) >= 5,
          f"legato: je Ton eine Note ueber ~2 s: {r.get('notes')} {r.get('fragmentsMerged')}")

    # Staccato bleibt staccato (der Pegel bricht zwischen den Noten ein);
    # Velocity aus dem Pegel: die zweite Haelfte liegt 12 dB tiefer
    line = [69, 72, 76, 72]
    loud, quiet, stacc = (os.path.join(d, k + ".wav") for k in ("loud", "quiet", "stacc"))
    make_voice(loud, [(i * 0.5, 0.15, m) for i, m in enumerate(line)], 4.5)
    make_voice(quiet, [(2.0 + i * 0.5, 0.15, m) for i, m in enumerate(line)], 4.5)
    mix_wavs(stacc, [(loud, 1.0), (quiet, 0.25)])
    r = api("audioToMidi", file=stacc, legato=True)
    ns = r.get("notes", [])
    vl = [n["velocity"] for n in ns if n["start"] < 1.9]
    vq = [n["velocity"] for n in ns if n["start"] > 1.9]
    check(len(ns) == 8 and r.get("legatoJoined") == 0 and all(n["length"] < 0.3 for n in ns), f"staccato bleibt kurz: {ns}")
    check(vl and vq and min(vl) >= 90 and 40 <= max(vq) <= 60, f"Velocity aus dem Pegel (-12 dB ~ 50): laut {vl}, leise {vq}")

    # 4OSC legato, 80 ms Glide (gleitet nur in Voice Mode legato bei
    # ueberlappenden Noten), Noten je Schlag bei 120 BPM
    check(api("treeSeed", dir=d, label="legato").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=5).get("ok") is True, "5 s")
    t = api("createTrack", type="midi", instrument="4OSC")
    check(api("setParameter", plugin=t["id"], settings={"Wave 1": "sawUp", "Voice Mode": "legato"}).get("ok") is True, "4OSC legato")
    check(api("setParameter", plugin=t["id"], reals={"Legato": 80}).get("ok") is True, "Glide 80 ms")
    melody = [64, 65, 67, 65, 64, 62, 64, 65]
    check(api("addMidiClip", track=t["index"], section="Section 1", startBeat=0, lengthBeats=9,
              notes=[{"pitch": p, "beat": i, "beats": 1.05, "velocity": 100} for i, p in enumerate(melody)]).get("ok") is True, "Linie")
    glide = os.path.join(d, "glide.wav")
    check(api("render", file=glide, section="Section 1", tail=1, force=True).get("ok") is True, "render")
    r = api("audioToMidi", file=glide, mode="melody")
    ns = r.get("notes", [])
    check([n["pitch"] for n in ns] == melody and all("bend" not in n for n in ns)
          and not all(a["start"] + a["length"] > b["start"] for a, b in zip(ns, ns[1:])), f"ohne legato: keine Ueberlappung: {ns}")
    r = api("audioToMidi", file=glide, mode="melody", legato=True, bends=True)
    ns = r.get("notes", [])
    check([n["pitch"] for n in ns] == melody and all(a["start"] + a["length"] > b["start"] for a, b in zip(ns, ns[1:])),
          f"legato: jede Note ueberlappt die naechste: {ns}")
    # F4 nach E4 (Halbton von unten) und E4 nach F4 (von oben): der Bend
    # beginnt um den Notenwechsel bei 0,5 / 2,0 s nahe -100 / +100 Cent und
    # kommt beim Ton an
    up, down = ns[1].get("bend") or [[0, 0]], ns[4].get("bend") or [[0, 0]]
    check(r.get("bentNotes", 0) >= 5 and 0.44 <= up[0][0] <= 0.53 and up[0][1] <= -80 and min(abs(c) for _, c in up) <= 5
          and 1.94 <= down[0][0] <= 2.03 and down[0][1] >= 80 and min(abs(c) for _, c in down) <= 5,
          f"bends: F4 {up[:4]}, E4 {down[:4]}, {r.get('bentNotes')}")
    check(abs(ns[1]["start"] - up[0][0]) < 0.002, f"die Note beginnt mit dem Glide: {ns[1]}")
    # describeVoice misst den Glide wie bends ab dem Beginn der Bewegung —
    # vorher zaehlte der gehaltene Teil des Tons davor mit (Halbton: 141 ms
    # bei 80 ms Portamento; Todo 2026-10-27-describevoice-glidems-zu-lang) —
    # und rechnet ihn auf den ganzen Tonschritt hoch: 4OSC gleitet linear in
    # der eingestellten Zeit, glideMs = Einstellung (Entscheidung Matthias
    # 2026-10-29; vorher 58 ms bei 80 ms). Toleranz: das Tempo kommt aus
    # wenigen Contour-Frames (11,6 ms; Halbton in 80 ms ~5 Frames), je Note
    # +-25 %, der Median ueber 6-7 Uebergaenge +-15 % (gemessen 80 ms: 79,
    # je Note 70-86; 150 ms: 154, je Note 138-157)
    glide150 = os.path.join(d, "glide150.wav")
    check(api("setParameter", plugin=t["id"], reals={"Legato": 150}).get("ok") is True, "Glide 150 ms")
    check(api("render", file=glide150, section="Section 1", tail=1, force=True).get("ok") is True, "render 150 ms")
    for f, knob in ((glide, 80), (glide150, 150)):
        v = api("describeVoice", file=f, bpm=120, firstDownbeat=0, detail=True)
        per = [int(n["glide"].split(" c / ")[1].split()[0]) for n in v.get("notes", []) if n.get("glide")]
        gm = v.get("voice", {}).get("glideMs") or 0
        check(len(per) >= 5 and all(abs(x - knob) <= 0.25 * knob for x in per) and abs(gm - knob) <= 0.15 * knob,
              f"glideMs ~ Portamento {knob} ms: {gm}, je Note {per}")
    check(api("addSection", name="M", length=5).get("ok") is True, "Section M")
    r = api("addMidiFromAudio", file=glide, mode="melody", legato=True, bends=True, insertSection="M")
    check(r.get("ok") is True and r.get("notes") == 8 and r.get("bendRange") == 2 and r.get("pitchBendPoints", 0) >= 10, f"addMidiFromAudio bends: {r}")
    cn = api("clipNotes", track=r.get("track"), name=r.get("name"))
    bendv = [c["value"] for c in cn.get("controllers", []) if c.get("controller") == "pitchBend"]
    check(len(bendv) == r.get("pitchBendPoints") and min(bendv) <= -3000 and max(bendv) >= 3000, f"Pitch-Bend im Clip (+-100 Cent = +-4096 bei 2 Halbtoenen): {cn.get('controllers', [])[:6]}")
    r = api("addMidiFromAudio", file=held, legato=True, bends=True, insertSection="M")
    check(r.get("ok") is True and "pitchBendPoints" not in r and any("pitch bends not written" in h for h in r.get("hints", [])),
          f"Dyaden: kein Pitch-Bend (ein Kanal): {r}")

    # keepOctaves (shape chords): jede Note in der Lage, in der sie klingt
    two = os.path.join(d, "two.wav")
    make_voice(two, [(i * 0.3, 0.31, m) for i, m in enumerate([48, 52, 55, 60, 64, 67, 72, 67, 64, 60, 55, 52, 48])], 4.5)
    folded = [n["pitch"] for n in api("audioToMidi", file=two, shape="chords", bpm=120, firstDownbeat=0).get("notes", [])]
    kept = [n["pitch"] for n in api("audioToMidi", file=two, shape="chords", bpm=120, firstDownbeat=0, keepOctaves=True).get("notes", [])]
    check(folded and max(folded) - min(folded) <= 12 and kept and min(kept) <= 50 and max(kept) >= 70,
          f"zwei Oktaven: gefaltet {folded}, keepOctaves {kept}")

    for args, err in [({"file": two, "shape": "chords", "legato": True}, "legato and bends apply to shape notes (chords already hold to the next hit)"),
                      ({"file": two, "mode": "drums", "bends": True}, "legato and bends need pitched notes (not mode drums)")]:
        r = api("audioToMidi", **args)
        check(r.get("ok") is False and r.get("error") == err, f"{err}: {r}")
    r = api("addMidiFromAudio", file=glide, bends=True, bendRange=0, insertSection="M")
    check(r.get("ok") is False and r.get("error", "").startswith("bendRange must be 1..48"), f"bendRange: {r}")
    api("treeClose")


@t("compare_reference_articulation_flow")
def _():
    # compareReference mit Artikulation und Tonhoehen mit Oktavlage (Todo
    # 2026-10-18 Analyse, P3; Praxistest 1c: Baender und Tonklassen waren
    # "nah", die Referenz spielte legato mit Glides, der Nachbau
    # Achtel-Staccato). Referenz: 4OSC legato mit 80 ms Glide; Nachbau:
    # dieselbe Linie kurz und eine Oktave tiefer; Gegenprobe gegen sich selbst.
    api("treeClose")
    d = tempfile.mkdtemp(prefix="dawd-cr-artic-")
    check(api("treeSeed", dir=d, label="artic").get("ok") is True, "seed")
    check(api("treeSettings", autoBranch=False).get("ok") is True, "autoBranch aus")
    check(api("updateSection", name="Section 1", length=9).get("ok") is True, "9 s")
    t = api("createTrack", type="midi", instrument="4OSC")
    check(api("setParameter", plugin=t["id"], settings={"Wave 1": "sawUp", "Voice Mode": "legato"}).get("ok") is True, "4OSC legato")
    check(api("setParameter", plugin=t["id"], reals={"Legato": 80}).get("ok") is True, "Glide 80 ms")
    melody = [64, 65, 67, 65, 64, 62, 64, 65] * 2
    c = api("addMidiClip", track=t["index"], section="Section 1", startBeat=0, lengthBeats=17,
            notes=[{"pitch": p, "beat": i, "beats": 1.05, "velocity": 100} for i, p in enumerate(melody)])
    check(c.get("ok") is True, f"Linie: {c}")
    ref = os.path.join(d, "ref.wav")
    check(api("render", file=ref, section="Section 1", tail=0.5, force=True).get("ok") is True, "Referenz")
    r = api("compareReference", file=ref, section="Section 1")
    if "articulation" not in r.get("reference", {}):
        print("    skip (no ONNX Runtime/model: no articulation)")
        return
    check(r.get("ok") is True and all(abs(r["diff"]["articulation"].get(k) or 0) <= 0.05 for k in ("legatoDelta", "glideShareDelta", "meanPitchDelta"))
          and not any(w in h for h in r["hints"] for w in ("articulation:", "glides into", "semitones")), f"Gegenprobe: {r['diff'].get('articulation')} {r['hints']}")
    ra = r["reference"]["articulation"]
    check(ra.get("legato", 0) >= 0.9 and ra.get("glideShare", 0) >= 0.5 and ra["pitch"]["octaves"] == [{"octave": "C4", "share": 1.0}]
          and ra["pitch"]["top"][0]["note"] in ("E4", "F4"), f"Referenz: legato, gleitet, Oktave 4: {ra}")

    api("setParameter", plugin=t["id"], settings={"Voice Mode": "poly"})
    check(api("setMidiNotes", track=c["track"], name=c["name"],
              notes=[{"pitch": p - 12, "beat": i, "beats": 0.3, "velocity": 100} for i, p in enumerate(melody)]).get("ok") is True, "Nachbau")
    r = api("compareReference", file=ref, section="Section 1")
    ma, ad = r["mix"]["articulation"], r["diff"]["articulation"]
    check(ma.get("legatoShare") == 0 and ad.get("legatoShareDelta", 0) <= -0.8 and ad.get("glideShareDelta", 0) <= -0.5
          and ad.get("meanPitchDelta") == -12 and ma["pitch"]["octaves"] == [{"octave": "C3", "share": 1.0}], f"Nachbau: {ma} {ad}")
    for words in ("articulation: reference legato", "reference glides into", "12.0 semitones lower than the reference (mean E3 vs F4) — about an octave"):
        check(any(words in h for h in r["hints"]), f"Hinweis '{words}': {r['hints']}")
    r = api("compareReference", file=ref, section="Section 1", articulation=False)
    check(r.get("ok") is True and "articulation" not in r["mix"] and "articulation" not in r["diff"], f"articulation: false: {r.get('diff')}")
    check(api("updateSection", name="Section 1", length=61).get("ok") is True, "61 s")
    r = api("compareReference", file=ref, section="Section 1")
    check(r.get("ok") is True and "articulation" not in r["mix"] and any("articulation not compared (longer than 60 s)" in h for h in r["hints"]),
          f"ueber 60 s ohne: {r.get('hints')}")
    api("treeClose")


def wav_rms_db(path, start=0.0, end=None):
    """RMS in dB einer WAV (16/24 Bit, alle Kanaele) im Bereich [start, end) s."""
    import math
    with wave.open(path) as f:
        rate, ch, sw, n = f.getframerate(), f.getnchannels(), f.getsampwidth(), f.getnframes()
        a = int(start * rate)
        b = n if end is None else min(n, int(end * rate))
        f.setpos(a)
        data = f.readframes(max(0, b - a))
    full = float(2 ** (8 * sw - 1))
    sq, cnt = 0.0, 0
    for i in range(0, len(data) - sw + 1, sw * 7):   # jede 7. Probe reicht
        v = int.from_bytes(data[i:i + sw], "little", signed=True) / full
        sq += v * v
        cnt += 1
    return 10 * math.log10(sq / max(1, cnt) + 1e-12)


